static void AddTimelineCompletionCandidates(
    std::vector<std::wstring>* candidates,
    const std::vector<std::wstring>& argsBefore)
{
    static const wchar_t* rootValues[] =
    {
        L"dashboard",
        L"reset",
        L"help"
    };

    do
    {
        if (argsBefore.size() <= 1)
        {
            AddCompletionCandidates(candidates, rootValues);
            break;
        }

        std::wstring sub = ToLower(argsBefore[1]);
        if (sub == L"help")
        {
            static const wchar_t* values[] =
            {
                L"advanced"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"ingest")
        {
            if (argsBefore.size() <= 2)
            {
                static const wchar_t* values[] =
                {
                    L"ti",
                    L"snapshot",
                    L"help"
                };
                AddCompletionCandidates(candidates, values);
            }
            else if (ToLower(argsBefore[2]) == L"ti")
            {
                static const wchar_t* values[] =
                {
                    L"recent",
                    L"all",
                    L"/limit"
                };
                AddCompletionCandidates(candidates, values);
            }
            else if (ToLower(argsBefore[2]) == L"snapshot")
            {
                static const wchar_t* values[] =
                {
                    L"baseline"
                };
                AddCompletionCandidates(candidates, values);
            }
            break;
        }

        if (sub == L"update")
        {
            static const wchar_t* values[] =
            {
                L"recent",
                L"all",
                L"/limit",
                L"/snapshot",
                L"/live",
                L"help"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"live")
        {
            static const wchar_t* values[] =
            {
                L"on",
                L"off",
                L"status",
                L"start",
                L"stop",
                L"clear",
                L"drain",
                L"/capacity",
                L"/limit",
                L"help"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"query")
        {
            static const wchar_t* values[] =
            {
                L"/source",
                L"/domain",
                L"/pid",
                L"/limit",
                L"/oldest",
                L"/newest"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"graph")
        {
            static const wchar_t* values[] =
            {
                L"/source",
                L"/domain",
                L"/image",
                L"/pid",
                L"/limit",
                L"/oldest",
                L"/newest"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"reconcile")
        {
            static const wchar_t* values[] =
            {
                L"snapshot",
                L"baseline",
                L"/source",
                L"/domain",
                L"/pid",
                L"/limit"
            };
            AddCompletionCandidates(candidates, values);
            break;
        }

        if (sub == L"export")
        {
            AddCompletionCandidate(candidates, L"/jsonl");
            break;
        }

        if (sub == L"dashboard")
        {
            break;
        }

        AddCompletionCandidates(candidates, rootValues);
    } while (false);
}

