static const wchar_t* FormatBoolText(bool value)
{
    return value ? L"yes" : L"no";
}

static WORD FormatBoolColor(bool value)
{
    return value ? KNDBG_COLOR_OK : KNDBG_COLOR_WARN;
}

static std::wstring FormatCiOptionsFlagText(const VbsCiOptionsInfo& info)
{
    std::wstring acc;
    auto append = [&](const wchar_t* token)
    {
        if (!acc.empty())
        {
            acc.append(L"|");
        }
        acc.append(token);
    };

    if (info.CodeIntegrityEnabled) append(L"CODEINTEGRITY_OPTION_ENABLED");
    if (info.TestSign)             append(L"TESTSIGN");
    if (info.UmciEnabled)          append(L"UMCI_ENABLED");
    if (info.UmciAuditMode)        append(L"UMCI_AUDITMODE_ENABLED");
    if (info.HvciEnforced)         append(L"HVCI_ENFORCED");
    if (info.UmciExclusionPaths)   append(L"UMCI_EXCLUSIONPATHS_ENABLED");
    if (info.TestBuild)            append(L"TEST_BUILD");
    if (info.PreproductionBuild)   append(L"PREPRODUCTION_BUILD");
    if (info.FlightBuild)          append(L"FLIGHT_BUILD");
    if (info.HvciStrictMode)       append(L"HVCI_STRICT_MODE");
    if (info.HvciDebugMode)        append(L"HVCI_DEBUG_MODE");

    return acc;
}

static void PrintCiOptionsBlock(const VbsCiOptionsInfo& info)
{
    PrintColoredText(L"[ci.options]", KNDBG_COLOR_TITLE);
    if (!info.Resolved)
    {
        std::wcout << L" status=unresolved\n";
        return;
    }

    std::wcout << L" source=" << info.SymbolSource;
    std::wcout << L" raw=0x" << std::hex << info.Raw << std::dec << L"\n";

    std::wstring flagsText = FormatCiOptionsFlagText(info);
    std::wcout << L"  flags=";
    if (flagsText.empty())
    {
        PrintColoredText(L"<none>", KNDBG_COLOR_DIM);
    }
    else
    {
        PrintColoredText(flagsText, KNDBG_COLOR_OK);
    }
    std::wcout << L"\n";

    std::wcout << L"  ci=" << FormatBoolText(info.CodeIntegrityEnabled)
               << L" testsign=" << FormatBoolText(info.TestSign)
               << L" umci=" << FormatBoolText(info.UmciEnabled)
               << L" hvci=" << FormatBoolText(info.HvciEnforced)
               << L" hvci_strict=" << FormatBoolText(info.HvciStrictMode)
               << L" hvci_debug=" << FormatBoolText(info.HvciDebugMode) << L"\n";
}

static void PrintHypervisorBlock(const VbsHypervisorInfo& info)
{
    PrintColoredText(L"[vbs.hypervisor]", KNDBG_COLOR_TITLE);
    std::wcout << L" present=";
    PrintColoredText(FormatBoolText(info.HypervisorPresent), FormatBoolColor(info.HypervisorPresent));
    if (!info.VendorSignature.empty())
    {
        std::wcout << L" vendor=\"" << info.VendorSignature << L"\"";
    }
    if (info.HvLeafBase != 0)
    {
        std::wcout << L" leaf_base=0x" << std::hex << info.HvLeafBase << std::dec;
    }
    if (info.HvFeaturesValid)
    {
        std::wcout << L" hv_hw_features=0x" << std::hex << info.HvHardwareFeatures << std::dec;
    }
    std::wcout << L"\n";
    std::wcout << L"  note: MBEC enablement requires IA32_VMX_PROCBASED_CTLS2 bit 22 (MSR read, kernel-only); inferred from HVCI enforcement instead.\n";
}

static void PrintVbsCoreBlock(const VbsScanResult& result)
{
    PrintColoredText(L"[vbs.core]", KNDBG_COLOR_TITLE);
    std::wcout << L" vbs_active=";
    PrintColoredText(FormatBoolText(result.VbsActive), FormatBoolColor(result.VbsActive));
    std::wcout << L" hvci_enforced=";
    PrintColoredText(FormatBoolText(result.CiOptions.HvciEnforced), FormatBoolColor(result.CiOptions.HvciEnforced));
    std::wcout << L" sk_loaded=";
    PrintColoredText(FormatBoolText(result.SecureKernelLoaded), FormatBoolColor(result.SecureKernelLoaded));
    std::wcout << L" skci=";
    PrintColoredText(FormatBoolText(result.SkciLoaded), FormatBoolColor(result.SkciLoaded));
    std::wcout << L"\n";

    if (result.HvlpVsmVtlCallVaResolved)
    {
        std::wcout << L"  " << result.HvlpVsmVtlCallVaSymbol << L"=" << HexTextWidth(result.HvlpVsmVtlCallVa, 16, true) << L"\n";
    }

    if (result.HvcallStubResolved)
    {
        std::wcout << L"  " << result.HvcallStubSymbol << L"=" << HexTextWidth(result.HvcallStubAddress, 16, true) << L"\n";
    }
}

static void PrintSecureKernelModules(const VbsScanResult& result)
{
    if (result.SecureKernelModules.empty())
    {
        PrintColoredText(L"[securekernel.modules]", KNDBG_COLOR_TITLE);
        std::wcout << L" count=0\n";
        return;
    }

    PrintColoredText(L"[securekernel.modules]", KNDBG_COLOR_TITLE);
    std::wcout << L" count=" << result.SecureKernelModules.size() << L"\n";
    for (const VbsModuleHit& module : result.SecureKernelModules)
    {
        std::wcout << L"  ";
        PrintColoredText(module.ImageName, KNDBG_COLOR_OK);
        std::wcout << L" base=" << HexTextWidth(module.Base, 16, true)
                   << L" size=0x" << std::hex << module.Size << std::dec << L"\n";
    }
}

static void PrintTrustletList(const VbsScanResult& result)
{
    PrintColoredText(L"[securekernel.trustlets]", KNDBG_COLOR_TITLE);
    std::wcout << L" count=" << result.Trustlets.size() << L"\n";
    for (const VbsTrustletInfo& t : result.Trustlets)
    {
        std::wcout << L"  ";
        PrintColoredText(HexTextWidth(t.Eprocess, 16, true), KNDBG_COLOR_ACCENT);
        std::wcout << L" pid=" << std::dec << t.ProcessId;
        if (!t.ImageName.empty())
        {
            std::wcout << L" image=\"";
            PrintColoredText(t.ImageName, KNDBG_COLOR_OK);
            std::wcout << L"\"";
        }
        if (t.HasSecureState)
        {
            std::wcout << L" secure_state=0x" << std::hex << t.SecureState << std::dec
                       << L" sk_in_process=" << FormatBoolText(t.SecureKernelInProcess);
        }
        else
        {
            std::wcout << L" secure_state=unknown";
        }
        std::wcout << L"\n";
    }
}

static void EmitVbsWarnings(const VbsScanResult& result)
{
    for (const std::wstring& warning : result.Warnings)
    {
        std::wcerr << L"!vbs warning: " << warning << L"\n";
    }
}

static bool PrepareVbsScan(
    VbsScanner::Options options,
    DeviceClient& device,
    SymbolEngine& symbols,
    VbsScanResult* result,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (!device.IsOpen())
        {
            if (error != nullptr)
            {
                *error = L"requires the KnLiveDbg.sys driver device to be open";
            }
            break;
        }

        if (symbols.Modules().empty())
        {
            if (!symbols.LoadKernelModules(error))
            {
                break;
            }
        }

        VbsScanner scanner(device, symbols);
        if (!scanner.Scan(options, result, error))
        {
            break;
        }

        ok = true;
    } while (false);

    return ok;
}

static void HandleVbsCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (args.size() >= 2 && HasHelpToken(args, 1))
        {
            PrintVbsHelp();
            break;
        }

        if (args.size() >= 2)
        {
            std::wcerr << L"usage: !vbs\n";
            PrintVbsHelp();
            break;
        }

        VbsScanner::Options options = {};
        options.Target = VbsScanner::Scope::Vbs;

        VbsScanResult result = {};
        std::wstring error;
        if (!PrepareVbsScan(options, device, symbols, &result, &error))
        {
            std::wcerr << L"!vbs failed: " << error << L"\n";
            EmitVbsWarnings(result);
            break;
        }

        EmitVbsWarnings(result);

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildVbsJson(result);
        }

        PrintVbsCoreBlock(result);
        PrintCiOptionsBlock(result.CiOptions);
        PrintHypervisorBlock(result.Hypervisor);
        PrintSecureKernelModules(result);
        PrintTrustletList(result);
    } while (false);
}

static void PrintCiPolicyBlock(const VbsScanResult& result)
{
    PrintColoredText(L"[ci.policy]", KNDBG_COLOR_TITLE);
    std::wcout << L" status=";
    if (result.CiOptions.Resolved && result.CiOptions.UmciEnabled)
    {
        PrintColoredText(L"UMCI-enforced", KNDBG_COLOR_OK);
    }
    else if (result.CiOptions.Resolved)
    {
        PrintColoredText(L"UMCI-disabled", KNDBG_COLOR_WARN);
    }
    else
    {
        PrintColoredText(L"unknown", KNDBG_COLOR_WARN);
    }
    if (result.CiOptions.Resolved)
    {
        std::wcout << L" testsign=" << FormatBoolText(result.CiOptions.TestSign)
                   << L" audit=" << FormatBoolText(result.CiOptions.UmciAuditMode)
                   << L" exclusion_paths=" << FormatBoolText(result.CiOptions.UmciExclusionPaths)
                   << L" hvci=" << FormatBoolText(result.CiOptions.HvciEnforced)
                   << L" hvci_strict=" << FormatBoolText(result.CiOptions.HvciStrictMode);
    }
    std::wcout << L"\n";
    std::wcout << L"  note: WDAC policy blob discovery requires private CI internals and is reserved for a follow-up milestone.\n";
}

static void HandleCiCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols)
{
    do
    {
        if (args.size() >= 2 && HasHelpToken(args, 1))
        {
            PrintCiHelp();
            break;
        }

        bool printOptions = true;
        bool printPolicy = true;
        if (args.size() >= 2)
        {
            if (!IsCiScopeName(args[1]))
            {
                std::wcerr << L"usage: !ci [options|policy]\n";
                PrintCiHelp();
                break;
            }
            std::wstring scope = ToLower(args[1]);
            if (scope == L"options")
            {
                printOptions = true;
                printPolicy = false;
            }
            else if (scope == L"policy")
            {
                printOptions = true;
                printPolicy = true;
            }
        }

        VbsScanner::Options options = {};
        options.Target = VbsScanner::Scope::Ci;

        VbsScanResult result = {};
        std::wstring error;
        if (!PrepareVbsScan(options, device, symbols, &result, &error))
        {
            std::wcerr << L"!ci failed: " << error << L"\n";
            EmitVbsWarnings(result);
            break;
        }

        EmitVbsWarnings(result);

        if (printOptions)
        {
            PrintCiOptionsBlock(result.CiOptions);
            PrintHypervisorBlock(result.Hypervisor);
        }

        if (printPolicy)
        {
            PrintCiPolicyBlock(result);
        }
    } while (false);
}

static void HandleSecureKernelCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols)
{
    do
    {
        if (args.size() >= 2 && HasHelpToken(args, 1))
        {
            PrintSecureKernelHelp();
            break;
        }

        if (args.size() >= 2)
        {
            std::wcerr << L"usage: !securekernel\n";
            PrintSecureKernelHelp();
            break;
        }

        VbsScanner::Options options = {};
        options.Target = VbsScanner::Scope::SecureKernel;

        VbsScanResult result = {};
        std::wstring error;
        if (!PrepareVbsScan(options, device, symbols, &result, &error))
        {
            std::wcerr << L"!securekernel failed: " << error << L"\n";
            EmitVbsWarnings(result);
            break;
        }

        EmitVbsWarnings(result);

        PrintSecureKernelModules(result);
        PrintTrustletList(result);
    } while (false);
}

static void PrintEtwHelp()
{
    std::wcout << L"!etw command:\n";
    std::wcout << L"  !etw loggers\n";
    std::wcout << L"  !etw logger <index|name-substring>\n";
    std::wcout << L"  !etw integrity\n";
    std::wcout << L"  !etw providers [/limit <n>]\n";
    std::wcout << L"  !etw ti-cross\n";
    std::wcout << L"\n";
    std::wcout << L"scopes:\n";
    std::wcout << L"  loggers    list every populated WMI_LOGGER_CONTEXT slot under nt!EtwpDebuggerData with name and GetCpuClock annotation\n";
    std::wcout << L"  logger     filter by slot index (decimal) or case-insensitive name substring\n";
    std::wcout << L"  integrity  decode the first instructions of canonical ETW/PMC dispatch functions and report trampoline / cross-module branch findings (modern InfinityHook variants)\n";
    std::wcout << L"  providers  heuristic provider candidates with unclassified nearby-pointer diagnostics (coverage incomplete by design)\n";
    std::wcout << L"  ti-cross   correlate active !ti subscription reception rate with silence / drop signals\n";
    std::wcout << L"\n";
    std::wcout << L"notes:\n";
    std::wcout << L"  Resolves nt!EtwpDebuggerData, walks the silo state when present, then resolves LoggerName and GetCpuClock through _WMI_LOGGER_CONTEXT PDB fields with documented fallbacks.\n";
    std::wcout << L"  In modern Windows GetCpuClock is a UINT32 mode tag dispatched internally; mode=Custom on Circular Kernel Context Logger is normal, not a hook indicator.\n";
    std::wcout << L"  !etw integrity disassembles each target's first 16 instructions and flags first-instruction jmp/int3/ud2, mov-imm64+jmp-reg trampolines, push-imm+ret trampolines, and cross-module branches whose targets lie outside any loaded kernel module.\n";
    std::wcout << L"  !etw providers never claims full ETW tree reconstruction; empty + incomplete means layout drift, not clean.\n";
    std::wcout << L"  !etw ti-cross is skipped when TI is not active; silence is only evaluated after a short start threshold.\n";
}

static void PrintNmiHelp()
{
    std::wcout << L"!nmi command:\n";
    std::wcout << L"  !nmi\n";
    std::wcout << L"  !nmi callbacks\n";
    std::wcout << L"\n";
    std::wcout << L"output:\n";
    std::wcout << L"  Singly-linked list of KNMI_HANDLER_CALLBACK nodes from nt!KiNmiCallbackListHead, with module/symbol annotation per callback.\n";
    std::wcout << L"\n";
    std::wcout << L"notes:\n";
    std::wcout << L"  Node layout is fixed: Next at 0x00, Callback at 0x08, Context at 0x10, Handle at 0x18.\n";
    std::wcout << L"  Callback targets outside any loaded kernel module are flagged as suspicious; the walker bounds iteration and detects cycles.\n";
}

static void PrintEtwLoggerRecord(const EtwLoggerRecord& record)
{
    PrintColoredText(L"[etw.logger]", KNDBG_COLOR_TITLE);
    std::wcout << L" slot=" << std::dec << record.Slot;
    std::wcout << L" context=" << HexTextWidth(record.ContextAddress, 16, true);
    if (!record.Name.empty())
    {
        std::wcout << L" name=\"";
        PrintColoredText(record.Name, KNDBG_COLOR_OK);
        std::wcout << L"\"";
    }
    if (record.Suspicious)
    {
        std::wcout << L" ";
        PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
    }
    std::wcout << L"\n";

    if (record.HasGetCpuClockRaw)
    {
        std::wcout << L"  ";
        PrintColoredText(L"getCpuClock", KNDBG_COLOR_ACCENT);
        std::wcout << L"=" << HexTextWidth(record.GetCpuClockRaw, 16, true);
        if (record.HasGetCpuClockMode)
        {
            std::wcout << L" mode=";
            PrintColoredText(record.GetCpuClockModeText, KNDBG_COLOR_OK);
            std::wcout << L"(" << std::dec << record.GetCpuClockMode << L")";
        }
        std::wcout << L"\n";
    }

    if (record.HasGetCpuClockCallback)
    {
        std::wcout << L"  ";
        PrintColoredText(L"callback", KNDBG_COLOR_ACCENT);
        std::wcout << L"=" << HexTextWidth(record.GetCpuClockCallback, 16, true);
        if (!record.GetCpuClockCallbackSource.empty())
        {
            std::wcout << L" source=" << record.GetCpuClockCallbackSource;
        }
        if (!record.GetCpuClockModule.empty())
        {
            std::wcout << L" module=";
            PrintColoredText(record.GetCpuClockModule, KNDBG_COLOR_OK);
        }
        if (!record.GetCpuClockSymbol.empty())
        {
            std::wcout << L" symbol=";
            PrintColoredText(record.GetCpuClockSymbol, KNDBG_COLOR_OK);
        }
        std::wcout << L"\n";
    }

    if (!record.Notes.empty())
    {
        std::wcout << L"  ";
        PrintColoredText(L"notes", KNDBG_COLOR_WARN);
        std::wcout << L"=" << record.Notes << L"\n";
    }
}

static void PrintNmiCallbackRecord(const NmiCallbackRecord& record)
{
    PrintColoredText(L"[nmi.callback]", KNDBG_COLOR_TITLE);
    std::wcout << L" slot=" << std::dec << record.Slot;
    std::wcout << L" node=" << HexTextWidth(record.NodeAddress, 16, true);
    if (record.Suspicious)
    {
        std::wcout << L" ";
        PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
    }
    std::wcout << L"\n";

    std::wcout << L"  ";
    PrintColoredText(L"callback", KNDBG_COLOR_ACCENT);
    std::wcout << L"=" << HexTextWidth(record.Callback, 16, true);
    if (!record.CallbackModule.empty())
    {
        std::wcout << L" module=";
        PrintColoredText(record.CallbackModule, KNDBG_COLOR_OK);
    }
    if (!record.CallbackSymbol.empty())
    {
        std::wcout << L" symbol=";
        PrintColoredText(record.CallbackSymbol, KNDBG_COLOR_OK);
    }
    std::wcout << L"\n";

    std::wcout << L"  context=" << HexTextWidth(record.Context, 16, true)
               << L" handle=" << HexTextWidth(record.Handle, 16, true) << L"\n";

    if (!record.Notes.empty())
    {
        std::wcout << L"  ";
        PrintColoredText(L"notes", KNDBG_COLOR_WARN);
        std::wcout << L"=" << record.Notes << L"\n";
    }
}

static void PrintEtwIntegrityRecord(const EtwIntegrityRecord& record)
{
    PrintColoredText(L"[etw.integrity]", KNDBG_COLOR_TITLE);
    std::wcout << L" target=";
    PrintColoredText(record.Symbol, KNDBG_COLOR_OK);

    const wchar_t* statusText = L"clean";
    WORD statusColor = KNDBG_COLOR_OK;
    if (!record.SymbolResolved)
    {
        statusText = L"unresolved";
        statusColor = KNDBG_COLOR_WARN;
    }
    else if (!record.BytesRead)
    {
        statusText = L"read-failed";
        statusColor = KNDBG_COLOR_WARN;
    }
    else if (!record.DecodeOk)
    {
        statusText = L"decode-failed";
        statusColor = KNDBG_COLOR_WARN;
    }
    else if (!record.Findings.empty())
    {
        statusText = L"SUSPICIOUS";
        statusColor = KNDBG_COLOR_FAIL;
    }

    std::wcout << L" status=";
    PrintColoredText(statusText, statusColor);
    std::wcout << L"\n";

    if (!record.Description.empty())
    {
        std::wcout << L"  description=" << record.Description << L"\n";
    }

    if (record.SymbolResolved)
    {
        std::wcout << L"  address=" << HexTextWidth(record.Address, 16, true);
        if (!record.OwningModule.empty())
        {
            std::wcout << L" module=";
            PrintColoredText(record.OwningModule, KNDBG_COLOR_OK);
        }
        std::wcout << L"\n";

        if (!record.HeadBytesHex.empty())
        {
            std::wcout << L"  head=" << record.HeadBytesHex << L"\n";
        }

        if (record.InstructionsAnalyzed > 0)
        {
            std::wcout << L"  instructions_analyzed=" << std::dec << record.InstructionsAnalyzed
                       << L" findings=" << record.Findings.size() << L"\n";
        }

        for (size_t i = 0; i < record.Findings.size(); ++i)
        {
            const EtwIntegrityFinding& finding = record.Findings[i];
            std::wcout << L"  ";
            PrintColoredText(L"finding[", KNDBG_COLOR_WARN);
            std::wcout << std::dec << i;
            PrintColoredText(L"]", KNDBG_COLOR_WARN);
            std::wcout << L" mnemonic=" << finding.Mnemonic
                       << L" instr_index=" << finding.InstructionIndex
                       << L" offset=0x" << std::hex << finding.InstructionOffset << std::dec
                       << L"\n    reason=" << finding.Reason << L"\n";
            if (finding.HasTarget)
            {
                std::wcout << L"    target=" << HexTextWidth(finding.Target, 16, true);
                if (!finding.TargetModule.empty())
                {
                    std::wcout << L" module=";
                    PrintColoredText(finding.TargetModule, KNDBG_COLOR_OK);
                }
                else
                {
                    std::wcout << L" module=";
                    PrintColoredText(L"<outside-loaded-modules>", KNDBG_COLOR_FAIL);
                }
                if (!finding.TargetSymbol.empty())
                {
                    std::wcout << L" symbol=";
                    PrintColoredText(finding.TargetSymbol, KNDBG_COLOR_OK);
                }
                std::wcout << L"\n";
            }
        }
    }
    else
    {
        std::wcout << L"  note: symbol not present in current kernel PDB; skipping\n";
    }
}

static void HandleEtwCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!etw requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }

        if (HasHelpToken(args, 1))
        {
            PrintEtwHelp();
            break;
        }

        EtwScanner::Options options = {};
        options.Target = EtwScanner::Scope::Loggers;

        size_t index = 1;
        if (index < args.size())
        {
            if (IsEtwScopeName(args[index]))
            {
                std::wstring scope = ToLower(args[index]);
                if (scope == L"loggers")
                {
                    options.Target = EtwScanner::Scope::Loggers;
                }
                else if (scope == L"logger")
                {
                    options.Target = EtwScanner::Scope::Logger;
                }
                else if (scope == L"integrity")
                {
                    options.Target = EtwScanner::Scope::Integrity;
                }
                else if (scope == L"providers")
                {
                    options.Target = EtwScanner::Scope::Providers;
                }
                else if (scope == L"ti-cross" || scope == L"ticross")
                {
                    options.Target = EtwScanner::Scope::TiCross;
                }
                ++index;
            }
            else
            {
                std::wcerr << L"usage: !etw [loggers|logger <index|name>|integrity|providers|ti-cross]\n";
                PrintEtwHelp();
                break;
            }
        }

        if (options.Target == EtwScanner::Scope::Logger)
        {
            if (index >= args.size())
            {
                std::wcerr << L"usage: !etw logger <index|name-substring>\n";
                break;
            }

            std::wstring filterValue = args[index];
            uint64_t parsedIndex = 0;
            if (ParseUnsigned(filterValue, 10, &parsedIndex) && parsedIndex < 0x100ull)
            {
                options.HasIndexFilter = true;
                options.IndexFilter = static_cast<uint32_t>(parsedIndex);
            }
            else
            {
                options.NameFilter = filterValue;
            }
            ++index;
        }

        if (options.Target == EtwScanner::Scope::Providers)
        {
            while (index < args.size())
            {
                if (ToLower(args[index]) == L"/limit" && index + 1 < args.size())
                {
                    uint64_t limitValue = 0;
                    if (!ParseUnsigned(args[index + 1], 10, &limitValue) ||
                        limitValue == 0 ||
                        limitValue > 256)
                    {
                        std::wcerr << L"!etw providers: /limit must be between 1 and 256\n";
                        break;
                    }
                    options.Limit = static_cast<uint32_t>(limitValue);
                    index += 2;
                    continue;
                }
                break;
            }
        }

        if (index < args.size() && options.Target != EtwScanner::Scope::Providers)
        {
            std::wcerr << L"!etw: unexpected extra argument \"" << args[index] << L"\"\n";
            break;
        }
        if (index < args.size() && options.Target == EtwScanner::Scope::Providers)
        {
            std::wcerr << L"!etw providers: unexpected extra argument \"" << args[index] << L"\"\n";
            break;
        }

        if (symbols.Modules().empty())
        {
            std::wstring loadError;
            if (!symbols.LoadKernelModules(&loadError))
            {
                std::wcerr << L"!etw failed: " << loadError << L"\n";
                break;
            }
        }

        EtwScanner scanner(device, symbols);

        if (options.Target == EtwScanner::Scope::TiCross)
        {
            EtwTiCrossInput input = {};
            TiSubscriber& ti = GetTiSubscriberInstance();
            input.TiActive = ti.IsActive();
            TiSubscriberStats stats = ti.SnapshotStats();
            input.EventsReceived = stats.EventsReceived;
            input.EventsKept = stats.EventsKept;
            input.EventsDropped = stats.EventsDropped;
            input.StartTickMs = stats.StartTickMs;
            input.LastEventTickMs = stats.LastEventTickMs;
            input.NowTickMs = GetTickCount64();
            uint8_t protection = 0;
            std::wstring gateError;
            input.PplAntimalware = CheckSelfIsPplAntimalware(device, symbols, &protection, &gateError);

            EtwTiCrossResult cross = {};
            std::wstring crossError;
            if (!EtwScanner::BuildTiCrossView(input, &cross, &crossError))
            {
                std::wcerr << L"!etw ti-cross failed: " << crossError << L"\n";
                break;
            }
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = BuildEtwTiCrossJson(cross);
            }

            PrintColoredText(L"etw ti-cross", KNDBG_COLOR_TITLE);
            std::wcout << L" status=";
            const WORD statusColor = cross.Suspicious
                ? KNDBG_COLOR_FAIL
                : (cross.Status == L"healthy" ? KNDBG_COLOR_OK : KNDBG_COLOR_WARN);
            PrintColoredText(cross.Status, statusColor);
            std::wcout << L" active=" << (cross.TiActive ? L"yes" : L"no")
                       << L" received=" << std::dec << cross.EventsReceived
                       << L" dropped=" << cross.EventsDropped
                       << L" elapsed=" << cross.ElapsedSeconds << L"s";
            if (cross.Suspicious)
            {
                std::wcout << L" ";
                PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
            }
            std::wcout << L"\n";
            if (!cross.Reason.empty())
            {
                std::wcout << L"  reason=" << cross.Reason << L"\n";
            }
            for (const std::wstring& note : cross.Notes)
            {
                std::wcout << L"  note: " << note << L"\n";
            }
            break;
        }

        if (options.Target == EtwScanner::Scope::Providers)
        {
            EtwProviderScanResult providerResult = {};
            std::wstring providerError;
            if (!scanner.ScanProviders(options, &providerResult, &providerError))
            {
                std::wcerr << L"!etw providers failed: " << providerError << L"\n";
                for (const std::wstring& warning : providerResult.Warnings)
                {
                    std::wcerr << L"!etw warning: " << warning << L"\n";
                }
                break;
            }
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = BuildEtwProvidersJson(providerResult);
            }
            for (const std::wstring& warning : providerResult.Warnings)
            {
                std::wcerr << L"!etw warning: " << warning << L"\n";
            }

            PrintColoredText(L"etw providers", KNDBG_COLOR_TITLE);
            std::wcout << L" count=" << std::dec << providerResult.Providers.size()
                       << L" suspicious=" << providerResult.SuspiciousCount
                       << L" coverage=" << (providerResult.CoverageComplete ? L"complete" : L"incomplete")
                       << L" usermodeProviders=" << providerResult.UserModeProviderCount;
            if (providerResult.AnchorResolved)
            {
                std::wcout << L" anchor=" << providerResult.AnchorSymbol
                           << L"@" << HexTextWidth(providerResult.AnchorAddress, 16, true);
            }
            if (providerResult.AnySuspicious)
            {
                std::wcout << L" ";
                PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
            }
            std::wcout << L"\n";

            for (const EtwProviderRecord& record : providerResult.Providers)
            {
                if (!record.Suspicious && providerResult.Providers.size() > 32)
                {
                    continue;
                }
                PrintColoredText(L"[etw.provider]", KNDBG_COLOR_TITLE);
                std::wcout << L" guid=" << record.GuidText
                           << L" entry=" << HexTextWidth(record.EntryAddress, 16, true)
                           << L" candidatePointer=" << HexTextWidth(record.EnableCallback, 16, true);
                if (!record.EnableCallbackModule.empty())
                {
                    std::wcout << L" module=" << record.EnableCallbackModule;
                }
                if (record.Suspicious)
                {
                    std::wcout << L" ";
                    PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
                }
                std::wcout << L"\n";
                if (!record.Notes.empty())
                {
                    std::wcout << L"  note: " << record.Notes << L"\n";
                }
            }
            break;
        }

        if (options.Target == EtwScanner::Scope::Integrity)
        {
            EtwIntegrityResult integrityResult = {};
            std::wstring integrityError;
            if (!scanner.ScanIntegrity(&integrityResult, &integrityError))
            {
                std::wcerr << L"!etw integrity failed: " << integrityError << L"\n";
                for (const std::wstring& warning : integrityResult.Warnings)
                {
                    std::wcerr << L"!etw warning: " << warning << L"\n";
                }
                break;
            }

            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = BuildEtwIntegrityJson(integrityResult);
            }

            for (const std::wstring& warning : integrityResult.Warnings)
            {
                std::wcerr << L"!etw warning: " << warning << L"\n";
            }

            size_t suspiciousCount = 0;
            size_t unresolvedCount = 0;
            size_t cleanCount = 0;
            for (const EtwIntegrityRecord& record : integrityResult.Records)
            {
                if (!record.SymbolResolved)
                {
                    ++unresolvedCount;
                }
                else if (!record.Findings.empty())
                {
                    ++suspiciousCount;
                }
                else if (record.BytesRead && record.DecodeOk)
                {
                    ++cleanCount;
                }
            }

            PrintColoredText(L"etw integrity", KNDBG_COLOR_TITLE);
            std::wcout << L" targets=" << std::dec << integrityResult.Records.size()
                       << L" clean=" << cleanCount
                       << L" suspicious=";
            PrintColoredText(std::to_wstring(suspiciousCount),
                             suspiciousCount == 0 ? KNDBG_COLOR_OK : KNDBG_COLOR_FAIL);
            std::wcout << L" unresolved=" << unresolvedCount << L"\n";

            for (const EtwIntegrityRecord& record : integrityResult.Records)
            {
                PrintEtwIntegrityRecord(record);
            }
            break;
        }

        EtwScanResult result = {};
        std::wstring error;
        if (!scanner.Scan(options, &result, &error))
        {
            std::wcerr << L"!etw failed: " << error << L"\n";
            for (const std::wstring& warning : result.Warnings)
            {
                std::wcerr << L"!etw warning: " << warning << L"\n";
            }
            break;
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!etw warning: " << warning << L"\n";
        }

        PrintColoredText(L"etw loggers", KNDBG_COLOR_TITLE);
        std::wcout << L"=" << result.Loggers.size();
        std::wcout << L" debuggerData=" << HexTextWidth(result.DebuggerDataAddress, 16, true);
        std::wcout << L" arraySource=" << result.LoggerArraySource;
        if (result.UsedSiloPath)
        {
            std::wcout << L" silo=" << HexTextWidth(result.SiloStateAddress, 16, true);
        }
        std::wcout << L" arrayBase=" << HexTextWidth(result.LoggerArrayBase, 16, true);
        std::wcout << L" layoutFromPdb=" << (result.LayoutFromPdb ? L"yes" : L"no");
        std::wcout << L" nameOffset=0x" << std::hex << result.LoggerNameOffset << std::dec;
        std::wcout << L" getCpuClockOffset=0x" << std::hex << result.GetCpuClockOffset << std::dec;
        if (result.NonCanonicalSlotCount > 0)
        {
            std::wcout << L" skippedSlots=" << std::dec << result.NonCanonicalSlotCount;
        }
        std::wcout << L"\n";

        for (const EtwLoggerRecord& record : result.Loggers)
        {
            PrintEtwLoggerRecord(record);
        }
    } while (false);
}

static void HandleNmiCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!nmi requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }

        if (HasHelpToken(args, 1))
        {
            PrintNmiHelp();
            break;
        }

        size_t index = 1;
        if (index < args.size())
        {
            if (!IsNmiScopeName(args[index]))
            {
                std::wcerr << L"usage: !nmi [callbacks]\n";
                PrintNmiHelp();
                break;
            }
            ++index;
        }

        if (index < args.size())
        {
            std::wcerr << L"!nmi: unexpected extra argument \"" << args[index] << L"\"\n";
            break;
        }

        if (symbols.Modules().empty())
        {
            std::wstring loadError;
            if (!symbols.LoadKernelModules(&loadError))
            {
                std::wcerr << L"!nmi failed: " << loadError << L"\n";
                break;
            }
        }

        NmiScanner scanner(device, symbols);
        NmiScanResult result = {};
        std::wstring error;
        if (!scanner.Scan(&result, &error))
        {
            std::wcerr << L"!nmi failed: " << error << L"\n";
            for (const std::wstring& warning : result.Warnings)
            {
                std::wcerr << L"!nmi warning: " << warning << L"\n";
            }
            break;
        }

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildNmiJson(result);
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!nmi warning: " << warning << L"\n";
        }

        PrintColoredText(L"nmi callbacks", KNDBG_COLOR_TITLE);
        std::wcout << L"=" << result.Callbacks.size();
        if (result.ListHeadResolved)
        {
            std::wcout << L" listHead=" << result.ListHeadSymbol;
            std::wcout << L"(" << HexTextWidth(result.ListHeadAddress, 16, true) << L")";
        }
        std::wcout << L"\n";

        for (const NmiCallbackRecord& record : result.Callbacks)
        {
            PrintNmiCallbackRecord(record);
        }
    } while (false);
}

static void PrintPayloadHelp()
{
    std::wcout << L"!payload command:\n";
    std::wcout << L"  !payload <address|symbol> [/disasm <n>] [/json <path>]\n";
    std::wcout << L"  !payload scan [/limit <n>] [/disasm <n>] [/json <path>]\n";
    std::wcout << L"\n";
    std::wcout << L"  Layer: hook-to-body. Follows function pointers that sit outside every\n";
    std::wcout << L"  loaded kernel module. This is how a cleaned kdmapper-style payload stays\n";
    std::wcout << L"  live: callbacks/SSDT/IDT/NMI/HAL/MSR/ETW/WFP/DPC/dispatch still jump to\n";
    std::wcout << L"  independent pages after the original driver image is gone. !mapper will\n";
    std::wcout << L"  not see that image. A quiet !payload scan means no scanned hook surface\n";
    std::wcout << L"  pointed off-module; it does not prove those pages are unused.\n";
    std::wcout << L"\n";
    std::wcout << L"  Each trace walks page tables, looks up SystemBigPoolInformation, probes\n";
    std::wcout << L"  for an intact or signature-wiped PE header, and disassembles the first\n";
    std::wcout << L"  instructions. No new driver IOCTL is used.\n";
    std::wcout << L"\n";
    std::wcout << L"options:\n";
    std::wcout << L"  scan           collect unbacked pointers first, then trace unique addresses.\n";
    std::wcout << L"  /limit <n>     cap unique traces (default 16, max 128). scan only.\n";
    std::wcout << L"  /disasm <n>    instructions to decode (default 16, max 32).\n";
    std::wcout << L"  /json <path>   write kn-live-dbg.payload.v1 JSON.\n";
    std::wcout << L"\n";
    std::wcout << L"  scan collects unbacked pointers from callbacks, SSDT, IDT, NMI, HAL,\n";
    std::wcout << L"  SYSCALL MSRs, ETW, WFP callouts, DPC/timer, driver dispatch, and firmware\n";
    std::wcout << L"  table handlers. A failed surface is a coverage warning, not a clean miss.\n";
    std::wcout << L"  scan drops present but non-executable off-module pointers (registry\n";
    std::wcout << L"  cookies/list links). Those are not hook bodies. Count them as filtered.\n";
    std::wcout << L"\n";
    std::wcout << L"examples:\n";
    std::wcout << L"  !payload fffffc0000123456\n";
    std::wcout << L"  !payload scan\n";
    std::wcout << L"  !payload scan /limit 32 /json .\\payload.json\n";
}

static void PrintMapperHelp()
{
    std::wcout << L"!mapper command:\n";
    std::wcout << L"  !mapper [all|unloaded|piddb|cihash] [/limit <n>] [/json <path>]\n";
    std::wcout << L"  !unloaded    alias for !mapper unloaded\n";
    std::wcout << L"  !piddb       alias for !mapper piddb\n";
    std::wcout << L"  !cihash      alias for !mapper cihash\n";
    std::wcout << L"\n";
    std::wcout << L"  Layer: bookkeeping remnants. Walks the three kernel ledgers a real\n";
    std::wcout << L"  NtLoadDriver / IopLoadDriver path writes, then a mapper often forgets\n";
    std::wcout << L"  or only half-wipes:\n";
    std::wcout << L"    unloaded  nt!MmUnloadedDrivers circular log\n";
    std::wcout << L"    piddb     nt!PiDDBCacheTable AVL cache\n";
    std::wcout << L"    cihash    ci!g_KernelHashBucketList (or nearby ci symbols)\n";
    std::wcout << L"    all       every surface (default)\n";
    std::wcout << L"\n";
    std::wcout << L"  This layer sees the signed BYOVD/exploit driver after it was loaded for\n";
    std::wcout << L"  real. The manually mapped payload was never in these lists, so a cleaned\n";
    std::wcout << L"  kdmapper run is expected to print leftover=0. leftover=0 means the\n";
    std::wcout << L"  ledgers look clean, not that no payload is mapped. Pair with !byovd\n";
    std::wcout << L"  (still-loaded vulnerable image), !kpage /pe (orphan pages), and\n";
    std::wcout << L"  !payload scan (hooks that still point at those pages).\n";
    std::wcout << L"\n";
    std::wcout << L"options:\n";
    std::wcout << L"  /limit <n>   keep leftover/suspicious records first, then truncate.\n";
    std::wcout << L"  /json <path> write kn-live-dbg.mapper.v1 JSON.\n";
    std::wcout << L"\n";
    std::wcout << L"  Missing symbols fail closed with an explicit coverage note. Unloaded\n";
    std::wcout << L"  ranges reused by another live image print as REUSED; the same image\n";
    std::wcout << L"  still mapped at that start prints as RELOAD (adjacent repeats coalesce\n";
    std::wcout << L"  as xN). STILL-X is only for an unloaded range that is still\n";
    std::wcout << L"  present+executable and not reused. CI/PiDDB names explained by\n";
    std::wcout << L"  MmUnloadedDrivers or dump_* crash-dump leftovers are EXPECTED and\n";
    std::wcout << L"  omitted from default output (kept in JSON). Other missing names print\n";
    std::wcout << L"  as STALE. Wiped names or a zero TimeDateStamp print as SUSPICIOUS.\n";
    std::wcout << L"  If PiDDB AVL does not validate, the walk falls back to PiDDBCacheList.\n";
    std::wcout << L"  !snapshot captures leftover-mapper only.\n";
    std::wcout << L"\n";
    std::wcout << L"examples:\n";
    std::wcout << L"  !mapper\n";
    std::wcout << L"  !mapper unloaded\n";
    std::wcout << L"  !piddb /json .\\piddb.json\n";
}

static void PrintKpageHelp()
{
    std::wcout << L"!kpage command:\n";
    std::wcout << L"  !kpage [/deep] [/wx] [/pe] [/session|/nosession] [/limit <n>] [/json <path>]\n";
    std::wcout << L"\n";
    std::wcout << L"  Layer: orphan executable pages. Walks the kernel half of the live CR3\n";
    std::wcout << L"  page tables and reports executable leaves that do not overlap any\n";
    std::wcout << L"  SystemModuleInformation range. This is the layer that can still see a\n";
    std::wcout << L"  kdmapper payload after PiDDB / MmUnloadedDrivers / ci hash were wiped:\n";
    std::wcout << L"  the image lives on independent pages that were never a loaded module.\n";
    std::wcout << L"  Use /pe to keep PE-like regions and /wx for W+X. A silent !kpage does\n";
    std::wcout << L"  not replace !payload scan: hooks can hide inside a live module via PTE\n";
    std::wcout << L"  remap. Adjacent same-permission pages are coalesced. Page-table self-map\n";
    std::wcout << L"  windows are skipped. Session-space hits stay low-risk unless W+X or PE.\n";
    std::wcout << L"  /pe uses a page-start PE probe (DOS e_lfanew only). Interior NT-header\n";
    std::wcout << L"  scans are for !pool pe, not leftover pages.\n";
    std::wcout << L"\n";
    std::wcout << L"options:\n";
    std::wcout << L"  /deep         also walk nt!MmPfnDatabase (expensive; not default).\n";
    std::wcout << L"  /wx           keep only effective W+X regions.\n";
    std::wcout << L"  /pe           keep only regions with a PE header probe hit.\n";
    std::wcout << L"  /session      include session-space hits (default).\n";
    std::wcout << L"  /nosession    drop session-space hits.\n";
    std::wcout << L"  /limit <n>    cap printed regions (default 64, max 512).\n";
    std::wcout << L"  /json <path>  write kn-live-dbg.kpage.v1 JSON.\n";
    std::wcout << L"\n";
    std::wcout << L"  /deep requires _MMPFN.PteAddress and MmPteBase from the PDB and is capped.\n";
    std::wcout << L"  Do not use /deep as the default scan. !snapshot does not run !kpage.\n";
    std::wcout << L"\n";
    std::wcout << L"examples:\n";
    std::wcout << L"  !kpage\n";
    std::wcout << L"  !kpage /wx /pe /limit 20\n";
    std::wcout << L"  !kpage /deep /nosession /json .\\kpage.json\n";
}

static void PrintPayloadTraceRecord(const PayloadTraceRecord& record)
{
    PrintColoredText(L"[payload]", KNDBG_COLOR_TITLE);
    std::wcout << L" " << HexTextWidth(record.Address, 16, true);
    std::wcout << L" class=";
    PrintColoredText(record.Classification, KNDBG_COLOR_ACCENT);
    std::wcout << L" risk=";
    PrintColoredText(
        record.Risk,
        record.Risk == L"high" ? KNDBG_COLOR_FAIL : (record.Risk == L"medium" ? KNDBG_COLOR_WARN : KNDBG_COLOR_DIM));
    if (!record.Source.empty())
    {
        std::wcout << L" source=" << record.Source;
    }
    std::wcout << L"\n";

    std::wcout << L"  module=";
    if (record.InLoadedModule)
    {
        PrintColoredText(record.ModuleName, KNDBG_COLOR_OK);
    }
    else
    {
        PrintColoredText(L"<non-image>", KNDBG_COLOR_WARN);
    }
    if (!record.SymbolName.empty())
    {
        std::wcout << L" symbol=" << record.SymbolName;
    }
    std::wcout << L"\n";

    std::wcout << L"  present=" << (record.Inspect.EffectivePresent ? L"yes" : L"no");
    std::wcout << L" W=" << (record.Inspect.EffectiveWritable ? L"1" : L"0");
    std::wcout << L" X=" << (record.Inspect.EffectiveExecutable ? L"1" : L"0");
    if (record.Inspect.TranslationSucceeded)
    {
        std::wcout << L" PA=" << HexTextWidth(record.Inspect.PhysicalAddress, 16, true);
    }
    if (record.Inspect.EffectivePresent &&
        record.Inspect.EffectiveWritable &&
        record.Inspect.EffectiveExecutable)
    {
        std::wcout << L" ";
        PrintColoredText(L"[W+X]", KNDBG_COLOR_FAIL);
    }
    std::wcout << L"\n";

    if (record.InBigPool)
    {
        std::wcout << L"  pool=" << HexTextWidth(record.PoolAddress, 16, true)
                   << L" size=0x" << std::hex << record.PoolSize << std::dec
                   << L" tag=" << LeftoverFormatTag(record.PoolTag)
                   << L" " << (record.PoolNonPaged ? L"NonPaged" : L"Paged") << L"\n";
    }
    else
    {
        std::wcout << L"  pool=<not in SystemBigPoolInformation>\n";
    }

    if (record.PeProbed && record.Pe.IsPe)
    {
        std::wcout << L"  pe=" << HexTextWidth(record.PeProbeAddress, 16, true)
                   << L" sections=" << record.Pe.NumberOfSections
                   << L" sizeOfImage=0x" << std::hex << record.Pe.SizeOfImage << std::dec;
        if (record.Pe.MzWiped || record.Pe.PeSignatureWiped || record.Pe.ELfanewMismatch)
        {
            std::wcout << L" ";
            PrintColoredText(L"WIPED", KNDBG_COLOR_FAIL);
        }
        std::wcout << L"\n";
    }

    if (!record.Notes.empty())
    {
        std::wcout << L"  notes=" << record.Notes << L"\n";
    }
    if (record.DisasmOk && !record.Disasm.Text.empty())
    {
        PrintColoredText(L"  [payload.disasm]", KNDBG_COLOR_TITLE);
        std::wcout << L"\n" << record.Disasm.Text;
        if (!record.Disasm.Text.empty() && record.Disasm.Text.back() != L'\n')
        {
            std::wcout << L"\n";
        }
    }
}

static bool ParseLeftoverJsonAndLimit(
    const std::vector<std::wstring>& args,
    size_t startIndex,
    uint32_t* limit,
    uint32_t* disasm,
    bool* deep,
    bool* wx,
    bool* pe,
    bool* includeSession,
    std::wstring* jsonPath,
    std::wstring* error)
{
    bool ok = true;

    for (size_t index = startIndex; index < args.size(); ++index)
    {
        const std::wstring opt = ToLower(args[index]);
        if (opt == L"/limit")
        {
            if (index + 1 >= args.size())
            {
                if (error != nullptr)
                {
                    *error = L"/limit requires a value";
                }
                ok = false;
                break;
            }
            uint64_t value = 0;
            if (!ParseUnsigned(args[index + 1], 0, &value) || value > 0xffffffffull)
            {
                if (error != nullptr)
                {
                    *error = L"invalid /limit";
                }
                ok = false;
                break;
            }
            if (limit != nullptr)
            {
                *limit = static_cast<uint32_t>(value);
            }
            ++index;
            continue;
        }
        if (opt == L"/disasm")
        {
            if (index + 1 >= args.size())
            {
                if (error != nullptr)
                {
                    *error = L"/disasm requires a value";
                }
                ok = false;
                break;
            }
            uint64_t value = 0;
            if (!ParseUnsigned(args[index + 1], 0, &value) || value == 0 || value > 32)
            {
                if (error != nullptr)
                {
                    *error = L"/disasm must be 1..32";
                }
                ok = false;
                break;
            }
            if (disasm != nullptr)
            {
                *disasm = static_cast<uint32_t>(value);
            }
            ++index;
            continue;
        }
        if (opt == L"/json")
        {
            if (index + 1 >= args.size())
            {
                if (error != nullptr)
                {
                    *error = L"/json requires a path";
                }
                ok = false;
                break;
            }
            if (jsonPath != nullptr)
            {
                *jsonPath = args[index + 1];
            }
            ++index;
            continue;
        }
        if (opt == L"/deep")
        {
            if (deep != nullptr)
            {
                *deep = true;
            }
            continue;
        }
        if (opt == L"/wx")
        {
            if (wx != nullptr)
            {
                *wx = true;
            }
            continue;
        }
        if (opt == L"/pe")
        {
            if (pe != nullptr)
            {
                *pe = true;
            }
            continue;
        }
        if (opt == L"/session")
        {
            if (includeSession != nullptr)
            {
                *includeSession = true;
            }
            continue;
        }
        if (opt == L"/nosession")
        {
            if (includeSession != nullptr)
            {
                *includeSession = false;
            }
            continue;
        }

        if (error != nullptr)
        {
            *error = L"unrecognised argument \"" + args[index] + L"\"";
        }
        ok = false;
        break;
    }

    return ok;
}

static void HandlePayloadCommand(
    const std::vector<std::wstring>& args,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!payload requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }
        if (HasHelpToken(args, 1))
        {
            PrintPayloadHelp();
            break;
        }

        bool scan = false;
        size_t optionIndex = 1;
        std::wstring addressText;
        if (args.size() >= 2 && ToLower(args[1]) == L"scan")
        {
            scan = true;
            optionIndex = 2;
        }
        else if (args.size() >= 2 && !IsSwitchLikeToken(args[1]))
        {
            addressText = args[1];
            optionIndex = 2;
        }
        else
        {
            std::wcerr << L"usage: !payload <address|symbol> | !payload scan\n";
            PrintPayloadHelp();
            break;
        }

        uint32_t limit = 16;
        uint32_t disasm = 16;
        std::wstring jsonPath;
        std::wstring parseError;
        if (!ParseLeftoverJsonAndLimit(
                args,
                optionIndex,
                &limit,
                &disasm,
                nullptr,
                nullptr,
                nullptr,
                nullptr,
                &jsonPath,
                &parseError))
        {
            std::wcerr << L"!payload: " << parseError << L"\n";
            break;
        }

        PayloadTracer tracer(device, symbols);
        PayloadTraceOptions options = {};
        options.DisasmInstructions = disasm;
        options.Limit = limit;
        options.ScanHooks = scan;

        PayloadTraceResult result = {};
        std::wstring error;
        if (scan)
        {
            std::wcout << L"!payload scan: sweeping hook surfaces for unbacked pointers...\n";
            if (!tracer.Scan(options, &result, &error))
            {
                std::wcerr << L"!payload scan failed: " << error << L"\n";
                break;
            }
        }
        else
        {
            uint64_t address = 0;
            if (!ParseAddressOrSymbol(symbols, state, addressText, &address, &parseError))
            {
                std::wcerr << L"!payload: failed to parse \"" << addressText << L"\": " << parseError << L"\n";
                break;
            }

            PayloadTraceRecord record = {};
            if (!tracer.TraceAddress(address, L"user", options, &record, &error))
            {
                std::wcerr << L"!payload failed: " << error << L"\n";
                break;
            }
            result.Records.push_back(record);
            result.Traced = 1;
        }

        const std::wstring json = BuildPayloadTraceJson(result);
        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = json;
        }
        if (!jsonPath.empty())
        {
            std::wstring writeError;
            if (!WriteUtf8TextFile(jsonPath, json, &writeError))
            {
                std::wcerr << L"!payload: failed to write JSON: " << writeError << L"\n";
            }
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!payload warning: " << warning << L"\n";
        }
        for (const std::wstring& note : result.CoverageNotes)
        {
            std::wcerr << L"!payload coverage: " << note << L"\n";
        }

        PrintColoredText(L"payload", KNDBG_COLOR_TITLE);
        if (scan)
        {
            std::wcout << L" scan hooks=" << result.HookPointersSeen
                       << L" unique=" << result.UniqueUnbacked
                       << L" traced=" << result.Traced
                       << L" filtered=" << result.FilteredLowRisk
                       << L" complete=" << (result.HookSweepComplete ? L"yes" : L"no");
            if (result.Incomplete)
            {
                std::wcout << L" ";
                PrintColoredText(L"incomplete", KNDBG_COLOR_WARN);
            }
            std::wcout << L"\n";
        }
        else
        {
            std::wcout << L" inspect\n";
        }

        for (const PayloadTraceRecord& record : result.Records)
        {
            PrintPayloadTraceRecord(record);
        }
    } while (false);
}

static void HandleMapperCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!mapper requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }
        if (HasHelpToken(args, 1))
        {
            PrintMapperHelp();
            break;
        }

        MapperScanOptions options = {};
        size_t optionIndex = 1;
        if (args.size() >= 2 && !IsSwitchLikeToken(args[1]))
        {
            const std::wstring scope = ToLower(args[1]);
            if (scope == L"all")
            {
                optionIndex = 2;
            }
            else if (scope == L"unloaded")
            {
                options.IncludePiddb = false;
                options.IncludeHash = false;
                optionIndex = 2;
            }
            else if (scope == L"piddb")
            {
                options.IncludeUnloaded = false;
                options.IncludeHash = false;
                optionIndex = 2;
            }
            else if (scope == L"cihash" || scope == L"hash")
            {
                options.IncludeUnloaded = false;
                options.IncludePiddb = false;
                optionIndex = 2;
            }
            else
            {
                std::wcerr << L"!mapper scope must be all, unloaded, piddb, or cihash\n";
                PrintMapperHelp();
                break;
            }
        }

        std::wstring jsonPath;
        std::wstring parseError;
        if (!ParseLeftoverJsonAndLimit(
                args,
                optionIndex,
                &options.Limit,
                nullptr,
                nullptr,
                nullptr,
                nullptr,
                nullptr,
                &jsonPath,
                &parseError))
        {
            std::wcerr << L"!mapper: " << parseError << L"\n";
            break;
        }

        MapperRemnantScanner scanner(device, symbols);
        MapperScanResult result = {};
        std::wstring error;
        if (!scanner.Scan(options, &result, &error))
        {
            std::wcerr << L"!mapper failed: " << error << L"\n";
            break;
        }

        const std::wstring json = BuildMapperJson(result);
        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = json;
        }
        if (!jsonPath.empty())
        {
            std::wstring writeError;
            if (WriteUtf8TextFile(jsonPath, json, &writeError))
            {
                std::wcout << L"!mapper json=" << jsonPath << L"\n";
            }
            else
            {
                std::wcerr << L"!mapper: failed to write JSON: " << writeError << L"\n";
            }
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!mapper warning: " << warning << L"\n";
        }
        for (const std::wstring& note : result.CoverageNotes)
        {
            std::wcerr << L"!mapper coverage: " << note << L"\n";
        }

        uint32_t piddbLeftover = 0;
        uint32_t hashLeftover = 0;
        for (const MapperPiddbRecord& record : result.Piddb)
        {
            if (record.Suspicious || (!record.InLoadedModules && !record.Expected))
            {
                ++piddbLeftover;
            }
        }
        for (const MapperHashRecord& record : result.HashEntries)
        {
            if (record.Suspicious || (!record.InLoadedModules && !record.Expected))
            {
                ++hashLeftover;
            }
        }

        PrintColoredText(L"mapper", KNDBG_COLOR_TITLE);
        std::wcout << L" suspicious=" << (result.AnySuspicious ? L"yes" : L"no");
        if (options.IncludeUnloaded)
        {
            std::wcout << L" unloaded=" << result.Unloaded.size()
                       << L"(" << (result.UnloadedComplete ? L"complete" : L"partial") << L")";
        }
        if (options.IncludePiddb)
        {
            std::wcout << L" piddb=" << result.Piddb.size()
                       << L"(" << (result.PiddbComplete ? L"complete" : L"partial");
            if (!result.PiddbWalkMode.empty())
            {
                std::wcout << L"/" << result.PiddbWalkMode;
            }
            std::wcout << L",leftover=" << piddbLeftover << L")";
        }
        if (options.IncludeHash)
        {
            std::wcout << L" hash=" << result.HashEntries.size()
                       << L"(" << (result.HashComplete ? L"complete" : L"partial")
                       << L",leftover=" << hashLeftover << L")";
        }
        std::wcout << L"\n";

        if (options.IncludeUnloaded)
        {
        for (const MapperUnloadedRecord& record : result.Unloaded)
        {
            PrintColoredText(L"[unloaded]", KNDBG_COLOR_TITLE);
            std::wcout << L" [" << record.Index << L"] ";
            if (record.Name.empty())
            {
                PrintColoredText(L"<unnamed>", KNDBG_COLOR_WARN);
            }
            else
            {
                std::wcout << record.Name;
            }
            std::wcout << L" start=" << HexTextWidth(record.StartAddress, 16, true)
                       << L" end=" << HexTextWidth(record.EndAddress, 16, true);
            if (record.RepeatCount > 1)
            {
                std::wcout << L" x" << record.RepeatCount;
            }
            if (record.SameImageReload)
            {
                std::wcout << L" ";
                PrintColoredText(L"RELOAD", KNDBG_COLOR_WARN);
            }
            else if (record.RangeReused)
            {
                std::wcout << L" ";
                PrintColoredText(L"REUSED", KNDBG_COLOR_WARN);
            }
            else if (record.StillExecutable)
            {
                std::wcout << L" ";
                PrintColoredText(L"STILL-X", KNDBG_COLOR_FAIL);
            }
            if (record.Suspicious)
            {
                std::wcout << L" ";
                PrintColoredText(L"SUSPICIOUS", KNDBG_COLOR_FAIL);
            }
            std::wcout << L"\n";
            if (!record.Notes.empty())
            {
                std::wcout << L"  notes=" << record.Notes << L"\n";
            }
        }
        }

        uint32_t piddbPrinted = 0;
        for (const MapperPiddbRecord& record : result.Piddb)
        {
            if ((record.InLoadedModules || record.Expected) && !record.Suspicious)
            {
                continue;
            }
            if (piddbPrinted >= 32)
            {
                std::wcout << L"  ... additional PiDDB leftovers omitted\n";
                break;
            }
            PrintColoredText(L"[piddb]", KNDBG_COLOR_TITLE);
            std::wcout << L" " << record.DriverName
                       << L" stamp=0x" << std::hex << record.TimeDateStamp << std::dec
                       << L" loaded=" << (record.InLoadedModules ? L"yes" : L"no") << L" ";
            PrintColoredText(
                record.Suspicious ? L"SUSPICIOUS" : (record.Expected ? L"EXPECTED" : L"STALE"),
                record.Suspicious ? KNDBG_COLOR_FAIL : KNDBG_COLOR_WARN);
            std::wcout << L"\n";
            if (!record.Notes.empty())
            {
                std::wcout << L"  notes=" << record.Notes << L"\n";
            }
            ++piddbPrinted;
        }

        uint32_t hashPrinted = 0;
        for (const MapperHashRecord& record : result.HashEntries)
        {
            if ((record.InLoadedModules || record.Expected) && !record.Suspicious)
            {
                continue;
            }
            if (hashPrinted >= 32)
            {
                std::wcout << L"  ... additional hash-bucket leftovers omitted\n";
                break;
            }
            PrintColoredText(L"[cihash]", KNDBG_COLOR_TITLE);
            std::wcout << L" " << record.DriverName
                       << L" loaded=" << (record.InLoadedModules ? L"yes" : L"no") << L" ";
            PrintColoredText(
                record.Suspicious ? L"SUSPICIOUS" : (record.Expected ? L"EXPECTED" : L"STALE"),
                record.Suspicious ? KNDBG_COLOR_FAIL : KNDBG_COLOR_WARN);
            std::wcout << L"\n";
            if (!record.Notes.empty())
            {
                std::wcout << L"  notes=" << record.Notes << L"\n";
            }
            ++hashPrinted;
        }
    } while (false);
}

static void HandleKpageCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!kpage requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }
        if (HasHelpToken(args, 1))
        {
            PrintKpageHelp();
            break;
        }

        OrphanKernelPageOptions options = {};
        options.IncludeSession = true;
        std::wstring jsonPath;
        std::wstring parseError;
        if (!ParseLeftoverJsonAndLimit(
                args,
                1,
                &options.Limit,
                nullptr,
                &options.DeepPfn,
                &options.WxOnly,
                &options.PeOnly,
                &options.IncludeSession,
                &jsonPath,
                &parseError))
        {
            std::wcerr << L"!kpage: " << parseError << L"\n";
            break;
        }

        if (options.DeepPfn)
        {
            std::wcout << L"!kpage: walking kernel page tables then MmPfnDatabase (/deep)...\n";
        }
        else
        {
            std::wcout << L"!kpage: walking kernel page tables for executable leaves outside modules...\n";
        }

        OrphanKernelPageScanner scanner(device, symbols);
        OrphanKernelPageResult result = {};
        std::wstring error;
        if (!scanner.Scan(options, &result, &error))
        {
            std::wcerr << L"!kpage failed: " << error << L"\n";
            break;
        }

        const std::wstring json = BuildOrphanKernelPageJson(result);
        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = json;
        }
        if (!jsonPath.empty())
        {
            std::wstring writeError;
            if (!WriteUtf8TextFile(jsonPath, json, &writeError))
            {
                std::wcerr << L"!kpage: failed to write JSON: " << writeError << L"\n";
            }
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!kpage warning: " << warning << L"\n";
        }
        for (const std::wstring& note : result.CoverageNotes)
        {
            std::wcerr << L"!kpage coverage: " << note << L"\n";
        }

        PrintColoredText(L"kpage", KNDBG_COLOR_TITLE);
        std::wcout << L" regions=" << result.Regions.size()
                   << L" leaves=" << result.ExecutableLeaves
                   << L" skippedModule=" << result.ModuleLeavesSkipped
                   << L" skippedSelfMap=" << result.SelfMapLeavesSkipped
                   << L" tables=" << result.TablePagesWalked
                   << L" walk=" << (result.PageWalkComplete ? L"complete" : L"partial");
        if (result.PfnWalkAttempted)
        {
            std::wcout << L" pfnExamined=" << result.PfnEntriesExamined
                       << L" pfnHits=" << result.PfnHits
                       << L" pfn=" << (result.PfnWalkComplete ? L"complete" : L"partial");
        }
        std::wcout << L"\n";

        for (const OrphanKernelPageRegion& region : result.Regions)
        {
            PrintColoredText(L"[kpage]", KNDBG_COLOR_TITLE);
            std::wcout << L" " << HexTextWidth(region.Start, 16, true)
                       << L"-" << HexTextWidth(region.End, 16, true)
                       << L" size=0x" << std::hex << region.Size << std::dec
                       << L" class=" << region.Classification
                       << L" risk=";
            PrintColoredText(
                region.Risk,
                region.Risk == L"high" ? KNDBG_COLOR_FAIL : (region.Risk == L"medium" ? KNDBG_COLOR_WARN : KNDBG_COLOR_DIM));
            if (region.Writable && region.Executable)
            {
                std::wcout << L" ";
                PrintColoredText(
                    L"[W+X]",
                    region.Risk == L"high" ? KNDBG_COLOR_FAIL : KNDBG_COLOR_WARN);
            }
            if (region.HasPe)
            {
                std::wcout << L" ";
                PrintColoredText(L"PE", KNDBG_COLOR_FAIL);
                std::wcout << L" sizeOfImage=0x" << std::hex << region.Pe.SizeOfImage
                           << L" nt=0x" << region.Pe.NtOffset << std::dec;
            }
            if (region.InBigPool)
            {
                std::wcout << L" pool=" << LeftoverFormatTag(region.PoolTag);
            }
            if (region.FromPfn)
            {
                std::wcout << L" pfn";
            }
            std::wcout << L"\n";
            if (!region.Notes.empty())
            {
                std::wcout << L"  notes=" << region.Notes << L"\n";
            }
        }
    } while (false);
}

static void PrintMinifilterHelp()
{
    std::wcout << L"!minifilter command:\n";
    std::wcout << L"  !minifilter [list] [/json <path>]\n";
    std::wcout << L"  !minifilter show <name|address> [/json <path>]\n";
    std::wcout << L"  !minifilter irp <name|address> <IRP_MJ_*> [/json <path>]\n";
    std::wcout << L"  !minifilter disable <name|address> <IRP_MJ_*|all> [/pre|/post|/both]\n";
    std::wcout << L"  !minifilter enable <name|address> <IRP_MJ_*|all> [/pre|/post|/both]\n";
    std::wcout << L"  !minifilter disable-all <name|address> [/pre|/post|/both]\n";
    std::wcout << L"  !minifilter enable-all <name|address> [/pre|/post|/both]\n";
    std::wcout << L"  !fltmgr is an alias for !minifilter\n";
    std::wcout << L"\n";
    std::wcout << L"  Walks fltmgr!FltGlobals frames, FLT_FILTER.Operations, and the live\n";
    std::wcout << L"  FLT_INSTANCE.CallbackNodes that FltMgr actually dispatches (PDB layout).\n";
    std::wcout << L"  list/show/irp are read-only. disable/enable write FLT_FILTER.Operations and\n";
    std::wcout << L"  replace live FLT_INSTANCE.CallbackNode Pre/Post with distinct CFG-valid\n";
    std::wcout << L"  thunks: Pre returns FLT_PREOP_SUCCESS_NO_CALLBACK (1), Post returns\n";
    std::wcout << L"  FLT_POSTOP_FINISHED_PROCESSING (0). A shared return-0 Pre is\n";
    std::wcout << L"  FLT_PREOP_SUCCESS_WITH_CALLBACK and drains FastIO to IRP. Do not write NULL\n";
    std::wcout << L"  (kCFG 0x139/0xa) and do not unlink CallbackLinks (corrupt list 0x139/0x3).\n";
    std::wcout << L"  disable saves the original pointers in this session so enable can restore them.\n";
    std::wcout << L"  disable <name> all and disable-all walk every registered slot and sweep any\n";
    std::wcout << L"  leftover original callbacks. enable-all restores every same-session backup.\n";
    std::wcout << L"\n";
    std::wcout << L"options:\n";
    std::wcout << L"  /pre /post /both  which callback to change (default both).\n";
    std::wcout << L"  /json <path>      write kn-live-dbg.minifilter.v1, minifilter-irp.v1, or minifilter-irp-batch.v1.\n";
    std::wcout << L"\n";
    std::wcout << L"  IRP majors accept IRP_MJ_CREATE, CREATE, directory_control, ioctl, 0x00, 0n12.\n";
    std::wcout << L"  all / * / every / IRP_MJ_ALL / disable-all / enable-all apply to every slot.\n";
    std::wcout << L"  Ambiguous filter names fail closed. Inbox names (WdFilter, FileInfo, ...) warn\n";
    std::wcout << L"  but are not blocked. disable/enable/disable-all/enable-all require 'write on'.\n";
    std::wcout << L"\n";
    std::wcout << L"examples:\n";
    std::wcout << L"  !minifilter\n";
    std::wcout << L"  !minifilter show UnionFS\n";
    std::wcout << L"  !minifilter irp UnionFS IRP_MJ_CREATE\n";
    std::wcout << L"  write on\n";
    std::wcout << L"  !minifilter disable UnionFS CREATE\n";
    std::wcout << L"  !minifilter disable UnionFS all\n";
    std::wcout << L"  !minifilter disable-all UnionFS\n";
    std::wcout << L"  !minifilter enable-all UnionFS\n";
}

static void PrintMinifilterSlot(const MinifilterIrpSlot& slot)
{
    PrintColoredText(L"[minifilter.irp]", KNDBG_COLOR_TITLE);
    std::wcout << L" " << slot.MajorName
               << L" mj=0x" << std::hex << slot.MajorFunction << std::dec
               << L" slot=" << slot.Index
               << L" entry=" << HexTextWidth(slot.Entry, 16, true);
    if (slot.Disabled)
    {
        std::wcout << L" ";
        PrintColoredText(L"DISABLED", KNDBG_COLOR_WARN);
    }
    std::wcout << L"\n";
    std::wcout << L"  pre=" << HexTextWidth(slot.Pre, 16, true);
    if (!slot.PreModule.empty())
    {
        std::wcout << L" module=";
        PrintColoredText(slot.PreModule, KNDBG_COLOR_OK);
    }
    else if (slot.Pre != 0)
    {
        std::wcout << L" module=";
        PrintColoredText(L"<non-image>", KNDBG_COLOR_WARN);
    }
    if (!slot.PreSymbol.empty())
    {
        std::wcout << L" symbol=" << slot.PreSymbol;
    }
    std::wcout << L"\n  post=" << HexTextWidth(slot.Post, 16, true);
    if (!slot.PostModule.empty())
    {
        std::wcout << L" module=";
        PrintColoredText(slot.PostModule, KNDBG_COLOR_OK);
    }
    else if (slot.Post != 0)
    {
        std::wcout << L" module=";
        PrintColoredText(L"<non-image>", KNDBG_COLOR_WARN);
    }
    if (!slot.PostSymbol.empty())
    {
        std::wcout << L" symbol=" << slot.PostSymbol;
    }
    std::wcout << L"\n";
}

static void PrintMinifilterFilter(const MinifilterFilterRecord& filter, bool verboseSlots)
{
    PrintColoredText(L"[minifilter]", KNDBG_COLOR_TITLE);
    std::wcout << L" " << (filter.Name.empty() ? L"<unnamed>" : filter.Name);
    if (!filter.Altitude.empty())
    {
        std::wcout << L" altitude=" << filter.Altitude;
    }
    std::wcout << L" frame=" << filter.FrameId
               << L" filter=" << HexTextWidth(filter.Filter, 16, true)
               << L" ops=" << filter.ActiveOperationCount << L"/" << filter.OperationCount;
    if (filter.LiveLayoutAvailable)
    {
        std::wcout << L" instances=" << filter.InstanceCount
                   << L" live=" << filter.LiveCallbackCount;
    }
    if (!filter.DriverModule.empty())
    {
        std::wcout << L" driver=";
        PrintColoredText(filter.DriverModule, KNDBG_COLOR_OK);
    }
    if (filter.WellKnownInbox)
    {
        std::wcout << L" ";
        PrintColoredText(L"inbox", KNDBG_COLOR_DIM);
    }
    std::wcout << L"\n";
    if (!filter.Notes.empty())
    {
        std::wcout << L"  notes=" << filter.Notes << L"\n";
    }
    if (verboseSlots)
    {
        for (const MinifilterIrpSlot& slot : filter.OperationsTable)
        {
            PrintMinifilterSlot(slot);
        }
    }
}

static void HandleMinifilterCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!minifilter requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }
        if (HasHelpToken(args, 1))
        {
            PrintMinifilterHelp();
            break;
        }

        std::wstring action = L"list";
        size_t index = 1;
        if (index < args.size() && !IsSwitchLikeToken(args[index]))
        {
            const std::wstring token = ToLower(args[index]);
            if (token == L"list" ||
                token == L"show" ||
                token == L"irp" ||
                token == L"disable" ||
                token == L"enable" ||
                token == L"disable-all" ||
                token == L"enable-all" ||
                token == L"status")
            {
                action = (token == L"status") ? L"irp" : token;
                ++index;
            }
            else
            {
                action = L"show";
            }
        }

        std::wstring specifier;
        std::wstring irpText;
        MinifilterIrpWhich which = MinifilterIrpWhich::Both;
        std::wstring jsonPath;
        bool parseOk = true;
        while (index < args.size())
        {
            const std::wstring opt = ToLower(args[index]);
            if (opt == L"/pre")
            {
                which = MinifilterIrpWhich::Pre;
                ++index;
                continue;
            }
            if (opt == L"/post")
            {
                which = MinifilterIrpWhich::Post;
                ++index;
                continue;
            }
            if (opt == L"/both")
            {
                which = MinifilterIrpWhich::Both;
                ++index;
                continue;
            }
            if (opt == L"/json")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!minifilter: /json requires a path\n";
                    parseOk = false;
                    break;
                }
                jsonPath = args[index + 1];
                index += 2;
                continue;
            }
            if (IsSwitchLikeToken(args[index]))
            {
                std::wcerr << L"!minifilter: unrecognised argument \"" << args[index] << L"\"\n";
                parseOk = false;
                break;
            }
            if (specifier.empty() && action != L"list")
            {
                specifier = args[index];
                ++index;
                continue;
            }
            if (irpText.empty() &&
                (action == L"irp" ||
                 action == L"disable" ||
                 action == L"enable"))
            {
                irpText = args[index];
                ++index;
                continue;
            }
            std::wcerr << L"!minifilter: unexpected extra argument \"" << args[index] << L"\"\n";
            parseOk = false;
            break;
        }
        if (!parseOk)
        {
            break;
        }

        if (action != L"list" && specifier.empty())
        {
            const bool needsIrp =
                action == L"irp" || action == L"disable" || action == L"enable";
            std::wcerr << L"usage: !minifilter " << action << L" <name|address>"
                       << (needsIrp ? L" <IRP_MJ_*|all>" : L"") << L"\n";
            PrintMinifilterHelp();
            break;
        }

        MinifilterIrpScanner scanner(device, symbols);
        MinifilterIrpScanResult scan = {};
        std::wstring error;

        if (action == L"list")
        {
            if (!scanner.Scan(&scan, &error))
            {
                std::wcerr << L"!minifilter failed: " << error << L"\n";
                break;
            }
            const std::wstring json = BuildMinifilterIrpJson(scan);
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = json;
            }
            if (!jsonPath.empty())
            {
                std::wstring writeError;
                if (!WriteUtf8TextFile(jsonPath, json, &writeError))
                {
                    std::wcerr << L"!minifilter: failed to write JSON: " << writeError << L"\n";
                }
            }
            for (const std::wstring& warning : scan.Warnings)
            {
                std::wcerr << L"!minifilter warning: " << warning << L"\n";
            }
            for (const std::wstring& note : scan.CoverageNotes)
            {
                std::wcerr << L"!minifilter coverage: " << note << L"\n";
            }
            PrintColoredText(L"minifilter", KNDBG_COLOR_TITLE);
            std::wcout << L" filters=" << scan.Filters.size()
                       << L" globals=" << scan.FltGlobalsSymbol
                       << L" complete=" << (scan.CoverageComplete ? L"yes" : L"no") << L"\n";
            for (const MinifilterFilterRecord& filter : scan.Filters)
            {
                PrintMinifilterFilter(filter, false);
            }
            break;
        }

        if (action == L"show")
        {
            MinifilterFilterRecord filter = {};
            if (!scanner.Show(specifier, &filter, &scan, &error))
            {
                std::wcerr << L"!minifilter failed: " << error << L"\n";
                break;
            }
            const std::wstring json = BuildMinifilterIrpJson(scan);
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = json;
            }
            if (!jsonPath.empty())
            {
                std::wstring writeError;
                if (!WriteUtf8TextFile(jsonPath, json, &writeError))
                {
                    std::wcerr << L"!minifilter: failed to write JSON: " << writeError << L"\n";
                }
            }
            PrintMinifilterFilter(filter, true);
            break;
        }

        MinifilterIrpAction irpAction = MinifilterIrpAction::Status;
        bool allSlots = false;
        if (action == L"disable-all")
        {
            irpAction = MinifilterIrpAction::Disable;
            allSlots = true;
            action = L"disable";
        }
        else if (action == L"enable-all")
        {
            irpAction = MinifilterIrpAction::Enable;
            allSlots = true;
            action = L"enable";
        }
        else if (action == L"disable")
        {
            irpAction = MinifilterIrpAction::Disable;
        }
        else if (action == L"enable")
        {
            irpAction = MinifilterIrpAction::Enable;
        }

        if (!allSlots && !irpText.empty() && IsMinifilterIrpAllToken(irpText))
        {
            allSlots = true;
        }

        if (allSlots)
        {
            if (irpAction != MinifilterIrpAction::Disable &&
                irpAction != MinifilterIrpAction::Enable)
            {
                std::wcerr << L"!minifilter: all is only valid for disable/enable\n";
                break;
            }

            MinifilterIrpBatchResult batch = {};
            if (!scanner.SetAllIrps(specifier, irpAction, which, &batch, &scan, &error))
            {
                std::wcerr << L"!minifilter failed: " << error << L"\n";
                break;
            }

            const std::wstring json = BuildMinifilterIrpBatchJson(batch);
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = json;
            }
            if (!jsonPath.empty())
            {
                std::wstring writeError;
                if (!WriteUtf8TextFile(jsonPath, json, &writeError))
                {
                    std::wcerr << L"!minifilter: failed to write JSON: " << writeError << L"\n";
                }
            }

            if (batch.WellKnownInbox)
            {
                std::wcerr << L"!minifilter warning: " << batch.FilterName
                           << L" looks like an inbox filter\n";
            }
            for (const std::wstring& failure : batch.Failures)
            {
                std::wcerr << L"!minifilter warning: " << failure << L"\n";
            }

            PrintColoredText(L"minifilter.change", KNDBG_COLOR_TITLE);
            std::wcout << L" " << (batch.FilterName.empty() ? L"<unnamed>" : batch.FilterName)
                       << L" ALL action=" << action
                       << L" changed=" << batch.Changed
                       << L" skipped=" << batch.Skipped
                       << L" failed=" << batch.Failed
                       << L" attempted=" << batch.Attempted
                       << L" live_nodes=" << batch.LiveNodesChanged;
            if (batch.LiveNodesFailed > 0)
            {
                std::wcout << L" live_failed=" << batch.LiveNodesFailed;
            }
            std::wcout << L"\n";
            for (const MinifilterIrpChange& change : batch.Changes)
            {
                if (!change.PreChanged && !change.PostChanged)
                {
                    continue;
                }
                std::wcout << L"  " << change.Before.MajorName
                           << L" pre " << HexTextWidth(change.Before.Pre, 16, true)
                           << L" -> " << HexTextWidth(change.After.Pre, 16, true)
                           << L" post " << HexTextWidth(change.Before.Post, 16, true)
                           << L" -> " << HexTextWidth(change.After.Post, 16, true)
                           << L" ";
                PrintColoredText(L"UPDATED", KNDBG_COLOR_WARN);
                std::wcout << L"\n";
            }
            break;
        }

        uint32_t major = 0;
        if (irpText.empty() || !ParseMinifilterIrpMajor(irpText, &major, &error))
        {
            std::wcerr << L"!minifilter: " << (error.empty() ? L"IRP major required (or all)" : error) << L"\n";
            break;
        }

        MinifilterIrpChange change = {};
        if (!scanner.SetIrp(specifier, major, irpAction, which, &change, &scan, &error))
        {
            std::wcerr << L"!minifilter failed: " << error << L"\n";
            break;
        }

        const std::wstring json = BuildMinifilterIrpChangeJson(change);
        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = json;
        }
        if (!jsonPath.empty())
        {
            std::wstring writeError;
            if (!WriteUtf8TextFile(jsonPath, json, &writeError))
            {
                std::wcerr << L"!minifilter: failed to write JSON: " << writeError << L"\n";
            }
        }

        if (change.WellKnownInbox && irpAction != MinifilterIrpAction::Status)
        {
            std::wcerr << L"!minifilter warning: " << change.FilterName
                       << L" looks like an inbox filter\n";
        }

        PrintColoredText(L"minifilter.change", KNDBG_COLOR_TITLE);
        std::wcout << L" " << (change.FilterName.empty() ? L"<unnamed>" : change.FilterName)
                   << L" " << change.Before.MajorName
                   << L" action=" << action << L"\n";
        std::wcout << L"  before pre=" << HexTextWidth(change.Before.Pre, 16, true)
                   << L" post=" << HexTextWidth(change.Before.Post, 16, true) << L"\n";
        std::wcout << L"  after  pre=" << HexTextWidth(change.After.Pre, 16, true)
                   << L" post=" << HexTextWidth(change.After.Post, 16, true);
        if (change.PreChanged || change.PostChanged || change.LiveNodesChanged > 0)
        {
            std::wcout << L" ";
            PrintColoredText(L"UPDATED", KNDBG_COLOR_WARN);
        }
        std::wcout << L" live_nodes=" << change.LiveNodesChanged;
        if (change.LiveNodesFailed > 0)
        {
            std::wcout << L" live_failed=" << change.LiveNodesFailed;
        }
        std::wcout << L"\n";
    } while (false);
}

static void PrintMsrCheckHelp()
{
    std::wcout << L"!msrcheck command:\n";
    std::wcout << L"  !msrcheck\n";
    std::wcout << L"\n";
    std::wcout << L"output:\n";
    std::wcout << L"  Reads the SYSCALL-configuration MSRs (IA32_LSTAR/CSTAR/STAR/FMASK/EFER) on every\n";
    std::wcout << L"  active processor in group 0 through the driver's read-only MSR primitive.\n";
    std::wcout << L"\n";
    std::wcout << L"checks:\n";
    std::wcout << L"  LSTAR must equal nt!KiSystemCall64; a mismatch, a per-CPU divergence, or an entry\n";
    std::wcout << L"  pointer outside the loaded kernel image is flagged as a possible SYSCALL hook.\n";
    std::wcout << L"  CSTAR is validated only when non-zero (it is unused on most Intel parts). STAR\n";
    std::wcout << L"  selectors and EFER bits are decoded for inspection.\n";
}

static void PrintMsrReadingRecord(const MsrReading& reading)
{
    PrintColoredText(L"[msr]", KNDBG_COLOR_TITLE);
    std::wcout << L" ";
    PrintColoredText(reading.MsrName, KNDBG_COLOR_ACCENT);

    if (reading.PerCpuValues.empty())
    {
        std::wcout << L" read-failed\n";
        return;
    }

    uint64_t value = reading.PerCpuValues.front();
    std::wcout << L"=" << HexTextWidth(value, 16, true);
    if (reading.Suspicious)
    {
        std::wcout << L" ";
        PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
    }
    std::wcout << L"\n";

    if (reading.IsPointer && (!reading.OwningModule.empty() || !reading.NearestSymbol.empty()))
    {
        std::wcout << L"  ";
        if (!reading.OwningModule.empty())
        {
            std::wcout << L"module=";
            PrintColoredText(reading.OwningModule, KNDBG_COLOR_OK);
            std::wcout << L" ";
        }
        if (!reading.NearestSymbol.empty())
        {
            std::wcout << L"symbol=";
            PrintColoredText(reading.NearestSymbol, KNDBG_COLOR_OK);
        }
        std::wcout << L"\n";
    }

    if (reading.MsrIndex == KNDBG_MSR_IA32_STAR)
    {
        uint32_t compatEip = static_cast<uint32_t>(value & 0xFFFFFFFFull);
        uint16_t syscallCsSs = static_cast<uint16_t>((value >> 32) & 0xFFFFull);
        uint16_t sysretCsSs = static_cast<uint16_t>((value >> 48) & 0xFFFFull);
        std::wcout << L"  syscall_cs_ss=" << HexTextWidth(syscallCsSs, 4, true)
                   << L" sysret_cs_ss=" << HexTextWidth(sysretCsSs, 4, true)
                   << L" compat_eip=" << HexTextWidth(compatEip, 8, true) << L"\n";
    }
    else if (reading.MsrIndex == KNDBG_MSR_IA32_EFER)
    {
        std::wcout << L"  SCE=" << ((value & 0x1ull) != 0 ? L"1" : L"0")
                   << L" LME=" << ((value & 0x100ull) != 0 ? L"1" : L"0")
                   << L" LMA=" << ((value & 0x400ull) != 0 ? L"1" : L"0")
                   << L" NXE=" << ((value & 0x800ull) != 0 ? L"1" : L"0") << L"\n";
    }

    if (reading.Divergent)
    {
        std::wcout << L"  per-cpu:";
        for (size_t i = 0; i < reading.PerCpuValues.size(); ++i)
        {
            std::wcout << L" cpu" << std::dec << i << L"=" << HexTextWidth(reading.PerCpuValues[i], 16, true);
        }
        std::wcout << L"\n";
    }

    if (!reading.Notes.empty())
    {
        std::wcout << L"  note: ";
        PrintColoredText(reading.Notes, KNDBG_COLOR_WARN);
        std::wcout << L"\n";
    }
}

static void HandleMsrCheckCommand(
    const std::vector<std::wstring>& args,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    do
    {
        if (!device.IsOpen())
        {
            std::wcerr << L"!msrcheck requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }

        if (HasHelpToken(args, 1))
        {
            PrintMsrCheckHelp();
            break;
        }

        if (args.size() > 1)
        {
            std::wcerr << L"!msrcheck: unexpected extra argument \"" << args[1] << L"\"\n";
            PrintMsrCheckHelp();
            break;
        }

        if (symbols.Modules().empty())
        {
            std::wstring loadError;
            if (!symbols.LoadKernelModules(&loadError))
            {
                std::wcerr << L"!msrcheck failed: " << loadError << L"\n";
                break;
            }
        }

        MsrScanner scanner(device, symbols);
        MsrScanResult result = {};
        std::wstring error;
        if (!scanner.Scan(&result, &error))
        {
            std::wcerr << L"!msrcheck failed: " << error << L"\n";
            for (const std::wstring& warning : result.Warnings)
            {
                std::wcerr << L"!msrcheck warning: " << warning << L"\n";
            }
            break;
        }

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildMsrJson(result);
        }

        for (const std::wstring& warning : result.Warnings)
        {
            std::wcerr << L"!msrcheck warning: " << warning << L"\n";
        }

        PrintColoredText(L"msr syscall-config", KNDBG_COLOR_TITLE);
        std::wcout << L" cpus=" << std::dec << result.ProcessorCount;
        if (result.AnySuspicious)
        {
            std::wcout << L" ";
            PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
        }
        std::wcout << L"\n";

        for (const MsrReading& reading : result.Readings)
        {
            PrintMsrReadingRecord(reading);
        }
    } while (false);
}

static void PrintCrCheckHelp()
{
    std::wcout << L"!cr command:\n";
    std::wcout << L"  !cr\n";
    std::wcout << L"\n";
    std::wcout << L"output:\n";
    std::wcout << L"  Reads CR0/CR4/CR8 on every active processor in group 0 through the driver's\n";
    std::wcout << L"  read-only control-register primitive.\n";
    std::wcout << L"\n";
    std::wcout << L"checks:\n";
    std::wcout << L"  CR0.WP must be 1 (kernel write-protect); WP=0 or any per-CPU divergence of CR0/CR4\n";
    std::wcout << L"  is flagged as suspicious. SMEP/SMAP/UMIP/LA57/CET/PKE bits in CR4 are decoded; SMEP\n";
    std::wcout << L"  or SMAP off is surfaced as a mitigation-weakened note (legacy CPUs may lack them).\n";
}

static void PrintCrReadingRecord(const CrReading& reading)
{
    PrintColoredText(L"[cr]", KNDBG_COLOR_TITLE);
    std::wcout << L" ";
    PrintColoredText(reading.Name, KNDBG_COLOR_ACCENT);

    if (reading.PerCpuValues.empty())
    {
        std::wcout << L" read-failed\n";
        return;
    }

    uint64_t value = reading.PerCpuValues.front();
    std::wcout << L"=" << HexTextWidth(value, 16, true);
    if (reading.Suspicious)
    {
        std::wcout << L" ";
        PrintColoredText(L"[SUSPICIOUS]", KNDBG_COLOR_FAIL);
    }
    std::wcout << L"\n";

    if (reading.Name == L"CR0")
    {
        std::wcout << L"  WP=" << ((value & (1ull << 16)) != 0 ? L"1" : L"0")
                   << L" PG=" << ((value & (1ull << 31)) != 0 ? L"1" : L"0")
                   << L" NE=" << ((value & (1ull << 5)) != 0 ? L"1" : L"0") << L"\n";
    }
    else if (reading.Name == L"CR4")
    {
        std::wcout << L"  SMEP=" << ((value & (1ull << 20)) != 0 ? L"1" : L"0")
                   << L" SMAP=" << ((value & (1ull << 21)) != 0 ? L"1" : L"0")
                   << L" UMIP=" << ((value & (1ull << 11)) != 0 ? L"1" : L"0")
                   << L" LA57=" << ((value & (1ull << 12)) != 0 ? L"1" : L"0")
                   << L" CET=" << ((value & (1ull << 23)) != 0 ? L"1" : L"0")
                   << L" PKE=" << ((value & (1ull << 22)) != 0 ? L"1" : L"0") << L"\n";
    }

    if (reading.Divergent)
    {
        std::wcout << L"  per-cpu:";
        for (size_t i = 0; i < reading.PerCpuValues.size(); ++i)
        {
            std::wcout << L" cpu" << std::dec << i << L"=" << HexTextWidth(reading.PerCpuValues[i], 16, true);
        }
        std::wcout << L"\n";
    }

    if (!reading.Notes.empty())
    {
        std::wcout << L"  note: ";
        PrintColoredText(reading.Notes, KNDBG_COLOR_WARN);
        std::wcout << L"\n";
    }
}

