static bool ParseIntegrityLimitOption(
    const std::wstring& value,
    uint32_t numberBase,
    uint32_t* limit,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (limit == nullptr)
        {
            break;
        }

        uint64_t parsed = 0;
        if (!ParseUnsigned(value, numberBase, &parsed) || parsed > 0xffffffffull)
        {
            if (error != nullptr)
            {
                *error = L"invalid limit: " + value;
            }
            break;
        }

        *limit = static_cast<uint32_t>(parsed);
        ok = true;
    } while (false);

    return ok;
}

