static bool ParseTimelineLimit(
    const std::wstring& text,
    size_t maxLimit,
    size_t* limit,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (limit == nullptr)
        {
            if (error != nullptr)
            {
                *error = L"invalid limit output";
            }
            break;
        }

        uint64_t parsed = 0;
        if (!ParseUnsigned(text, 10, &parsed) || parsed == 0 || parsed > maxLimit)
        {
            if (error != nullptr)
            {
                *error = L"limit must be 1.." + std::to_wstring(maxLimit);
            }
            break;
        }

        *limit = static_cast<size_t>(parsed);
        ok = true;
    } while (false);

    return ok;
}

struct TimelineUpdateOptions
{
    std::wstring Mode;
    size_t Limit = 0;
    bool IncludeLive = false;
};

static bool ParseTimelineUpdateOptions(
    const std::vector<std::wstring>& args,
    size_t first,
    TimelineUpdateOptions* options,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (options == nullptr)
        {
            if (error != nullptr)
            {
                *error = L"invalid update options output";
            }
            break;
        }

        TimelineUpdateOptions parsed = {};
        parsed.Mode = L"recent";
        parsed.Limit = 200;
        parsed.IncludeLive = false;

        size_t index = first;
        if (index < args.size() && !args[index].empty() && args[index][0] != L'/')
        {
            parsed.Mode = ToLower(args[index]);
            if (parsed.Mode == L"all")
            {
                parsed.Limit = 10000;
            }
            else if (parsed.Mode != L"recent")
            {
                if (error != nullptr)
                {
                    *error = L"mode must be recent or all";
                }
                break;
            }
            ++index;
        }

        while (index < args.size())
        {
            std::wstring option = ToLower(args[index]);
            if (option == L"/limit")
            {
                if (index + 1 >= args.size())
                {
                    if (error != nullptr)
                    {
                        *error = L"/limit requires a value";
                    }
                    break;
                }
                if (!ParseTimelineLimit(args[index + 1], 100000, &parsed.Limit, error))
                {
                    break;
                }
                index += 2;
                continue;
            }
            if (option == L"/snapshot")
            {
                ++index;
                continue;
            }
            if (option == L"/live")
            {
                parsed.IncludeLive = true;
                ++index;
                continue;
            }
            if (error != nullptr)
            {
                *error = L"unrecognised option: " + args[index];
            }
            break;
        }

        if (index < args.size())
        {
            break;
        }

        *options = parsed;
        ok = true;
    } while (false);

    return ok;
}

static void PrintTimelineEventLine(const TimelineEvent& event)
{
    PrintColoredText(L"[timeline]", KNDBG_COLOR_TITLE);
    std::wcout << L" id=" << event.EventId
               << L" source=" << event.Source
               << L" domain=" << event.Domain;

    if (event.ProcessId != 0)
    {
        std::wcout << L" pid=" << event.ProcessId;
    }
    if (event.TargetProcessId != 0)
    {
        std::wcout << L" target_pid=" << event.TargetProcessId;
    }
    if (!event.Risk.empty())
    {
        std::wcout << L" risk=" << event.Risk;
    }
    if (!event.Confidence.empty())
    {
        std::wcout << L" confidence=" << event.Confidence;
    }

    std::wcout << L" ";
    if (!event.TimestampUtc.empty())
    {
        std::wcout << event.TimestampUtc;
    }
    else if (event.TimestampFileTime != 0)
    {
        std::wcout << FormatTimestampLocal(event.TimestampFileTime);
    }
    else
    {
        std::wcout << L"<no-time>";
    }

    if (!event.Summary.empty())
    {
        std::wcout << L" " << event.Summary;
    }
    else if (!event.Entity.empty())
    {
        std::wcout << L" " << event.Entity;
    }
    std::wcout << L"\n";
}

