    std::wcout << L"  domains:";
    if (stats.ByDomain.empty())
    {
        std::wcout << L" <none>";
    }
    for (const auto& item : stats.ByDomain)
    {
        std::wcout << L" " << item.first << L"=" << item.second;
    }
