static std::wstring TimelineLiveEventTypeText(uint32_t type)
{
    std::wstring text = L"unknown";
    if (type == KNDBG_TIMELINE_EVENT_PROCESS_CREATE)
    {
        text = L"process-create";
    }
    else if (type == KNDBG_TIMELINE_EVENT_PROCESS_EXIT)
    {
        text = L"process-exit";
    }
    else if (type == KNDBG_TIMELINE_EVENT_IMAGE_LOAD)
    {
        text = L"image-load";
    }
    else if (type == KNDBG_TIMELINE_EVENT_THREAD_CREATE)
    {
        text = L"thread-create";
    }
    else if (type == KNDBG_TIMELINE_EVENT_THREAD_EXIT)
    {
        text = L"thread-exit";
    }
    return text;
}

static TimelineEvent BuildTimelineEventFromLiveEvent(const TimelineLiveEvent& live)
{
    TimelineEvent event = {};
    event.TimestampFileTime = live.Timestamp100ns;
    event.Source = L"kernel-live";
    if (live.Type == KNDBG_TIMELINE_EVENT_IMAGE_LOAD)
    {
        event.Domain = L"image";
    }
    else if (live.Type == KNDBG_TIMELINE_EVENT_THREAD_CREATE ||
             live.Type == KNDBG_TIMELINE_EVENT_THREAD_EXIT)
    {
        event.Domain = L"thread";
    }
    else
    {
        event.Domain = L"process";
    }
    event.Action = TimelineLiveEventTypeText(live.Type);
    event.ProcessId = live.ProcessId;
    event.ThreadId = live.ThreadId;
    event.Entity = live.ImagePath;
    if (event.Entity.empty())
    {
        if (event.Domain == L"thread" && live.ThreadId != 0)
        {
            event.Entity = L"pid:" + std::to_wstring(live.ProcessId) +
                L" tid:" + std::to_wstring(live.ThreadId);
        }
        else
        {
            event.Entity = L"pid:" + std::to_wstring(live.ProcessId);
        }
    }
    event.Summary = event.Action + L" pid=" + std::to_wstring(live.ProcessId);
    if (live.ThreadId != 0 && event.Domain == L"thread")
    {
        event.Summary += L" tid=" + std::to_wstring(live.ThreadId);
    }
    if (event.Domain == L"thread" && live.CreatorProcessId != 0)
    {
        event.Summary += L" creator_pid=" + std::to_wstring(live.CreatorProcessId);
        event.Evidence[L"creator_pid"] = std::to_wstring(live.CreatorProcessId);
        event.Evidence[L"source_pid"] = std::to_wstring(live.CreatorProcessId);
        if (live.CreatorThreadId != 0)
        {
            event.Summary += L" creator_tid=" + std::to_wstring(live.CreatorThreadId);
            event.Evidence[L"creator_tid"] = std::to_wstring(live.CreatorThreadId);
        }
        if (live.CreatorProcessId != 0 && live.CreatorProcessId != live.ProcessId)
        {
            event.Risk = L"warning";
            event.Evidence[L"remote_thread"] = L"true";
            event.Evidence[L"target_pid"] = std::to_wstring(live.ProcessId);
            event.Evidence[L"cross_process_operation"] = L"createremotethread";
            event.Evidence[L"analysis_family"] = L"cross-process";
            event.Evidence[L"timeline_category"] = L"cross-process";
        }
    }
    if (live.ParentProcessId != 0)
    {
        event.Summary += L" parent_pid=" + std::to_wstring(live.ParentProcessId);
        event.Evidence[L"parent_pid"] = std::to_wstring(live.ParentProcessId);
    }
    if (!live.ImagePath.empty())
    {
        event.Summary += L" image=" + live.ImagePath;
        event.Evidence[L"image_path"] = live.ImagePath;
    }
    if (live.ImageBase != 0)
    {
        event.Evidence[L"image_base"] = HexTextWidth(live.ImageBase, 16, true);
    }
    if (live.ImageSize != 0)
    {
        event.Evidence[L"image_size"] = HexTextWidth(live.ImageSize, 16, true);
    }
    if (live.FileObject != 0)
    {
        event.Evidence[L"file_object"] = HexTextWidth(live.FileObject, 16, true);
    }
    if (event.Risk.empty())
    {
        event.Risk = L"info";
    }
    event.Confidence = L"kernel-callback";
    event.Evidence[L"sequence"] = std::to_wstring(live.Sequence);
    event.Evidence[L"type"] = std::to_wstring(live.Type);
    if (live.ThreadId != 0)
    {
        event.Evidence[L"tid"] = std::to_wstring(live.ThreadId);
    }
    return event;
}

static void PrintTimelineLiveStatus(const TimelineLiveStatus& status)
{
    uint32_t pressure = 0;
    if (status.Capacity != 0)
    {
        pressure = static_cast<uint32_t>(
            std::min<uint64_t>(100, (static_cast<uint64_t>(status.Count) * 100ull) / status.Capacity));
    }

    PrintColoredText(L"[timeline.live]", KNDBG_COLOR_TITLE);
    std::wcout << L" active=" << ((status.Flags & KNDBG_TIMELINE_STATUS_ACTIVE) != 0 ? L"yes" : L"no")
               << L" process_cb=" << ((status.Flags & KNDBG_TIMELINE_STATUS_PROCESS_CALLBACK) != 0 ? L"yes" : L"no")
               << L" image_cb=" << ((status.Flags & KNDBG_TIMELINE_STATUS_IMAGE_CALLBACK) != 0 ? L"yes" : L"no")
               << L" thread_cb=" << ((status.Flags & KNDBG_TIMELINE_STATUS_THREAD_CALLBACK) != 0 ? L"yes" : L"no")
               << L" capacity=" << status.Capacity
               << L" queued=" << status.Count
               << L" pressure=" << pressure << L"%"
               << L" dropped=" << status.Dropped
               << L" next_sequence=" << status.NextSequence << L"\n";
}

struct TimelineAutoDrainSnapshot
{
    bool Running = false;
    uint64_t Batches = 0;
    uint64_t Events = 0;
    uint64_t Added = 0;
    uint64_t Errors = 0;
    std::wstring LastUtc;
    std::wstring LastError;
};

static std::mutex g_TimelineLiveIoMutex;

static bool QueryTimelineLiveStatus(
    DeviceClient* device,
    TimelineLiveStatus* status,
    std::wstring* error)
{
    bool ok = false;
    std::lock_guard<std::mutex> lock(g_TimelineLiveIoMutex);

    do
    {
        if (device == nullptr || !device->IsOpen())
        {
            if (error != nullptr)
            {
                *error = L"driver device is not open";
            }
            break;
        }
        ok = device->QueryTimelineStatus(status, error);
    } while (false);

    return ok;
}

static bool ControlTimelineLive(
    DeviceClient* device,
    uint32_t action,
    uint32_t capacity,
    std::wstring* error)
{
    bool ok = false;
    std::lock_guard<std::mutex> lock(g_TimelineLiveIoMutex);

    do
    {
        if (device == nullptr || !device->IsOpen())
        {
            if (error != nullptr)
            {
                *error = L"driver device is not open";
            }
            break;
        }
        ok = device->ControlTimeline(action, capacity, error);
    } while (false);

    return ok;
}

static bool DrainTimelineLiveEvents(
    DeviceClient* device,
    uint32_t maxEvents,
    std::vector<TimelineLiveEvent>* events,
    TimelineLiveStatus* status,
    std::wstring* error)
{
    bool ok = false;
    std::lock_guard<std::mutex> lock(g_TimelineLiveIoMutex);

    do
    {
        if (device == nullptr || !device->IsOpen())
        {
            if (error != nullptr)
            {
                *error = L"driver device is not open";
            }
            break;
        }
        ok = device->DrainTimelineEvents(maxEvents, events, status, error);
    } while (false);

    return ok;
}

class TimelineAutoDrainWorker
{
public:
    ~TimelineAutoDrainWorker()
    {
        Stop();
    }

    bool Start(DebuggerState* state, DeviceClient* device)
    {
        bool ok = false;
        std::lock_guard<std::mutex> lock(ControlMutex);

        do
        {
            if (state == nullptr || device == nullptr || !device->IsOpen())
            {
                break;
            }

            if (Running.load() && Thread.joinable())
            {
                ok = true;
                break;
            }

            if (Thread.joinable())
            {
                StopRequested = true;
                Thread.join();
            }

            {
                std::lock_guard<std::mutex> statsLock(StatsMutex);
                Batches = 0;
                Events = 0;
                Added = 0;
                Errors = 0;
                LastUtc.clear();
                LastError.clear();
            }

            StopRequested = false;
            Running = true;
            Thread = std::thread(&TimelineAutoDrainWorker::WorkerLoop, this, state, device);
            ok = true;
        } while (false);

        return ok;
    }

    void Stop()
    {
        std::thread worker;
        {
            std::lock_guard<std::mutex> lock(ControlMutex);
            StopRequested = true;
            if (Thread.joinable())
            {
                worker = std::move(Thread);
            }
        }

        if (worker.joinable())
        {
            worker.join();
        }
        Running = false;
    }

    bool IsRunning() const
    {
        return Running.load();
    }

    TimelineAutoDrainSnapshot Snapshot() const
    {
        TimelineAutoDrainSnapshot snapshot = {};
        snapshot.Running = Running.load();
        std::lock_guard<std::mutex> lock(StatsMutex);
        snapshot.Batches = Batches;
        snapshot.Events = Events;
        snapshot.Added = Added;
        snapshot.Errors = Errors;
        snapshot.LastUtc = LastUtc;
        snapshot.LastError = LastError;
        return snapshot;
    }

private:
    void WorkerLoop(DebuggerState* state, DeviceClient* device)
    {
        do
        {
            while (!StopRequested.load() && !g_StopRequested.load())
            {
                std::vector<TimelineLiveEvent> liveEvents;
                TimelineLiveStatus drainStatus = {};
                std::wstring error;
                if (!DrainTimelineLiveEvents(device, 256, &liveEvents, &drainStatus, &error))
                {
                    RecordError(error);
                    break;
                }

                std::vector<TimelineEvent> events;
                events.reserve(liveEvents.size());
                for (const TimelineLiveEvent& item : liveEvents)
                {
                    events.push_back(BuildTimelineEventFromLiveEvent(item));
                }

                TimelineIngestResult result = state->Timeline.IngestEvents(events);
                RecordDrain(liveEvents.size(), result.Added);

                for (size_t i = 0; i < 5; ++i)
                {
                    if (StopRequested.load() || g_StopRequested.load())
                    {
                        break;
                    }
                    std::this_thread::sleep_for(std::chrono::milliseconds(100));
                }
            }
        } while (false);

        Running = false;
    }

    void RecordDrain(size_t drained, uint64_t added)
    {
        std::lock_guard<std::mutex> lock(StatsMutex);
        ++Batches;
        Events += drained;
        Added += added;
        LastUtc = SnapshotCurrentUtcTimestamp();
        LastError.clear();
    }

    void RecordError(const std::wstring& error)
    {
        std::lock_guard<std::mutex> lock(StatsMutex);
        ++Errors;
        LastUtc = SnapshotCurrentUtcTimestamp();
        LastError = error;
    }

    mutable std::mutex ControlMutex;
    mutable std::mutex StatsMutex;
    std::thread Thread;
    std::atomic_bool StopRequested{false};
    std::atomic_bool Running{false};
    uint64_t Batches = 0;
    uint64_t Events = 0;
    uint64_t Added = 0;
    uint64_t Errors = 0;
    std::wstring LastUtc;
    std::wstring LastError;
};

static TimelineAutoDrainWorker g_TimelineAutoDrainWorker;

static bool StartTimelineAutoDrainWorker(DebuggerState& state, DeviceClient* device)
{
    return g_TimelineAutoDrainWorker.Start(&state, device);
}

static void StopTimelineAutoDrainWorker()
{
    g_TimelineAutoDrainWorker.Stop();
}

static TimelineAutoDrainSnapshot QueryTimelineAutoDrainSnapshot()
{
    return g_TimelineAutoDrainWorker.Snapshot();
}

static void PrintTimelineAutoDrainStatus(const TimelineAutoDrainSnapshot& snapshot)
{
    PrintColoredText(L"[timeline.live]", KNDBG_COLOR_TITLE);
    std::wcout << L" auto_drain=" << (snapshot.Running ? L"running" : L"stopped")
               << L" batches=" << snapshot.Batches
               << L" drained=" << snapshot.Events
               << L" added=" << snapshot.Added
               << L" errors=" << snapshot.Errors;
    if (!snapshot.LastUtc.empty())
    {
        std::wcout << L" last=" << snapshot.LastUtc;
    }
    if (!snapshot.LastError.empty())
    {
        std::wcout << L" last_error=" << snapshot.LastError;
    }
    std::wcout << L"\n";
}

static void PrintTimelineGraph(const TimelineGraphResult& graph)
{
    PrintColoredText(L"[timeline.graph]", KNDBG_COLOR_TITLE);
    std::wcout << L" total_events=" << graph.TotalEvents
               << L" matched_events=" << graph.MatchedEvents
               << L" nodes=" << graph.Nodes.size()
               << L" edges=" << graph.Edges.size();
    if (graph.Truncated)
    {
        std::wcout << L" truncated=true";
    }
    std::wcout << L"\n";

    for (const TimelineGraphNode& node : graph.Nodes)
    {
        std::wcout << L"  node kind=" << node.Kind
                   << L" label=" << node.Label
                   << L" events=" << node.EventCount << L"\n";
    }

    for (const TimelineGraphEdge& edge : graph.Edges)
    {
        std::wcout << L"  edge kind=" << edge.Kind
                   << L" from=" << edge.From
                   << L" to=" << edge.To
                   << L" events=" << edge.EventCount;
        if (edge.FirstEventId != 0 || edge.LastEventId != 0)
        {
            std::wcout << L" first=" << edge.FirstEventId
                       << L" last=" << edge.LastEventId;
        }
        std::wcout << L"\n";
    }
}

static void PrintTimelineReconcile(const TimelineReconcileResult& result)
{
    PrintColoredText(L"[timeline.reconcile]", KNDBG_COLOR_TITLE);
    std::wcout << L" snapshot=" << result.SnapshotLabel
               << L" timeline_events=" << result.TimelineEvents
               << L" snapshot_processes=" << result.SnapshotProcesses
               << L" snapshot_records=" << result.SnapshotRecords
               << L" findings=" << result.Findings.size()
               << L" live_dropped=" << result.LiveDropped;
    if (result.Truncated)
    {
        std::wcout << L" truncated=true";
    }
    std::wcout << L"\n";

    for (const std::wstring& warning : result.Warnings)
    {
        PrintColoredText(L"[timeline.reconcile.warning]", KNDBG_COLOR_WARN);
        std::wcout << L" " << warning << L"\n";
    }

    for (const TimelineReconcileFinding& finding : result.Findings)
    {
        std::wcout << L"  finding kind=" << finding.Kind
                   << L" domain=" << finding.Domain
                   << L" risk=" << finding.Risk
                   << L" confidence=" << finding.Confidence;
        if (finding.ProcessId != 0)
        {
            std::wcout << L" pid=" << finding.ProcessId;
        }
        if (finding.EventId != 0)
        {
            std::wcout << L" event_id=" << finding.EventId;
        }
        std::wcout << L" subject=" << finding.Subject
                   << L" summary=" << finding.Summary << L"\n";
    }
}

static bool ParseTimelineQueryOptions(
    const std::vector<std::wstring>& args,
    size_t start,
    uint32_t numberBase,
    TimelineQueryOptions* options,
    std::wstring* error)
{
    (void)numberBase;
    bool ok = false;

    do
    {
        if (options == nullptr)
        {
            if (error != nullptr)
            {
                *error = L"invalid query options output";
            }
            break;
        }

        size_t index = start;
        while (index < args.size())
        {
            std::wstring option = ToLower(args[index]);
            if (option == L"/source")
            {
                if (index + 1 >= args.size())
                {
                    if (error != nullptr)
                    {
                        *error = L"/source requires a value";
                    }
                    break;
                }
                options->Source = args[index + 1];
                index += 2;
                continue;
            }
            if (option == L"/domain")
            {
                if (index + 1 >= args.size())
                {
                    if (error != nullptr)
                    {
                        *error = L"/domain requires a value";
                    }
                    break;
                }
                options->Domain = args[index + 1];
                index += 2;
                continue;
            }
            if (option == L"/pid")
            {
                if (index + 1 >= args.size())
                {
                    if (error != nullptr)
                    {
                        *error = L"/pid requires a value";
                    }
                    break;
                }
                uint64_t pid = 0;
                if (!ParseUnsigned(args[index + 1], 10, &pid) || pid == 0 || pid > 0xffffffffull)
                {
                    if (error != nullptr)
                    {
                        *error = L"invalid PID: " + args[index + 1];
                    }
                    break;
                }
                options->HasProcessId = true;
                options->ProcessId = static_cast<uint32_t>(pid);
                index += 2;
                continue;
            }
            if (option == L"/limit")
            {
                if (index + 1 >= args.size())
                {
                    if (error != nullptr)
                    {
                        *error = L"/limit requires a value";
                    }
                    break;
                }
                if (!ParseTimelineLimit(args[index + 1], 5000, &options->Limit, error))
                {
                    break;
                }
                index += 2;
                continue;
            }
            if (option == L"/oldest")
            {
                options->NewestFirst = false;
                ++index;
                continue;
            }
            if (option == L"/newest")
            {
                options->NewestFirst = true;
                ++index;
                continue;
            }

            if (error != nullptr)
            {
                *error = L"unrecognised option: " + args[index];
            }
            break;
        }

        ok = (index >= args.size());
    } while (false);

    return ok;
}

