struct ConsoleSurfaceSelfTestContext
{
    uint32_t Passed = 0;
    uint32_t Failed = 0;
};

static void CheckConsoleSurfaceSelfTest(
    ConsoleSurfaceSelfTestContext* context,
    bool condition,
    const std::wstring& name)
{
    do
    {
        if (context == nullptr)
        {
            break;
        }

        if (condition)
        {
            ++context->Passed;
            std::wcout << L"[console.selftest] PASS " << name << L"\n";
        }
        else
        {
            ++context->Failed;
            std::wcerr << L"[console.selftest] FAIL " << name << L"\n";
        }
    } while (false);
}

static bool CompletionCandidateExists(
    const std::vector<std::wstring>& argsBefore,
    const std::wstring& expected)
{
    std::vector<std::wstring> candidates = BuildInteractiveCompletionCandidates(argsBefore);
    return std::find(candidates.begin(), candidates.end(), expected) != candidates.end();
}

static void CheckCompletionCandidate(
    ConsoleSurfaceSelfTestContext* context,
    const std::vector<std::wstring>& argsBefore,
    const std::wstring& expected,
    const std::wstring& name)
{
    CheckConsoleSurfaceSelfTest(
        context,
        CompletionCandidateExists(argsBefore, expected),
        name);
}

static std::wstring CaptureDetailedHelpOutput(
    const std::vector<std::wstring>& args,
    size_t commandIndex)
{
    std::wstring output;

    do
    {
        std::wostringstream capture;
        std::wstreambuf* oldOut = std::wcout.rdbuf(capture.rdbuf());
        PrintDetailedCommandHelp(args, commandIndex);
        std::wcout.rdbuf(oldOut);
        output = capture.str();
    } while (false);

    return output;
}

static std::wstring CaptureCompletionListing(
    const std::vector<std::wstring>& argsBefore,
    const std::wstring& prefix)
{
    std::vector<std::wstring> candidates = BuildInteractiveCompletionCandidates(argsBefore);
    std::vector<std::wstring> matches = FilterCompletionCandidates(candidates, prefix);
    return FormatCompletionListing(matches, argsBefore);
}

static std::wstring FirstCommandMissingCompletionGuide()
{
    std::wstring missing;
    for (const CommandInfo& info : CommandRegistry::Commands())
    {
        if (info.Support == CommandSupport::DbgEng || info.Name == nullptr)
        {
            continue;
        }

        CompletionCommandGuide guide = {};
        if (!FindCompletionCommandGuide(info.Name, {}, &guide) ||
            guide.Summary == nullptr ||
            guide.Summary[0] == L'\0')
        {
            missing = info.Name;
            break;
        }
    }

    return missing;
}

