static bool HuntLabelsContain(const std::vector<std::wstring>& labels, const std::wstring& value)
{
    return std::find(labels.begin(), labels.end(), value) != labels.end();
}

static void AddUniqueHuntText(std::vector<std::wstring>* values, const std::wstring& value, size_t maxCount)
{
    do
    {
        if (values == nullptr || value.empty())
        {
            break;
        }

        if (std::find(values->begin(), values->end(), value) != values->end())
        {
            break;
        }

        if (values->size() >= maxCount)
        {
            break;
        }

        values->push_back(value);
    } while (false);
}

static std::wstring HuntFindingSampleText(const HuntFinding& finding)
{
    std::wstringstream stream;

    if (!finding.ImageName.empty())
    {
        stream << finding.ImageName;
    }
    else if (!finding.ModuleName.empty())
    {
        stream << finding.ModuleName;
    }
    else if (finding.ProcessId == 0)
    {
        stream << L"system";
    }
    else
    {
        stream << L"pid";
    }

    if (finding.ProcessId != 0)
    {
        stream << L"(" << finding.ProcessId << L")";
    }

    return stream.str();
}

static std::wstring HuntAssessmentKindForFinding(
    const HuntFinding& finding,
    const std::vector<std::wstring>& labels)
{
    std::wstring classLabel = HuntConsoleClassLabel(finding.ClassName);
    std::wstring kind;

    if (HuntLabelsContain(labels, L"published_file_hash_ioc") ||
        HuntLabelsContain(labels, L"exact_defense_evasion_file_hash") ||
        HuntLabelsContain(labels, L"exact_credential_tool_file_hash"))
    {
        kind = L"published_file_hash_ioc";
    }
    else if (classLabel == L"defense_evasion_driver_service" ||
             classLabel == L"defense_evasion_driver_profile" ||
             classLabel == L"known_defense_evasion_driver" ||
             classLabel == L"driver_file_hash_ioc" ||
             HuntLabelsContain(labels, L"known_defense_evasion_driver_service") ||
             HuntLabelsContain(labels, L"known_loaded_driver_name"))
    {
        kind = L"defense_evasion_driver_artifact";
    }
    else if (classLabel == L"credential_collection_tool_profile" ||
             classLabel == L"credential_collection_file_hash_ioc" ||
             HuntLabelsContain(labels, L"credential_collection_cli_shape") ||
             HuntLabelsContain(labels, L"known_credential_tool_name"))
    {
        kind = L"credential_collection_tool";
    }
    else if (classLabel == L"security_product_impairment_telemetry" ||
             HuntLabelsContain(labels, L"security_product_process_targeting") ||
             HuntLabelsContain(labels, L"security_product_target_list"))
    {
        kind = L"security_product_targeting";
    }
    else if (classLabel == L"security_communication_blocking" ||
             HuntLabelsContain(labels, L"security_tool_communication_blocking") ||
             HuntLabelsContain(labels, L"security_tool_communication_throttling") ||
             HuntLabelsContain(labels, L"qos_security_product_throttle_policy") ||
             HuntLabelsContain(labels, L"edrchoker_state") ||
             HuntLabelsContain(labels, L"wfp_security_product_block_filter") ||
             HuntLabelsContain(labels, L"wfp_anticheat_block_filter"))
    {
        kind = L"security_communication_blocking";
    }
    else if (classLabel == L"bind_link_tampering" ||
             HuntLabelsContain(
                 labels,
                 L"bindflt_active_global_mapping") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_security_product_path") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_security_artifact_path") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_protected_to_user_path") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_inverse_trust_mapping") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_protected_image_redirect") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_inverse_image_redirect") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_process_binding_state") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_process_backing_correlation") ||
             HuntLabelsContain(
                 labels,
                 L"bind_link_inverse_pair"))
    {
        kind = L"bind_link_tampering";
    }
    else if (classLabel == L"cloudfiles_ffi_tampering" ||
             HuntLabelsContain(
                 labels,
                 L"cloudfiles_ffi_ppl_image_mapping") ||
             HuntLabelsContain(
                 labels,
                 L"cloudfiles_placeholder_modified_data") ||
             HuntLabelsContain(
                 labels,
                 L"cloudfiles_ffi_live_disk_mismatch"))
    {
        kind = L"cloudfiles_ffi_tampering";
    }
    else if (classLabel == L"defense_evasion_process_profile" ||
             HuntLabelsContain(labels, L"known_defense_evasion_tool_name") ||
             HuntLabelsContain(labels, L"renamed_defense_evasion_tool_name"))
    {
        kind = L"defense_evasion_process_profile";
    }
    else if (classLabel == L"process_doppelganging" ||
             classLabel == L"process_image_integrity" ||
             HuntLabelsContain(labels, L"main_image_backing_mismatch") ||
             HuntLabelsContain(labels, L"main_image_section_path_mismatch") ||
             HuntLabelsContain(labels, L"live_main_image_differs_from_disk") ||
             HuntLabelsContain(labels, L"main_image_entrypoint_modified") ||
             HuntLabelsContain(labels, L"main_image_hash_modified") ||
             HuntLabelsContain(labels, L"kernel_main_section_swap_evidence") ||
             HuntLabelsContain(labels, L"process_tampering_primitive_evidence") ||
             HuntLabelsContain(labels, L"main_section_object_vs_vad_backing_mismatch") ||
             HuntLabelsContain(labels, L"main_section_object_vs_process_path_mismatch") ||
             HuntLabelsContain(labels, L"main_section_object_vs_peb_path_mismatch") ||
             HuntLabelsContain(labels, L"main_section_object_vs_api_path_mismatch") ||
             HuntLabelsContain(labels, L"main_image_file_delete_pending") ||
             HuntLabelsContain(labels, L"main_section_object_file_delete_pending") ||
             HuntLabelsContain(labels, L"main_image_file_write_or_delete_access") ||
             HuntLabelsContain(labels, L"main_section_object_file_write_or_delete_access") ||
             HuntLabelsContain(labels, L"main_image_file_section_object_pointer_mismatch") ||
             HuntLabelsContain(labels, L"main_section_object_file_section_object_pointer_mismatch"))
    {
        kind = L"process_tampering";
    }
    else if (classLabel == L"module_stomping" ||
             HuntLabelsContain(labels, L"module_stomping_permission_evidence") ||
             HuntLabelsContain(labels, L"module_entrypoint_write_permission_drift") ||
             HuntLabelsContain(labels, L"image_section_execute_permission_drift") ||
             HuntLabelsContain(labels, L"image_section_write_permission_drift") ||
             HuntLabelsContain(labels, L"image_rwx_section_vad") ||
             HuntLabelsContain(labels, L"mockingjay_rwx_section_candidate") ||
             HuntLabelsContain(labels, L"live_module_page_modified") ||
             HuntLabelsContain(labels, L"live_executable_page_differs_from_disk") ||
             HuntLabelsContain(labels, L"module_entrypoint_modified") ||
             HuntLabelsContain(labels, L"module_text_modified") ||
             HuntLabelsContain(labels, L"thread_started_in_modified_module_page") ||
             HuntLabelsContain(labels, L"apc_targeted_modified_module_page") ||
             HuntLabelsContain(labels, L"stack_referenced_modified_module_page"))
    {
        kind = L"module_stomping";
    }
    else if (classLabel == L"module_cross_view" ||
             classLabel == L"mapped_code" ||
             classLabel == L"manual_map" ||
             classLabel == L"vad_dkom" ||
             classLabel == L"builtin_module_provenance" ||
             HuntLabelsContain(labels, L"image_mapping_without_loader_entry") ||
             HuntLabelsContain(labels, L"image_vad_hidden_from_loader") ||
             HuntLabelsContain(labels, L"manual_mapped_private_pe") ||
             HuntLabelsContain(labels, L"partial_loader_unlink") ||
             HuntLabelsContain(labels, L"module_view_mismatch"))
    {
        kind = L"mapped_code_or_loader_evasion";
    }
    else
    {
        kind = classLabel.empty() ? L"other_hunt_finding" : classLabel;
    }

    return kind;
}

static uint32_t HuntAssessmentPriority(const std::wstring& kind)
{
    uint32_t priority = 900;

    if (kind == L"published_file_hash_ioc")
    {
        priority = 10;
    }
    else if (kind == L"defense_evasion_process_profile" ||
             kind == L"defense_evasion_driver_artifact")
    {
        priority = 20;
    }
    else if (kind == L"credential_collection_tool")
    {
        priority = 30;
    }
    else if (kind == L"process_tampering")
    {
        priority = 15;
    }
    else if (kind == L"security_product_targeting")
    {
        priority = 40;
    }
    else if (kind == L"security_communication_blocking")
    {
        priority = 45;
    }
    else if (kind == L"bind_link_tampering")
    {
        priority = 12;
    }
    else if (kind == L"cloudfiles_ffi_tampering")
    {
        priority = 11;
    }
    else if (kind == L"module_stomping")
    {
        priority = 50;
    }
    else if (kind == L"mapped_code_or_loader_evasion")
    {
        priority = 80;
    }

    return priority;
}

static std::wstring HuntAssessmentSeverityText(const HuntConsoleAssessmentSummary& summary)
{
    std::wstring severity = L"low";

    if (summary.High != 0)
    {
        severity = L"high";
    }
    else if (summary.Medium != 0)
    {
        severity = L"medium";
    }

    return severity;
}

static bool IsHighSignalHuntAssessment(const HuntConsoleAssessmentSummary& summary)
{
    return summary.High != 0;
}

static void PrintHuntAssessmentLine(
    const HuntConsoleAssessmentSummary& summary,
    const std::wstring& line)
{
    if (IsHighSignalHuntAssessment(summary))
    {
        PrintColoredText(line, KNDBG_COLOR_FAIL);
    }
    else
    {
        std::wcout << line;
    }
}

static std::wstring HuntAssessmentTechniqueText(const std::wstring& kind)
{
    std::wstring technique;

    if (kind == L"published_file_hash_ioc")
    {
        technique = L"matched a published threat file hash";
    }
    else if (kind == L"defense_evasion_driver_artifact")
    {
        technique = L"installed or exposed a known defense-evasion driver artifact";
    }
    else if (kind == L"credential_collection_tool")
    {
        technique = L"matched credential-collection tool behavior or identity";
    }
    else if (kind == L"security_product_targeting")
    {
        technique = L"repeatedly controlled known security-product processes";
    }
    else if (kind == L"security_communication_blocking")
    {
        technique = L"installed a network policy that blocks or throttles security-product communication";
    }
    else if (kind == L"bind_link_tampering")
    {
        technique = L"redirected a security-sensitive path through an active Bind Filter mapping";
    }
    else if (kind == L"cloudfiles_ffi_tampering")
    {
        technique = L"mapped mutable Cloud Files placeholder backing as executable image code";
    }
    else if (kind == L"defense_evasion_process_profile")
    {
        technique = L"masqueraded as a known defense-evasion tool";
    }
    else if (kind == L"process_tampering")
    {
        technique = L"tampered with process main image or section backing";
    }
    else if (kind == L"module_stomping")
    {
        technique = L"modified loaded module code or executable section permissions";
    }
    else if (kind == L"mapped_code_or_loader_evasion")
    {
        technique = L"hid or replaced executable code outside the normal loader view";
    }
    else
    {
        technique = L"matched a hunt anomaly";
    }

    return technique;
}

