static std::wstring HuntAssessmentEvidenceText(const HuntConsoleAssessmentSummary& summary)
{
    std::vector<std::wstring> phrases;

    for (const std::wstring& label : summary.Evidence)
    {
        AddUniqueHuntText(&phrases, HuntAssessmentEvidencePhrase(label), 8);
    }

    if (phrases.empty())
    {
        return L"-";
    }

    return JoinHuntValues(phrases, L"; ");
}

static std::wstring HuntDominantReasonText(const std::map<std::wstring, uint64_t>& reasons)
{
    std::wstring reason;
    uint64_t count = 0;
    uint32_t priority = 1000;

    auto selectReason =
        [&reason, &count, &priority](const std::map<std::wstring, uint64_t>& source, bool skipContext)
        {
            for (const auto& item : source)
            {
                if (skipContext && item.first == L"builtin_process_injection_evidence")
                {
                    continue;
                }

                uint32_t itemPriority = HuntConsoleSignalPriority(item.first);
                if (itemPriority < priority ||
                    (itemPriority == priority && item.second > count))
                {
                    reason = item.first;
                    count = item.second;
                    priority = itemPriority;
                }
            }
        };

    selectReason(reasons, true);
    if (reason.empty())
    {
        selectReason(reasons, false);
    }

    return reason;
}

static bool IsHuntHighSignalReason(const std::wstring& reason)
{
    bool matched = false;
    std::wstring lowered = ToLower(reason);

    do
    {
        if (StartsWithNoCase(lowered, L"gentlemen_") ||
            StartsWithNoCase(lowered, L"gentlekiller_") ||
            StartsWithNoCase(lowered, L"oxideharvest_") ||
            StartsWithNoCase(lowered, L"edr_killer_") ||
            StartsWithNoCase(lowered, L"eset_") ||
            StartsWithNoCase(lowered, L"byovd_"))
        {
            matched = true;
            break;
        }

        if (lowered == L"driver_service_binary_name_ioc" ||
            lowered == L"driver_service_installed" ||
            lowered == L"driver_service_running" ||
            lowered == L"known_security_product_process_target" ||
            lowered == L"loaded_driver_name_ioc" ||
            lowered == L"process_tampering_primitive_evidence" ||
            lowered == L"main_image_vad_file_delete_pending" ||
            lowered == L"main_section_object_file_delete_pending" ||
            lowered == L"main_image_vad_file_section_object_pointer_mismatch" ||
            lowered == L"main_section_object_file_section_object_pointer_mismatch" ||
            lowered == L"module_stomping_permission_evidence" ||
            lowered == L"module_entrypoint_write_permission_drift" ||
            lowered == L"security_tool_communication_blocking" ||
            lowered == L"security_tool_communication_throttling" ||
            lowered == L"qos_security_product_throttle_policy" ||
            lowered == L"edrchoker_state" ||
            lowered == L"bindflt_active_global_mapping" ||
            lowered == L"bind_link_security_product_path" ||
            lowered == L"bind_link_security_artifact_path" ||
            lowered == L"bind_link_protected_to_user_path" ||
            lowered == L"bind_link_inverse_trust_mapping" ||
            lowered == L"bind_link_protected_image_redirect" ||
            lowered == L"bind_link_inverse_image_redirect" ||
            lowered == L"bind_link_process_binding_state" ||
            lowered == L"bind_link_process_backing_correlation" ||
            lowered == L"bind_link_inverse_pair" ||
            lowered == L"cloudfiles_executable_placeholder_mapping" ||
            lowered == L"cloudfiles_ffi_ppl_image_mapping" ||
            lowered == L"cloudfiles_placeholder_modified_data" ||
            lowered == L"cloudfiles_ffi_live_disk_mismatch" ||
            lowered == L"wfp_security_product_block_filter" ||
            lowered == L"wfp_anticheat_block_filter" ||
            lowered == L"wfp_appid_block_condition")
        {
            matched = true;
            break;
        }
    } while (false);

    return matched;
}

static std::wstring FormatHuntPidList(const std::vector<uint32_t>& processIds, size_t maxCount)
{
    std::wstringstream stream;

    if (processIds.empty())
    {
        return L"-";
    }

    size_t printed = std::min(maxCount, processIds.size());
    for (size_t index = 0; index < printed; ++index)
    {
        if (index != 0)
        {
            stream << L",";
        }

        stream << processIds[index];
    }

    if (printed < processIds.size())
    {
        stream << L",...(+" << (processIds.size() - printed) << L")";
    }

    return stream.str();
}

static std::vector<HuntConsoleProcessSummary> BuildHuntProcessSummaries(const HuntResult& result)
{
    std::map<std::wstring, HuntConsoleProcessSummary> byProcess;

    for (const HuntFinding& finding : result.Findings)
    {
        std::wstring key = BuildHuntProcessKey(finding);
        HuntConsoleProcessSummary& summary = byProcess[key];
        if (summary.Total == 0)
        {
            summary.ProcessId = finding.ProcessId;
            summary.Eprocess = finding.Eprocess;
            summary.ImageName = finding.ImageName;
        }

        ++summary.Total;
        AddHuntRiskCount(finding.Risk, &summary.High, &summary.Medium, &summary.Low);
        for (const std::wstring& reason : finding.ReasonCodes)
        {
            std::wstring label = HuntConsoleReasonLabel(reason);
            summary.Priority = std::min(summary.Priority, HuntConsoleSignalPriority(label));
            ++summary.Reasons[label];
        }
    }

    std::vector<HuntConsoleProcessSummary> summaries;
    summaries.reserve(byProcess.size());
    for (const auto& item : byProcess)
    {
        summaries.push_back(item.second);
    }

    std::sort(
        summaries.begin(),
        summaries.end(),
        [](const HuntConsoleProcessSummary& left, const HuntConsoleProcessSummary& right)
        {
            if (left.Priority != right.Priority)
            {
                return left.Priority < right.Priority;
            }
            if (left.High != right.High)
            {
                return left.High > right.High;
            }
            if (left.Medium != right.Medium)
            {
                return left.Medium > right.Medium;
            }
            if (left.Total != right.Total)
            {
                return left.Total > right.Total;
            }
            if (left.ImageName != right.ImageName)
            {
                return left.ImageName < right.ImageName;
            }
            return left.ProcessId < right.ProcessId;
        });

    return summaries;
}

static std::vector<HuntConsoleReasonSummary> BuildHuntReasonSummaries(const HuntResult& result)
{
    std::map<std::wstring, HuntConsoleReasonSummary> byReason;

    for (const HuntFinding& finding : result.Findings)
    {
        for (const std::wstring& reason : finding.ReasonCodes)
        {
            std::wstring label = HuntConsoleReasonLabel(reason);
            HuntConsoleReasonSummary& summary = byReason[label];
            if (summary.Reason.empty())
            {
                summary.Reason = label;
                summary.Priority = HuntConsoleSignalPriority(label);
            }

            ++summary.Total;
            AddHuntRiskCount(finding.Risk, &summary.High, &summary.Medium, &summary.Low);
            if (finding.ProcessId != 0)
            {
                AddUniqueHuntProcessId(&summary.ProcessIds, finding.ProcessId);
            }
            else
            {
                ++summary.SystemFindings;
            }
        }
    }

    std::vector<HuntConsoleReasonSummary> summaries;
    summaries.reserve(byReason.size());
    for (const auto& item : byReason)
    {
        summaries.push_back(item.second);
    }

    std::sort(
        summaries.begin(),
        summaries.end(),
        [](const HuntConsoleReasonSummary& left, const HuntConsoleReasonSummary& right)
        {
            if (left.Priority != right.Priority)
            {
                return left.Priority < right.Priority;
            }
            if (left.High != right.High)
            {
                return left.High > right.High;
            }
            if (left.Medium != right.Medium)
            {
                return left.Medium > right.Medium;
            }
            if (left.Total != right.Total)
            {
                return left.Total > right.Total;
            }
            return left.Reason < right.Reason;
        });

    return summaries;
}

static std::vector<HuntConsoleHighSignalSummary> BuildHuntHighSignalSummaries(const HuntResult& result)
{
    std::map<std::wstring, HuntConsoleHighSignalSummary> bySignal;

    for (const HuntFinding& finding : result.Findings)
    {
        for (const std::wstring& reason : finding.ReasonCodes)
        {
            if (!IsHuntHighSignalReason(reason))
            {
                continue;
            }

            std::wstring label = HuntConsoleReasonLabel(reason);
            HuntConsoleHighSignalSummary& summary = bySignal[label];
            if (summary.Signal.empty())
            {
                summary.Signal = label;
            }

            ++summary.Total;
            AddHuntRiskCount(finding.Risk, &summary.High, &summary.Medium, &summary.Low);
            if (finding.ProcessId != 0)
            {
                AddUniqueHuntProcessId(&summary.ProcessIds, finding.ProcessId);
            }
            else
            {
                ++summary.SystemFindings;
            }
        }
    }

    std::vector<HuntConsoleHighSignalSummary> summaries;
    summaries.reserve(bySignal.size());
    for (const auto& item : bySignal)
    {
        summaries.push_back(item.second);
    }

    std::sort(
        summaries.begin(),
        summaries.end(),
        [](const HuntConsoleHighSignalSummary& left, const HuntConsoleHighSignalSummary& right)
        {
            uint32_t leftPriority = HuntConsoleSignalPriority(left.Signal);
            uint32_t rightPriority = HuntConsoleSignalPriority(right.Signal);
            if (leftPriority != rightPriority)
            {
                return leftPriority < rightPriority;
            }
            if (left.High != right.High)
            {
                return left.High > right.High;
            }
            if (left.Medium != right.Medium)
            {
                return left.Medium > right.Medium;
            }
            if (left.Total != right.Total)
            {
                return left.Total > right.Total;
            }
            return left.Signal < right.Signal;
        });

    return summaries;
}

static std::vector<HuntConsoleAssessmentSummary> BuildHuntAssessmentSummaries(const HuntResult& result)
{
    std::map<std::wstring, HuntConsoleAssessmentSummary> byKind;

    for (const HuntFinding& finding : result.Findings)
    {
        std::vector<std::wstring> labels = BuildHuntConsoleReasonLabels(finding.ReasonCodes);
        std::wstring kind = HuntAssessmentKindForFinding(finding, labels);
        HuntConsoleAssessmentSummary& summary = byKind[kind];
        if (summary.Kind.empty())
        {
            summary.Kind = kind;
            summary.Priority = HuntAssessmentPriority(kind);
        }

        ++summary.Total;
        AddHuntRiskCount(finding.Risk, &summary.High, &summary.Medium, &summary.Low);
        if (finding.ProcessId != 0)
        {
            AddUniqueHuntProcessId(&summary.ProcessIds, finding.ProcessId);
        }
        else
        {
            ++summary.SystemFindings;
        }

        AddUniqueHuntText(&summary.Samples, HuntFindingSampleText(finding), 6);
        for (const std::wstring& label : labels)
        {
            if (HuntConsoleSignalPriority(label) <= 90)
            {
                AddUniqueHuntText(&summary.Evidence, label, 8);
            }
        }
    }

    std::vector<HuntConsoleAssessmentSummary> summaries;
    summaries.reserve(byKind.size());
    for (const auto& item : byKind)
    {
        summaries.push_back(item.second);
    }

    std::sort(
        summaries.begin(),
        summaries.end(),
        [](const HuntConsoleAssessmentSummary& left, const HuntConsoleAssessmentSummary& right)
        {
            if (left.Priority != right.Priority)
            {
                return left.Priority < right.Priority;
            }
            if (left.High != right.High)
            {
                return left.High > right.High;
            }
            if (left.Medium != right.Medium)
            {
                return left.Medium > right.Medium;
            }
            if (left.Total != right.Total)
            {
                return left.Total > right.Total;
            }
            return left.Kind < right.Kind;
        });

    return summaries;
}

static void PrintHuntSummaryLine(const HuntResult& result)
{
    PrintColoredText(L"[hunt.summary]", KNDBG_COLOR_TITLE);
    std::wcout << L" scanned=" << result.ScannedProcessCount
               << L" findings=" << result.Findings.size()
               << L" high=" << result.HighFindings
               << L" medium=" << result.MediumFindings
               << L" low=" << result.LowFindings;
    if (result.KernelModuleCount != 0 ||
        result.ByovdMatchedDriverCount != 0 ||
        result.DriverObjectCount != 0 ||
        result.SuspiciousDriverObjectCount != 0 ||
        result.DriverServiceCount != 0 ||
        result.EdrKillerDriverServiceCount != 0)
    {
        std::wcout << L" kernel_modules=" << result.KernelModuleCount
                   << L" byovd_matches=" << result.ByovdMatchedDriverCount
                   << L" suspicious_drivers=" << result.SuspiciousDriverObjectCount
                   << L" driver_services=" << result.DriverServiceCount;
    }
    if (result.EdrKillerDriverServiceCount != 0)
    {
        std::wcout << L" driver_service_iocs=" << result.EdrKillerDriverServiceCount;
    }
    if (result.WfpFilterCount != 0 || result.SuspiciousWfpFilterCount != 0)
    {
        std::wcout << L" wfp_filters=" << result.WfpFilterCount
                   << L" suspicious_wfp_filters=" << result.SuspiciousWfpFilterCount;
    }
    if (result.WfpFilterCoverageIncomplete)
    {
        std::wcout << L" wfp_filter_coverage_incomplete=yes";
    }
    if (result.QosPolicyCount != 0 ||
        result.SuspiciousQosPolicyCount != 0)
    {
        std::wcout << L" qos_policies=" << result.QosPolicyCount
                   << L" suspicious_qos_policies="
                   << result.SuspiciousQosPolicyCount;
    }
    if (result.BindFilterMappingCount != 0 ||
        result.SuspiciousBindFilterMappingCount != 0 ||
        result.BindFilterProcessBindingCount != 0)
    {
        std::wcout << L" bindflt_global_mappings="
                   << result.BindFilterMappingCount
                   << L" suspicious_bindflt_global_mappings="
                   << result.SuspiciousBindFilterMappingCount
                   << L" bindflt_process_bindings="
                   << result.BindFilterProcessBindingCount;
    }
    if (result.CloudFilePlaceholderImageCount != 0 ||
        result.SuspiciousCloudFileImageCount != 0)
    {
        std::wcout << L" cloudfiles_placeholder_images="
                   << result.CloudFilePlaceholderImageCount
                   << L" suspicious_cloudfiles_images="
                   << result.SuspiciousCloudFileImageCount;
    }
    if (result.ThreatIntelActive || result.ThreatIntelAvailable || result.ThreatIntelEventCount != 0 || result.ThreatIntelCorrelationCount != 0)
    {
        std::wcout << L" ti_active=" << (result.ThreatIntelActive ? L"yes" : L"no")
                   << L" ti_available=" << (result.ThreatIntelAvailable ? L"yes" : L"no")
                   << L" ti_events=" << result.ThreatIntelEventCount
                   << L" ti_correlations=" << result.ThreatIntelCorrelationCount;
    }
    std::wcout << L" coverage_complete=" << (result.CoverageComplete ? L"yes" : L"no");
    if (result.ProcessInventoryIncomplete)
    {
        std::wcout << L" process_inventory_incomplete=yes";
    }
    if (result.ProcessTriageCoverageIncomplete)
    {
        std::wcout << L" process_triage_incomplete=yes";
    }
    if (result.DeepImageComparisonCoverageIncomplete)
    {
        std::wcout << L" deep_image_comparison_incomplete=yes";
    }
    if (result.CidTableLookupOnly)
    {
        std::wcout << L" cid_lookup_only=yes";
    }
    else if (result.CidTableFullProcessEnumeration ||
             result.CidTableDirectEntryEnumeration)
    {
        std::wcout << L" cid_process_full="
                   << (result.CidTableFullProcessEnumeration
                           ? L"complete"
                           : L"incomplete")
                   << L" cid_direct_entry="
                   << (result.CidTableDirectEntryEnumeration
                           ? L"complete"
                           : L"incomplete")
                   << L" cid_thread_full="
                   << (result.CidTableFullThreadEnumeration
                           ? L"complete"
                           : L"incomplete")
                   << L" cid_processes="
                   << result.CidTableProcessCount
                   << L" cid_discovered="
                   << result.CidTableDiscoveredProcessCount
                   << L" cid_level="
                   << result.CidTableLevel
                   << L" cid_leaves="
                   << result.CidTableAllocatedLeafCount
                   << L" cid_capacity="
                   << result.CidTableAllocatedHandleCapacity
                   << L" cid_probes="
                   << result.CidTableProbeCount
                   << L" cid_api_misses="
                   << result.CidTablePersistentApiMissCount
                   << L" cid_direct_entries="
                   << result.CidTableDirectEntryCount
                   << L" cid_direct_processes="
                   << result.CidTableDirectProcessCount
                   << L" cid_direct_threads="
                   << result.CidTableDirectThreadCount
                   << L" system_threads="
                   << result.SystemProcessInfoThreadCount
                   << L" toolhelp_threads="
                   << result.ToolhelpThreadCount
                   << L" cid_unclassified="
                   << result.CidTableUnclassifiedEntryCount
                   << L" cid_thread_findings="
                   << result.CidTableThreadFindingCount
                   << L" cid_thread_view_misses="
                   << result.CidTablePersistentThreadViewMissCount
                   << L" cid_thread_cross_view="
                   << (result.CidTableThreadCrossViewComplete
                           ? L"complete"
                           : L"incomplete")
                   << L" cid_whole_table="
                   << (result.CidTableFullEnumeration
                           ? L"complete"
                           : L"incomplete");
    }
    if (result.ThreatIntelCorrelationIncomplete)
    {
        std::wcout << L" ti_correlation_incomplete=yes";
    }
    if (result.BindFilterProcessCorrelationCoverageIncomplete)
    {
        std::wcout << L" bindflt_process_correlation_incomplete=yes";
    }
    if (result.CloudFilePlaceholderCoverageIncomplete)
    {
        std::wcout << L" cloudfiles_placeholder_incomplete=yes";
    }
    if (result.CloudFileProtectionCorrelationIncomplete)
    {
        std::wcout << L" cloudfiles_protection_correlation_incomplete=yes";
    }
    std::wcout << L"\n";
}

static void PrintHuntConclusion(const HuntResult& result, uint64_t warningCount)
{
    std::wstring verdict = L"clean";
    WORD color = KNDBG_COLOR_OK;
    std::wstring action = L"no hunt findings were emitted for the scanned system view";
    bool hasHighSignal = !BuildHuntHighSignalSummaries(result).empty();

    if (result.HighFindings != 0)
    {
        verdict = result.Findings.size() >= 1000 ? L"alert_noisy" : L"alert";
        color = KNDBG_COLOR_WARN;
        action = hasHighSignal
            ? L"read the assessment first; use /details for raw triage tables or /json for full evidence"
            : L"read the assessment first; use /details for raw process/reason clusters or /json for full evidence";
    }
    else if (result.MediumFindings != 0)
    {
        verdict = L"review";
        color = KNDBG_COLOR_TITLE;
        action = L"review the assessment and confirm with the printed follow-up commands";
    }
    else if (result.LowFindings != 0)
    {
        verdict = L"low_signal";
        color = KNDBG_COLOR_ACCENT;
        action = L"low-risk leads only; save JSON if this is a baseline capture";
    }
    else if (!result.CoverageComplete || result.ProcessInventoryIncomplete)
    {
        // Incomplete collection must never read as a clean whole-system bill
        // of health when zero findings were emitted.
        verdict = L"incomplete_coverage";
        color = KNDBG_COLOR_WARN;
        action = L"coverage is incomplete; do not treat empty findings as clean; re-run after fixing warnings or inspect incomplete inventory nodes";
    }

    PrintColoredText(L"[hunt.conclusion]", color);
    std::wcout << L" verdict=" << verdict
               << L" findings=" << result.Findings.size()
               << L" high=" << result.HighFindings
               << L" medium=" << result.MediumFindings
               << L" low=" << result.LowFindings
               << L" warnings=" << warningCount
               << L" coverage_complete=" << (result.CoverageComplete ? L"yes" : L"no")
               << L"\n";
    std::wcout << L"  action: " << action << L"\n";
}

static void PrintHuntHighSignalTable(const HuntResult& result)
{
    constexpr size_t maxRows = 12;
    constexpr size_t maxPids = 10;

    std::vector<HuntConsoleHighSignalSummary> signalSummaries = BuildHuntHighSignalSummaries(result);
    PrintColoredText(L"[hunt.high_signal]", signalSummaries.empty() ? KNDBG_COLOR_TITLE : KNDBG_COLOR_WARN);
    std::wcout << L" showing=" << std::min(maxRows, signalSummaries.size())
               << L" total=" << signalSummaries.size();
    if (signalSummaries.empty())
    {
        std::wcout << L" none=yes";
    }
    std::wcout << L"\n";

    for (size_t index = 0; index < signalSummaries.size() && index < maxRows; ++index)
    {
        const HuntConsoleHighSignalSummary& summary = signalSummaries[index];
        std::wcout << L"  #" << (index + 1)
                   << L" signal=" << summary.Signal
                   << L" total=" << summary.Total
                   << L" high=" << summary.High
                   << L" medium=" << summary.Medium
                   << L" low=" << summary.Low
                   << L" system_findings=" << summary.SystemFindings
                   << L" processes=" << summary.ProcessIds.size()
                   << L" pids=" << FormatHuntPidList(summary.ProcessIds, maxPids)
                   << L"\n";
    }
}

static std::wstring HuntConsoleQuotedText(std::wstring text)
{
    std::replace(text.begin(), text.end(), L'"', L'\'');
    return L"\"" + text + L"\"";
}

static std::wstring HuntAssessmentSubjectText(const HuntConsoleAssessmentSummary& summary)
{
    std::wstring subject = JoinHuntValues(summary.Samples, L",");

    if (subject.empty())
    {
        subject = summary.SystemFindings != 0 ? L"system" : L"-";
    }

    return subject;
}

static std::wstring HuntAssessmentWhatText(const std::wstring& kind)
{
    std::wstring text;

    if (kind == L"published_file_hash_ioc")
    {
        text = L"process, driver, or service binary matches a published threat file hash";
    }
    else if (kind == L"defense_evasion_driver_artifact")
    {
        text = L"SCM or loaded-driver state exposes a known defense-evasion driver artifact";
    }
    else if (kind == L"credential_collection_tool")
    {
        text = L"process identity or command line matches credential-collection tooling";
    }
    else if (kind == L"security_product_targeting")
    {
        text = L"process repeatedly controlled known security-product processes";
    }
    else if (kind == L"security_communication_blocking")
    {
        text = L"network policy blocks or throttles security-product communication";
    }
    else if (kind == L"bind_link_tampering")
    {
        text = L"active Bind Filter mapping redirects a security-sensitive filesystem path";
    }
    else if (kind == L"cloudfiles_ffi_tampering")
    {
        text = L"executable image mapping uses Cloud Files placeholder backing with PPL, modified-data, or live-page divergence evidence";
    }
    else if (kind == L"defense_evasion_process_profile")
    {
        text = L"process identity or metadata masquerades as a known defense-evasion tool";
    }
    else if (kind == L"process_tampering")
    {
        text = L"process main image or section backing was swapped, deleted, or write/delete-accessible";
    }
    else if (kind == L"module_stomping")
    {
        text = L"loaded module code or section permissions indicate module stomping";
    }
    else if (kind == L"mapped_code_or_loader_evasion")
    {
        text = L"executable code is hidden, replaced, or inconsistent with normal loader views";
    }
    else
    {
        text = HuntAssessmentTechniqueText(kind);
    }

    return text;
}

static std::wstring HuntAssessmentNextText(const HuntConsoleAssessmentSummary& summary)
{
    std::wstring next;

    if (summary.Kind == L"published_file_hash_ioc")
    {
        next = L"isolate the subject and review matched hash paths in /json";
    }
    else if (summary.Kind == L"defense_evasion_driver_artifact")
    {
        next = L"review the SCM service, loaded-driver path, and binary hash in /json";
    }
    else if (summary.Kind == L"credential_collection_tool")
    {
        next = L"review command line, image path, and file identity in /json";
    }
    else if (summary.Kind == L"security_product_targeting")
    {
        next = L"review recent !ti events and the target process list in /json";
    }
    else if (summary.Kind == L"security_communication_blocking")
    {
        next = L"review WFP filters plus ActiveStore QoS policy targets and rates in /json";
    }
    else if (summary.Kind == L"bind_link_tampering")
    {
        next = L"compare virtual/backing paths and process main-section file identity in /json";
    }
    else if (summary.Kind == L"cloudfiles_ffi_tampering")
    {
        next = L"review placeholder state, modified-data size, process protection, and live-vs-disk evidence in /json";
    }
    else if (summary.Kind == L"defense_evasion_process_profile")
    {
        next = L"review image path, signature, version info, and staging path in /json";
    }
    else if (summary.Kind == L"process_tampering")
    {
        next = L"review main section, VAD backing, and FILE_OBJECT evidence in /json";
    }
    else if (summary.Kind == L"module_stomping")
    {
        next = L"review module section permissions and live-vs-disk page evidence in /json";
    }
    else if (summary.Kind == L"mapped_code_or_loader_evasion")
    {
        next = L"run !vad and !threads for the subject, or use /details for raw triage tables";
    }
    else
    {
        next = L"use /json for full evidence or /details for raw triage tables";
    }

    return next;
}

static void PrintHuntAssessment(const HuntResult& result)
{
    constexpr size_t maxRows = 4;
    std::vector<HuntConsoleAssessmentSummary> summaries = BuildHuntAssessmentSummaries(result);

    PrintColoredText(L"[hunt.assessment]", result.Findings.empty() ? KNDBG_COLOR_TITLE : KNDBG_COLOR_WARN);
    std::wcout << L" showing=" << std::min(maxRows, summaries.size())
               << L" total_findings=" << result.Findings.size();
    if (result.Findings.empty())
    {
        std::wcout << L" none=yes";
    }
    std::wcout << L"\n";

    if (result.Findings.empty())
    {
        std::wcout << L"  answer=\"no suspicious hunt findings were emitted for the scanned system view\"\n";
        return;
    }

    for (size_t index = 0; index < summaries.size() && index < maxRows; ++index)
    {
        const HuntConsoleAssessmentSummary& summary = summaries[index];
        std::wstring severity = HuntAssessmentSeverityText(summary);
        std::wstring why = HuntAssessmentEvidenceText(summary);

        {
            std::wstringstream row;
            row << L"  #" << (index + 1)
                << L" severity=" << severity
                << L" count=" << summary.Total
                << L" subject=" << HuntConsoleQuotedText(HuntAssessmentSubjectText(summary))
                << L"\n";
            PrintHuntAssessmentLine(summary, row.str());
        }

        if (why == L"-")
        {
            why = L"matched hunt evidence";
        }

        PrintHuntAssessmentLine(
            summary,
            L"     what=" + HuntConsoleQuotedText(HuntAssessmentWhatText(summary.Kind)) + L"\n");
        PrintHuntAssessmentLine(
            summary,
            L"     why=" + HuntConsoleQuotedText(why) + L"\n");
        PrintHuntAssessmentLine(
            summary,
            L"     next=" + HuntConsoleQuotedText(HuntAssessmentNextText(summary)) + L"\n");
    }

    if (summaries.size() > maxRows)
    {
        std::wcout << L"  more_groups=" << (summaries.size() - maxRows)
                   << L" use /details for raw triage tables or /json for full evidence\n";
    }
}

static void PrintHuntTriageTables(const HuntResult& result)
{
    constexpr size_t maxRows = 8;

    std::vector<HuntConsoleProcessSummary> processSummaries = BuildHuntProcessSummaries(result);
    PrintColoredText(L"[hunt.top_processes]", KNDBG_COLOR_TITLE);
    std::wcout << L" showing=" << std::min(maxRows, processSummaries.size())
               << L" total=" << processSummaries.size()
               << L"\n";
    for (size_t index = 0; index < processSummaries.size() && index < maxRows; ++index)
    {
        const HuntConsoleProcessSummary& summary = processSummaries[index];
        std::wstring topReason = HuntDominantReasonText(summary.Reasons);
        std::wcout << L"  #" << (index + 1)
                   << L" pid=" << summary.ProcessId;
        if (summary.ProcessId == 0 && summary.Eprocess == 0 && summary.ImageName.empty())
        {
            std::wcout << L" scope=system";
        }
        if (summary.Eprocess != 0)
        {
            std::wcout << L" eprocess=" << HexTextWidth(summary.Eprocess, 16, true);
        }
        if (!summary.ImageName.empty())
        {
            std::wcout << L" image=" << summary.ImageName;
        }
        std::wcout << L" total=" << summary.Total
                   << L" high=" << summary.High
                   << L" medium=" << summary.Medium
                   << L" low=" << summary.Low;
        if (!topReason.empty())
        {
            std::wcout << L" top_reason=" << topReason;
        }
        std::wcout << L"\n";
    }

    std::vector<HuntConsoleReasonSummary> reasonSummaries = BuildHuntReasonSummaries(result);
    PrintColoredText(L"[hunt.top_reasons]", KNDBG_COLOR_TITLE);
    std::wcout << L" showing=" << std::min(maxRows, reasonSummaries.size())
               << L" total=" << reasonSummaries.size()
               << L"\n";
    for (size_t index = 0; index < reasonSummaries.size() && index < maxRows; ++index)
    {
        const HuntConsoleReasonSummary& summary = reasonSummaries[index];
        std::wcout << L"  #" << (index + 1)
                   << L" reason=" << summary.Reason
                   << L" total=" << summary.Total
                   << L" high=" << summary.High
                   << L" medium=" << summary.Medium
                   << L" low=" << summary.Low
                   << L" system_findings=" << summary.SystemFindings
                   << L" processes=" << summary.ProcessIds.size()
                   << L"\n";
    }
}

static void PrintHuntResult(const HuntResult& result, uint32_t renderLimit, bool summaryOnly)
{
    PrintColoredText(L"!hunt", KNDBG_COLOR_TITLE);
    std::wcout << L" mode=" << result.ModeText
               << L" schema=" << result.Schema
               << L" timestamp=" << result.TimestampUtc
               << L"\n";

    uint64_t warningCount = CountHuntWarnings(result);
    PrintHuntConclusion(result, warningCount);
    PrintHuntAssessment(result);
    PrintHuntSummaryLine(result);

    if (summaryOnly)
    {
        PrintColoredText(L"[hunt.detail]", KNDBG_COLOR_ACCENT);
        std::wcout << L" suppressed=yes raw_tables=yes total_findings=" << result.Findings.size()
                   << L" use /details for raw triage tables or /json for full evidence\n";
        PrintHuntWarnings(result, true);
        return;
    }

    PrintHuntHighSignalTable(result);
    PrintHuntTriageTables(result);

    size_t rendered = 0;
    size_t findingLimit = renderLimit != 0 ? renderLimit : result.Findings.size();
    PrintColoredText(L"[hunt.detail]", KNDBG_COLOR_ACCENT);
    std::wcout << L" showing=" << std::min(findingLimit, result.Findings.size())
               << L" total_findings=" << result.Findings.size();
    if (renderLimit == 0)
    {
        std::wcout << L" limit=all";
    }
    else
    {
        std::wcout << L" limit=" << renderLimit;
    }
    std::wcout << L"\n";

    for (size_t index = 0; index < result.Findings.size() && rendered < findingLimit; ++index)
    {
        PrintHuntFinding(result.Findings[index], index);
        ++rendered;
    }

    if (rendered < result.Findings.size())
    {
        PrintColoredText(L"[hunt.render]", KNDBG_COLOR_ACCENT);
        std::wcout << L" rendered=" << rendered
                   << L" total_findings=" << result.Findings.size()
                   << L" use /json for the full finding set\n";
    }

    PrintHuntWarnings(result, false);
}

static void HandleHuntCommand(
    const std::vector<std::wstring>& args,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    std::wstring error;

    do
    {
        if (args.size() >= 2 && IsHelpToken(args[1]))
        {
            PrintHuntHelp();
            break;
        }

        if (!device.IsOpen())
        {
            std::wcerr << L"!hunt requires the KnLiveDbg.sys driver device to be open\n";
            break;
        }

        HuntOptions options = {};
        std::wstring jsonPath;
        bool summaryOnly = false;
        bool renderDetails = false;
        bool parseOk = true;
        for (size_t index = 1; index < args.size(); ++index)
        {
            std::wstring option = ToLower(args[index]);
            if (option == L"/quick")
            {
                options.Mode = HuntMode::Quick;
            }
            else if (option == L"/deep")
            {
                options.Mode = HuntMode::Deep;
            }
            else if (option == L"/summary")
            {
                summaryOnly = true;
            }
            else if (option == L"/details")
            {
                renderDetails = true;
            }
            else if (option == L"/limit")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!hunt failed: /limit requires a value\n";
                    parseOk = false;
                    break;
                }
                if (!ParseProcessTriageLimit(args[index + 1], state.NumberBase, &options.RenderLimit, &error))
                {
                    std::wcerr << L"!hunt failed: " << error << L"\n";
                    parseOk = false;
                    break;
                }
                renderDetails = true;
                ++index;
            }
            else if (option == L"/json")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!hunt failed: /json requires a path\n";
                    parseOk = false;
                    break;
                }
                jsonPath = args[index + 1];
                ++index;
            }
            else
            {
                std::wcerr << L"!hunt failed: unknown option or target " << args[index] << L"\n";
                std::wcerr << L"!hunt scans the whole system and does not accept a process target\n";
                parseOk = false;
                break;
            }
        }

        if (!parseOk)
        {
            break;
        }

        std::vector<SnapshotProcessRecord> processes;
        std::vector<std::wstring> processWarnings;
        bool processInventoryIncomplete = false;
        if (!BuildSnapshotProcessInventory(
                state,
                device,
                symbols,
                &processes,
                &processWarnings,
                &error,
                &processInventoryIncomplete))
        {
            std::wcerr << L"!hunt process inventory failed: " << error << L"\n";
            break;
        }

        options.Processes = std::move(processes);

        if (options.Mode == HuntMode::Deep)
        {
            TiSubscriber& ti = GetTiSubscriberInstance();
            options.ThreatIntelActive = ti.IsActive();
            TiSubscriberStats tiStats = ti.SnapshotStats();
            options.ThreatIntelEventsDropped = tiStats.EventsDropped;
            std::vector<TiEventRecord> recentTiEvents = ti.Recent(4096, true);
            // An active, successfully queried ring is available even when a
            // quiet host produced zero events.  Event count and collection
            // availability are separate signals.
            options.ThreatIntelAvailable = options.ThreatIntelActive;
            options.ThreatIntelEvents.reserve(recentTiEvents.size());

            for (const TiEventRecord& tiEvent : recentTiEvents)
            {
                HuntTelemetryEvent event = {};
                event.Timestamp = tiEvent.Timestamp;
                event.ProcessId = tiEvent.ProcessId;
                event.TargetProcessId = tiEvent.TargetProcessId;
                event.TaskId = tiEvent.TaskId;
                event.Opcode = tiEvent.Opcode;
                event.TaskName = tiEvent.TaskName;
                event.OpcodeName = tiEvent.OpcodeName;
                event.ImagePath = tiEvent.ImagePath;
                event.TargetImageBase = tiEvent.TargetImageBase;
                event.RawPayloadHex = tiEvent.RawPayloadHex;
                event.Payload.reserve(tiEvent.Payload.size());
                for (const TiPayloadField& field : tiEvent.Payload)
                {
                    HuntTelemetryField huntField = {};
                    huntField.Name = field.Name;
                    huntField.Value = field.Value;
                    event.Payload.push_back(std::move(huntField));
                }
                options.ThreatIntelEvents.push_back(std::move(event));
            }
        }

        UserModeHunter hunter(device, symbols, GetExecutableDirectory());
        HuntResult result = {};
        if (!hunter.Scan(options, &result, &error))
        {
            std::wcerr << L"!hunt failed: " << error << L"\n";
            break;
        }

        result.Warnings.insert(result.Warnings.begin(), processWarnings.begin(), processWarnings.end());
        result.ProcessInventoryIncomplete =
            result.ProcessInventoryIncomplete ||
            processInventoryIncomplete;
        if (result.ProcessInventoryIncomplete)
        {
            result.CoverageComplete = false;
        }

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildHuntJson(result);
        }

        if (!jsonPath.empty())
        {
            if (WriteUtf8TextFile(jsonPath, BuildHuntJson(result), &error))
            {
                std::wcout << L"json written: " << jsonPath << L"\n";
            }
            else
            {
                std::wcerr << L"!hunt json failed: " << error << L"\n";
            }
        }

        PrintHuntResult(result, options.RenderLimit, summaryOnly || !renderDetails);
    } while (false);
}

static void HandleVadCommand(
    const std::vector<std::wstring>& args,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    enum class VadCommandMode
    {
        List,
        InjectionScan,
        Modules
    };

    std::wstring error;

    do
    {
        if (args.size() < 2 || IsHelpToken(args[1]))
        {
            PrintVadHelp();
            break;
        }

        VadCommandMode mode = VadCommandMode::List;
        size_t targetIndex = 1;
        const std::wstring modeToken = ToLower(args[1]);
        if (modeToken == L"scan")
        {
            mode = VadCommandMode::InjectionScan;
            targetIndex = 2;
        }
        else if (modeToken == L"modules" ||
                 modeToken == L"mappedpe")
        {
            mode = VadCommandMode::Modules;
            targetIndex = 2;
        }
        if (targetIndex >= args.size() ||
            IsHelpToken(args[targetIndex]))
        {
            PrintVadHelp();
            break;
        }

        ProcessTriageTarget target = {};
        std::vector<std::wstring> targetWarnings;
        if (!ResolveProcessTriageTarget(
                args[targetIndex],
                state,
                device,
                symbols,
                &target,
                &targetWarnings,
                &error))
        {
            std::wcerr << L"!vad failed: " << error << L"\n";
            break;
        }

        ProcessVadScanOptions options = {};
        options.Target = target;

        std::wstring jsonPath;
        bool summaryOnly = false;
        uint32_t limit = 0;
        bool parseOk = true;
        for (size_t index = targetIndex + 1;
             index < args.size();
             ++index)
        {
            std::wstring option = ToLower(args[index]);

            if (option == L"/summary")
            {
                summaryOnly = true;
            }
            else if (option == L"/exec")
            {
                options.ExecOnly = true;
            }
            else if (option == L"/private")
            {
                options.PrivateOnly = true;
            }
            else if (option == L"/wx")
            {
                options.WxOnly = true;
            }
            else if (option == L"/pe")
            {
                options.ProbePe = true;
                options.PeOnly = true;
            }
            else if (option == L"/hiddenpte" || option == L"/hidden" || option == L"/dkom")
            {
                options.ScanHiddenPtes = true;
            }
            else if (option == L"/scan")
            {
                if (mode == VadCommandMode::Modules)
                {
                    std::wcerr << L"!vad failed: /scan conflicts with modules mode\n";
                    parseOk = false;
                    break;
                }
                mode = VadCommandMode::InjectionScan;
            }
            else if (option == L"/modules" ||
                     option == L"/mappedpe")
            {
                if (mode == VadCommandMode::InjectionScan)
                {
                    std::wcerr << L"!vad failed: /modules conflicts with scan mode\n";
                    parseOk = false;
                    break;
                }
                mode = VadCommandMode::Modules;
            }
            else if (option == L"/limit")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!vad failed: /limit requires a value\n";
                    parseOk = false;
                    break;
                }
                if (!ParseProcessTriageLimit(
                        args[index + 1],
                        state.NumberBase,
                        &limit,
                        &error))
                {
                    std::wcerr << L"!vad failed: " << error << L"\n";
                    parseOk = false;
                    break;
                }
                ++index;
            }
            else if (option == L"/json")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!vad failed: /json requires a path\n";
                    parseOk = false;
                    break;
                }
                jsonPath = args[index + 1];
                ++index;
            }
            else
            {
                std::wcerr << L"!vad failed: unknown option " << args[index] << L"\n";
                parseOk = false;
                break;
            }
        }

        if (!parseOk)
        {
            break;
        }

        if (mode == VadCommandMode::Modules &&
            (options.ExecOnly ||
             options.PrivateOnly ||
             options.WxOnly ||
             options.PeOnly ||
             options.ScanHiddenPtes))
        {
            std::wcerr << L"!vad failed: modules mode accepts only /summary, /limit, and /json\n";
            break;
        }

        ProcessTriageScanner scanner(device, symbols);
        if (mode == VadCommandMode::Modules)
        {
            ProcessMappedPeScanOptions mappedOptions = {};
            mappedOptions.Target = target;
            mappedOptions.Limit = limit;
            ProcessMappedPeScanResult result = {};
            if (!scanner.ScanMappedPe(
                    mappedOptions,
                    &result,
                    &error))
            {
                std::wcerr << L"!vad modules failed: "
                           << error << L"\n";
                break;
            }

            result.Warnings.insert(
                result.Warnings.begin(),
                targetWarnings.begin(),
                targetWarnings.end());
            PrintMappedPeScanResult(result, summaryOnly);
            PrintProcessTriageWarnings(
                L"!vad modules",
                result.Warnings);
            const std::wstring json =
                BuildProcessMappedPeJson(result);
            if (structuredJsonOut != nullptr)
            {
                *structuredJsonOut = json;
            }
            if (!jsonPath.empty())
            {
                if (WriteUtf8TextFile(jsonPath, json, &error))
                {
                    std::wcout << L"json written: "
                               << jsonPath << L"\n";
                }
                else
                {
                    std::wcerr << L"!vad modules json failed: "
                               << error << L"\n";
                }
            }
            break;
        }

        options.SummaryOnly = summaryOnly;
        options.Limit = limit;
        if (mode == VadCommandMode::InjectionScan)
        {
            options.InjectionScan = true;
            options.ProbePe = true;
            options.ScanHiddenPtes = true;
            options.HiddenPteExecutableOnly = true;
            options.RequireVadCoverageForHiddenPtes = true;
        }

        ProcessVadScanResult result = {};
        if (!scanner.ScanVad(options, &result, &error))
        {
            std::wcerr << L"!vad failed: " << error << L"\n";
            break;
        }

        result.Warnings.insert(result.Warnings.begin(), targetWarnings.begin(), targetWarnings.end());
        PrintVadScanResult(result, summaryOnly);
        PrintProcessTriageWarnings(L"!vad", result.Warnings);

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildProcessVadJson(result);
        }

        if (!jsonPath.empty())
        {
            if (WriteUtf8TextFile(jsonPath, BuildProcessVadJson(result), &error))
            {
                std::wcout << L"json written: " << jsonPath << L"\n";
            }
            else
            {
                std::wcerr << L"!vad json failed: " << error << L"\n";
            }
        }
    } while (false);
}

static void HandleThreadsCommand(
    const std::vector<std::wstring>& args,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* structuredJsonOut = nullptr)
{
    std::wstring error;

    do
    {
        if (args.size() < 2 || IsHelpToken(args[1]))
        {
            PrintThreadsHelp();
            break;
        }

        ProcessThreadScanOptions options = {};
        std::vector<std::wstring> targetWarnings;
        if (!ResolveProcessTriageTarget(args[1], state, device, symbols, &options.Target, &targetWarnings, &error))
        {
            std::wcerr << L"!threads failed: " << error << L"\n";
            break;
        }

        std::wstring jsonPath;
        bool parseOk = true;
        bool summaryOnly = false;
        for (size_t index = 2; index < args.size(); ++index)
        {
            std::wstring option = ToLower(args[index]);

            if (option == L"/summary")
            {
                summaryOnly = true;
            }
            else if (option == L"/apc")
            {
                options.IncludeApc = true;
            }
            else if (option == L"/stacks")
            {
                options.IncludeStacks = true;
            }
            else if (option == L"/limit")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!threads failed: /limit requires a value\n";
                    parseOk = false;
                    break;
                }
                if (!ParseProcessTriageLimit(args[index + 1], state.NumberBase, &options.Limit, &error))
                {
                    std::wcerr << L"!threads failed: " << error << L"\n";
                    parseOk = false;
                    break;
                }
                ++index;
            }
            else if (option == L"/json")
            {
                if (index + 1 >= args.size())
                {
                    std::wcerr << L"!threads failed: /json requires a path\n";
                    parseOk = false;
                    break;
                }
                jsonPath = args[index + 1];
                ++index;
            }
            else
            {
                std::wcerr << L"!threads failed: unknown option " << args[index] << L"\n";
                parseOk = false;
                break;
            }
        }

        if (!parseOk)
        {
            break;
        }

        ProcessTriageScanner scanner(device, symbols);
        ProcessThreadScanResult result = {};
        if (!scanner.ScanThreads(options, &result, &error))
        {
            std::wcerr << L"!threads failed: " << error << L"\n";
            break;
        }

        result.Warnings.insert(result.Warnings.begin(), targetWarnings.begin(), targetWarnings.end());
        PrintThreadScanResult(result, options.IncludeStacks, options.IncludeApc, summaryOnly);
        PrintProcessTriageWarnings(L"!threads", result.Warnings);

        if (structuredJsonOut != nullptr)
        {
            *structuredJsonOut = BuildProcessThreadsJson(result);
        }

        if (!jsonPath.empty())
        {
            if (WriteUtf8TextFile(jsonPath, BuildProcessThreadsJson(result), &error))
            {
                std::wcout << L"json written: " << jsonPath << L"\n";
            }
            else
            {
                std::wcerr << L"!threads json failed: " << error << L"\n";
            }
        }
    } while (false);
}

static bool TryExtractPidFromAiQuery(const std::vector<std::wstring>& tokens, uint64_t* pid)
{
    bool found = false;

    do
    {
        if (pid == nullptr)
        {
            break;
        }

        for (size_t index = 0; index < tokens.size(); ++index)
        {
            std::wstring token = ToLower(TrimAiQueryToken(tokens[index]));
            if (token.empty())
            {
                continue;
            }

            std::wstring value;
            if (token == L"pid" || token == L"processid" || token == L"process-id")
            {
                if (index + 1 < tokens.size())
                {
                    value = TrimAiQueryToken(tokens[index + 1]);
                }
            }
            else if (token.rfind(L"pid=", 0) == 0)
            {
                value = token.substr(4);
            }

            uint64_t parsed = 0;
            uint64_t ignoredEprocess = 0;
            if (!value.empty() &&
                ClassifyProcessSpecifier(value, 0, &parsed, &ignoredEprocess) == ProcessSpecifierKind::Pid)
            {
                *pid = parsed;
                found = true;
                break;
            }
        }
    } while (false);

    return found;
}

static bool TryExtractEprocessFromAiQuery(
    const std::vector<std::wstring>& tokens,
    const DebuggerState& state,
    uint64_t* eprocess)
{
    bool found = false;

    do
    {
        if (eprocess == nullptr)
        {
            break;
        }

        for (size_t index = 0; index < tokens.size(); ++index)
        {
            std::wstring token = TrimAiQueryToken(tokens[index]);
            std::wstring lowered = ToLower(token);
            std::wstring value = token;

            if (lowered == L"eprocess" || lowered == L"_eprocess")
            {
                if (index + 1 < tokens.size())
                {
                    value = TrimAiQueryToken(tokens[index + 1]);
                }
                else
                {
                    value.clear();
                }
            }
            else if (lowered.rfind(L"eprocess=", 0) == 0)
            {
                value = token.substr(9);
            }
            else if (lowered.rfind(L"_eprocess=", 0) == 0)
            {
                value = token.substr(10);
            }

            uint64_t parsed = 0;
            if (!value.empty() &&
                ParseUnsigned(value, state.NumberBase, &parsed) &&
                IsLikelyKernelVirtualAddress(parsed))
            {
                *eprocess = parsed;
                found = true;
                break;
            }
        }
    } while (false);

    return found;
}

static AiProcessIntent ParseAiProcessIntent(const std::wstring& query, const DebuggerState& state)
{
    AiProcessIntent intent = {};
    std::wstring lowered = ToLower(query);
    std::vector<std::wstring> tokens = Split(query);
    bool hasProcessWord = ContainsAiQueryWord(lowered, L"process") ||
        ContainsNoCase(lowered, L"\xD504\xB85C\xC138\xC2A4");

    intent.ImageName = ExtractExeImageNameFromQuery(query);
    intent.WantsPid = ContainsNoCase(lowered, L"pid") ||
        ContainsNoCase(lowered, L"process id") ||
        ContainsNoCase(lowered, L"process-id");
    intent.WantsEprocess = ContainsNoCase(lowered, L"eprocess");
    intent.WantsDtb = ContainsNoCase(lowered, L"dtb") ||
        ContainsNoCase(lowered, L"dirbase") ||
        ContainsNoCase(lowered, L"directorytablebase") ||
        ContainsNoCase(lowered, L"cr3");
    intent.WantsPeb = ContainsNoCase(lowered, L"peb");
    intent.WantsInfo = ContainsNoCase(lowered, L"info") ||
        ContainsNoCase(lowered, L"summary") ||
        hasProcessWord;
    intent.HasPid = TryExtractPidFromAiQuery(tokens, &intent.Pid);
    intent.HasEprocess = TryExtractEprocessFromAiQuery(tokens, state, &intent.Eprocess);

    if (!intent.ImageName.empty() ||
        intent.HasPid ||
        (intent.HasEprocess &&
            (intent.WantsPid || intent.WantsEprocess || intent.WantsDtb || intent.WantsPeb || intent.WantsInfo)) ||
        ((intent.WantsPid || intent.WantsEprocess || intent.WantsDtb || intent.WantsPeb) &&
            hasProcessWord))
    {
        intent.IsProcessQuery = true;
    }

    if (intent.IsProcessQuery &&
        !intent.WantsPid &&
        !intent.WantsEprocess &&
        !intent.WantsDtb &&
        !intent.WantsPeb)
    {
        intent.WantsInfo = true;
    }

    return intent;
}

static bool AiProcessRecordMatchesIntent(const DmlProcessRecord& record, const AiProcessIntent& intent)
{
    bool matched = true;

    do
    {
        if (!intent.ImageName.empty())
        {
            if (!ProcessImageNameMatches(record.ImageName, intent.ImageName))
            {
                matched = false;
                break;
            }
        }

        if (intent.HasPid)
        {
            if (record.ProcessId != intent.Pid)
            {
                matched = false;
                break;
            }
        }

        if (intent.HasEprocess)
        {
            if (record.Eprocess != intent.Eprocess)
            {
                matched = false;
                break;
            }
        }
    } while (false);

    return matched;
}

static void PrintAiProcessAnswerLine(const DmlProcessRecord& record, const AiProcessIntent& intent)
{
    bool any = false;

    if (intent.WantsPid || intent.WantsInfo)
    {
        std::wcout << L"pid=" << std::dec << record.ProcessId;
        any = true;
    }

    if (intent.WantsEprocess || intent.WantsInfo)
    {
        std::wcout << (any ? L" " : L"");
        std::wcout << L"eprocess=" << HexTextWidth(record.Eprocess, 16, true);
        any = true;
    }

    if (intent.WantsDtb || intent.WantsInfo)
    {
        std::wcout << (any ? L" " : L"");
        std::wcout << L"dirbase=" << HexTextWidth(record.DirectoryTableBase, 16, true);
        if (record.UserDirectoryTableBase != 0)
        {
            std::wcout << L" userdirbase=" << HexTextWidth(record.UserDirectoryTableBase, 16, true);
        }
        any = true;
    }

    if (intent.WantsPeb || intent.WantsInfo)
    {
        std::wcout << (any ? L" " : L"");
        if (record.HasPeb)
        {
            std::wcout << L"peb=" << HexTextWidth(record.Peb, 16, true);
        }
        else
        {
            std::wcout << L"peb=<unavailable>";
        }
        any = true;
    }

    if (!any)
    {
        std::wcout << L"pid=" << std::dec << record.ProcessId
                   << L" eprocess=" << HexTextWidth(record.Eprocess, 16, true);
    }

    std::wcout << L"\n";
}

static void PrintAiProcessNextCommands(const DmlProcessRecord& record)
{
    std::wcout << L"next:\n";
    std::wcout << L"  dt nt!_EPROCESS " << HexTextWidth(record.Eprocess, 16, true) << L"\n";
    std::wcout << L"  procctx " << std::dec << record.ProcessId << L"\n";
    std::wcout << L"  db /process " << std::dec << record.ProcessId << L" <user-va> 80\n";
    std::wcout << L"  vtop /process " << std::dec << record.ProcessId << L" <user-va>\n";
}

static bool AiQueryHasNonProcessInvestigation(const std::wstring& query)
{
    static const std::vector<std::wstring> needles =
    {
        L"vad",
        L"thread",
        L"callback",
        L"handle",
        L"hunt",
        L"payload",
        L"mapper",
        L"kpage",
        L"integrity",
        L"ssdt",
        L"idt",
        L"wfp",
        L"alpc",
        L"minifilter",
        L"hidden",
        L"token",
        L"pool",
        L"wnf",
        L"etw",
        L"nmi",
        L"module",
        L"driver",
        L"dma",
        L"snapshot",
        L"vbs",
        L"hvci",
        L"byovd",
        L"hypervisor",
        L"\xCF5C\xBC31",
        L"\xD578\xB4E4",
        L"\xC228\xC740",
        L"\xC740\xB2C9",
        L"\xBB34\xACB0\xC131"
    };

    return ContainsAnyNoCase(query, needles);
}

static bool TryHandleAiProcessQuery(
    const std::wstring& query,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    AiPlanState* aiState)
{
    bool handled = false;

    do
    {
        AiProcessIntent intent = ParseAiProcessIntent(query, state);
        if (!intent.IsProcessQuery)
        {
            break;
        }
        if (AiQueryHasNonProcessInvestigation(query) || FindAiPlaybook(query) != nullptr)
        {
            break;
        }

        handled = true;

        DmlProcessCollection collection = {};
        std::wstring error;
        if (!CollectDmlProcessRecords(state, device, symbols, &collection, &error))
        {
            std::wcerr << L"ai local process query failed: " << error << L"\n";
            break;
        }

        std::vector<DmlProcessRecord> matches;
        for (const DmlProcessRecord& record : collection.Records)
        {
            if (AiProcessRecordMatchesIntent(record, intent))
            {
                matches.push_back(record);
            }
        }

        PrintColoredText(L"ai local", KNDBG_COLOR_TITLE);
        std::wcout << L": process query\n";

        if (matches.empty())
        {
            std::wcout << L"matches=0";
            if (!intent.ImageName.empty())
            {
                std::wcout << L" image=" << intent.ImageName;
            }
            if (intent.HasPid)
            {
                std::wcout << L" pid=" << std::dec << intent.Pid;
            }
            if (intent.HasEprocess)
            {
                std::wcout << L" eprocess=" << HexTextWidth(intent.Eprocess, 16, true);
            }
            std::wcout << L"\n";
            std::wcout << L"next:\n";
            std::wcout << L"  !dml_proc\n";
            break;
        }

        PrintDmlProcessHeader();
        for (const DmlProcessRecord& record : matches)
        {
            PrintDmlProcessRecord(record);
        }

        PrintColoredText(L"matches", KNDBG_COLOR_TITLE);
        std::wcout << L"=" << matches.size();
        if (collection.Truncated)
        {
            std::wcout << L" truncated=yes";
        }
        if (collection.Incomplete)
        {
            std::wcout << L" incomplete=yes failedReads=" << std::dec << collection.FailedReadCount;
        }
        std::wcout << L"\n";

        for (const std::wstring& warning : collection.Warnings)
        {
            std::wcerr << L"ai local warning: " << warning << L"\n";
        }

        if (matches.size() == 1)
        {
            PrintColoredText(L"answer", KNDBG_COLOR_TITLE);
            std::wcout << L": ";
            PrintAiProcessAnswerLine(matches[0], intent);
            PrintAiProcessNextCommands(matches[0]);
            if (aiState != nullptr)
            {
                aiState->LastPid = static_cast<uint32_t>(matches[0].ProcessId);
                aiState->LastImage = matches[0].ImageName;
            }
        }
        else
        {
            std::wcout << L"answer: multiple matches; use pid or eprocess to narrow the query\n";
            if (aiState != nullptr && !intent.ImageName.empty())
            {
                aiState->LastImage = intent.ImageName;
            }
        }
    } while (false);

    return handled;
}

static bool TryHandleAiLocalQuery(
    const std::wstring& query,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    AiPlanState* aiState)
{
    bool handled = false;

    do
    {
        if (TryHandleAiProcessQuery(query, state, device, symbols, aiState))
        {
            handled = true;
            break;
        }
    } while (false);

    return handled;
}

enum class AiCapabilityQueryResult
{
    NotAttempted,
    Handled,
    Failed,
    Deferred
};

struct AiCapabilityStep
{
    std::wstring Tool;
    std::wstring ArgsJson;
};

struct AiCapabilityPlan
{
    std::wstring Schema;
    std::wstring Summary;
    std::wstring RawResponse;
    std::vector<AiCapabilityStep> Steps;
};

struct AiCapabilityProcessFilter
{
    bool HasImage = false;
    std::wstring Image;
    bool HasPid = false;
    uint64_t Pid = 0;
    bool HasEprocess = false;
    uint64_t Eprocess = 0;
};

struct AiCapabilityStepResult
{
    bool HasProcesses = false;
    std::vector<DmlProcessRecord> Processes;
};

static bool TryParseAiCapabilitySourceIndex(const std::wstring& source, size_t* index)
{
    bool ok = false;

    do
    {
        if (index == nullptr || source.size() < 2 || source[0] != L'$')
        {
            break;
        }

        uint64_t parsed = 0;
        if (!ParseUnsigned(source.substr(1), 10, &parsed) ||
            parsed > static_cast<uint64_t>(std::numeric_limits<size_t>::max()))
        {
            break;
        }

        *index = static_cast<size_t>(parsed);
        ok = true;
    } while (false);

    return ok;
}

static std::wstring NormalizeAiCapabilityProcessField(const std::wstring& value)
{
    std::wstring field = ToLower(TrimWhitespace(value));

    if (field == L"name" || field == L"image" || field == L"imagename" || field == L"image_name")
    {
        field = L"image";
    }
    else if (field == L"processid" || field == L"process_id")
    {
        field = L"pid";
    }
    else if (field == L"address" || field == L"_eprocess")
    {
        field = L"eprocess";
    }
    else if (field == L"directorytablebase" || field == L"directory_table_base" || field == L"dirbase" || field == L"cr3")
    {
        field = L"dtb";
    }
    else if (field == L"userdirectorytablebase" || field == L"user_directory_table_base" || field == L"userdirbase")
    {
        field = L"userdtb";
    }
    else if (field == L"parent" || field == L"parentpid" || field == L"ppid")
    {
        field = L"ppid";
    }
    else if (field == L"active_threads" || field == L"activethreads")
    {
        field = L"threads";
    }

    return field;
}

static bool IsSupportedAiCapabilityProcessField(const std::wstring& field)
{
    return field == L"all" ||
        field == L"pid" ||
        field == L"image" ||
        field == L"eprocess" ||
        field == L"dtb" ||
        field == L"userdtb" ||
        field == L"peb" ||
        field == L"ppid" ||
        field == L"threads";
}

static std::vector<std::wstring> NormalizeAiCapabilityProcessFields(
    const std::vector<std::wstring>& rawFields,
    std::wstring* error)
{
    std::vector<std::wstring> fields;

    do
    {
        for (const std::wstring& rawField : rawFields)
        {
            std::wstring field = NormalizeAiCapabilityProcessField(rawField);
            if (field.empty())
            {
                continue;
            }

            if (!IsSupportedAiCapabilityProcessField(field))
            {
                if (error != nullptr)
                {
                    *error = L"unsupported process field: " + rawField;
                }
                fields.clear();
                break;
            }

            if (field == L"all")
            {
                fields.clear();
                break;
            }

            bool exists = false;
            for (const std::wstring& existing : fields)
            {
                if (existing == field)
                {
                    exists = true;
                    break;
                }
            }

            if (!exists)
            {
                fields.push_back(field);
            }
        }
    } while (false);

    return fields;
}

static std::vector<std::wstring> DefaultAiCapabilityProcessFields()
{
    std::vector<std::wstring> fields;
    fields.push_back(L"pid");
    fields.push_back(L"image");
    fields.push_back(L"eprocess");
    fields.push_back(L"dtb");
    fields.push_back(L"peb");
    return fields;
}

static bool ParseAiCapabilityProcessFilter(
    const std::wstring& argsJson,
    const DebuggerState& state,
    AiCapabilityProcessFilter* filter,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (filter == nullptr)
        {
            break;
        }

        *filter = AiCapabilityProcessFilter{};

        std::wstring image;
        if (!ExtractJsonStringValue(argsJson, L"image", &image))
        {
            ExtractJsonStringValue(argsJson, L"name", &image);
        }
        if (image.empty())
        {
            ExtractJsonStringValue(argsJson, L"process", &image);
        }
        if (!TrimWhitespace(image).empty())
        {
            filter->HasImage = true;
            filter->Image = TrimWhitespace(image);
        }

        std::wstring pidText;
        if (ExtractJsonScalarValue(argsJson, L"pid", &pidText) && !TrimWhitespace(pidText).empty())
        {
            uint64_t parsed = 0;
            uint64_t ignoredEprocess = 0;
            if (ClassifyProcessSpecifier(
                    TrimWhitespace(pidText),
                    0,
                    &parsed,
                    &ignoredEprocess) != ProcessSpecifierKind::Pid)
            {
                if (error != nullptr)
                {
                    *error = L"invalid process pid: " + pidText;
                }
                break;
            }

            filter->HasPid = true;
            filter->Pid = parsed;
        }

        std::wstring eprocessText;
        if (ExtractJsonScalarValue(argsJson, L"eprocess", &eprocessText) && !TrimWhitespace(eprocessText).empty())
        {
            uint64_t parsed = 0;
            if (!ParseUnsigned(TrimWhitespace(eprocessText), state.NumberBase, &parsed) ||
                !IsLikelyKernelVirtualAddress(parsed))
            {
                if (error != nullptr)
                {
                    *error = L"invalid EPROCESS address: " + eprocessText;
                }
                break;
            }

            filter->HasEprocess = true;
            filter->Eprocess = parsed;
        }

        ok = true;
    } while (false);

    return ok;
}

static bool AiCapabilityRecordMatchesFilter(
    const DmlProcessRecord& record,
    const AiCapabilityProcessFilter& filter)
{
    bool matched = true;

    do
    {
        if (filter.HasImage && !ProcessImageNameMatches(record.ImageName, filter.Image))
        {
            matched = false;
            break;
        }

        if (filter.HasPid && record.ProcessId != filter.Pid)
        {
            matched = false;
            break;
        }

        if (filter.HasEprocess && record.Eprocess != filter.Eprocess)
        {
            matched = false;
            break;
        }
    } while (false);

    return matched;
}

static bool HasAiCapabilityProcessFilterArg(const std::wstring& argsJson)
{
    bool hasFilter = false;
    std::wstring value;

    do
    {
        if (ExtractJsonStringValue(argsJson, L"image", &value) ||
            ExtractJsonStringValue(argsJson, L"name", &value) ||
            ExtractJsonStringValue(argsJson, L"process", &value) ||
            ExtractJsonScalarValue(argsJson, L"pid", &value) ||
            ExtractJsonScalarValue(argsJson, L"eprocess", &value))
        {
            hasFilter = true;
            break;
        }
    } while (false);

    return hasFilter;
}

static bool CollectAiCapabilityProcessMatches(
    const std::wstring& argsJson,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::vector<DmlProcessRecord>* matches,
    bool* truncated,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (matches == nullptr || truncated == nullptr)
        {
            break;
        }

        matches->clear();
        *truncated = false;

        AiCapabilityProcessFilter filter = {};
        if (!ParseAiCapabilityProcessFilter(argsJson, state, &filter, error))
        {
            break;
        }

        DmlProcessCollection collection = {};
        if (!CollectDmlProcessRecords(state, device, symbols, &collection, error))
        {
            break;
        }

        for (const DmlProcessRecord& record : collection.Records)
        {
            if (AiCapabilityRecordMatchesFilter(record, filter))
            {
                matches->push_back(record);
            }
        }

        *truncated = collection.Truncated;
        for (const std::wstring& warning : collection.Warnings)
        {
            std::wcerr << L"ai tool warning: " << warning << L"\n";
        }

        ok = true;
    } while (false);

    return ok;
}

static bool ResolveAiCapabilityProcessInput(
    const std::wstring& argsJson,
    const std::vector<AiCapabilityStepResult>& results,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::vector<DmlProcessRecord>* records,
    bool* truncated,
    std::wstring* error)
{
    bool ok = false;

    do
    {
        if (records == nullptr || truncated == nullptr)
        {
            break;
        }

        records->clear();
        *truncated = false;

        std::wstring source;
        ExtractJsonStringValue(argsJson, L"source", &source);
        if (!TrimWhitespace(source).empty())
        {
            size_t sourceIndex = 0;
            if (!TryParseAiCapabilitySourceIndex(TrimWhitespace(source), &sourceIndex) ||
                sourceIndex >= results.size() ||
                !results[sourceIndex].HasProcesses)
            {
                if (error != nullptr)
                {
                    *error = L"invalid process source reference: " + source;
                }
                break;
            }

            *records = results[sourceIndex].Processes;
            ok = true;
            break;
        }

        if (!results.empty() && results.back().HasProcesses)
        {
            if (!HasAiCapabilityProcessFilterArg(argsJson))
            {
                *records = results.back().Processes;
                ok = true;
                break;
            }
        }

        ok = CollectAiCapabilityProcessMatches(argsJson, state, device, symbols, records, truncated, error);
    } while (false);

    return ok;
}

static void PrintAiCapabilityProcessValue(
    const DmlProcessRecord& record,
    const std::wstring& field,
    bool* any)
{
    if (any != nullptr && *any)
    {
        std::wcout << L" ";
    }

    if (field == L"pid")
    {
        std::wcout << L"pid=" << std::dec << record.ProcessId;
    }
    else if (field == L"image")
    {
        std::wcout << L"image=" << record.ImageName;
    }
    else if (field == L"eprocess")
    {
        std::wcout << L"eprocess=" << HexTextWidth(record.Eprocess, 16, true);
    }
    else if (field == L"dtb")
    {
        std::wcout << L"dirbase=" << HexTextWidth(record.DirectoryTableBase, 16, true);
    }
    else if (field == L"userdtb")
    {
        std::wcout << L"userdirbase=" << HexTextWidth(record.UserDirectoryTableBase, 16, true);
    }
    else if (field == L"peb")
    {
        if (record.HasPeb)
        {
            std::wcout << L"peb=" << HexTextWidth(record.Peb, 16, true);
        }
        else
        {
            std::wcout << L"peb=<unavailable>";
        }
    }
    else if (field == L"ppid")
    {
        if (record.HasParentProcessId)
        {
            std::wcout << L"ppid=" << std::dec << record.ParentProcessId;
        }
        else
        {
            std::wcout << L"ppid=<unavailable>";
        }
    }
    else if (field == L"threads")
    {
        if (record.HasActiveThreads)
        {
            std::wcout << L"threads=" << std::dec << record.ActiveThreads;
        }
        else
        {
            std::wcout << L"threads=<unavailable>";
        }
    }

    if (any != nullptr)
    {
        *any = true;
    }
}

static void PrintAiCapabilityProcessDescriptions(
    const std::vector<DmlProcessRecord>& records,
    const std::vector<std::wstring>& rawFields)
{
    std::wstring error;
    std::vector<std::wstring> fields = NormalizeAiCapabilityProcessFields(rawFields, &error);
    if (!error.empty())
    {
        std::wcerr << L"ai tool warning: " << error << L"\n";
        fields = DefaultAiCapabilityProcessFields();
    }
    else if (fields.empty())
    {
        fields = DefaultAiCapabilityProcessFields();
    }

    for (size_t index = 0; index < records.size(); ++index)
    {
        std::wcout << L"[" << index << L"] ";
        bool any = false;
        for (const std::wstring& field : fields)
        {
            PrintAiCapabilityProcessValue(records[index], field, &any);
        }
        std::wcout << L"\n";
    }
}

static bool IsSupportedAiCapabilityTool(const std::wstring& tool)
{
    bool supported = false;

    do
    {
        if (IsAiCapabilityCatalogTool(tool))
        {
            supported = true;
            break;
        }

        // firmwaretable.list is an internal alias of fwtable.list. ti.subscribe
        // is MCP/lifecycle and is not advertised in the shared planner catalog.
        // code.disasm stays excluded: ExecuteAiCapabilityPlan has no DbgEng handle.
        if (tool == L"firmwaretable.list" || tool == L"ti.subscribe")
        {
            supported = true;
            break;
        }
    } while (false);

    return supported;
}

