// ti.subscribe controls the Threat-Intelligence ETW subscription lifecycle
// (start/stop/status). start/stop create/tear down a system-global ETW session
// and lazily write a log file, so they are gated behind --allow-write; status
// is a read. Reuses HandleTiCommand so the PPL self-gate and shutdown-hook
// registration are inherited verbatim.
static bool ExecuteAiCapabilityTiSubscribe(
    const AiCapabilityStep& step,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* error,
    std::wstring* structuredJsonOut = nullptr)
{
    bool ok = false;

    do
    {
        std::wstring action;
        ExtractJsonStringValue(step.ArgsJson, L"action", &action);
        action = ToLower(TrimWhitespace(action));
        if (action.empty())
        {
            action = L"status";
        }
        if (action != L"start" && action != L"stop" && action != L"status")
        {
            if (error != nullptr)
            {
                *error = L"ti.subscribe action must be start, stop, or status";
            }
            break;
        }

        if ((action == L"start" || action == L"stop") && !g_McpServer.AllowWrite())
        {
            if (error != nullptr)
            {
                *error = L"ti.subscribe " + action +
                         L" mutates capture state (system ETW session); start the MCP server with --allow-write";
            }
            break;
        }

        std::vector<std::wstring> args;
        args.push_back(L"!ti");
        args.push_back(action);

        PrintColoredText(L"ai tool", KNDBG_COLOR_TITLE);
        std::wcout << L": ti.subscribe\n";
        std::wcout << L"tool> " << JoinArgs(args, 0) << L"\n";
        HandleTiCommand(args, state, device, symbols);

        if (structuredJsonOut != nullptr)
        {
            TiSubscriber& ti = GetTiSubscriberInstance();
            *structuredJsonOut = BuildMcpTiStatsJson(ti.SnapshotStats(), ti.IsActive());
        }
        ok = true;
    } while (false);

    return ok;
}

static bool ExecuteAiCapabilityModuleIntegrity(
    const AiCapabilityStep& step,
    DebuggerState& state,
    DeviceClient& device,
    SymbolEngine& symbols,
    std::wstring* error,
    std::wstring* structuredJsonOut = nullptr)
{
    bool ok = false;

    do
    {
        if (!device.IsOpen())
        {
            if (error != nullptr)
            {
                *error = L"module.integrity requires the KnLiveDbg.sys driver device to be open";
            }
            break;
        }

        std::wstring target;
        ExtractAiCapabilityScalarAlias(step.ArgsJson, {L"module", L"name", L"target"}, &target);
        if (!target.empty() && !ValidateAiCapabilityScalarText(target, L"module target", error))
        {
            break;
        }
        if (!target.empty() && IsSwitchLikeToken(target))
        {
            if (error != nullptr)
            {
                *error = L"module target cannot be an option token";
            }
            break;
        }

        std::vector<std::wstring> args;
        args.push_back(L"!module");
        args.push_back(L"integrity");
        if (!target.empty())
        {
            args.push_back(target);
        }
        if (!AppendAiCapabilityLimitOption(step.ArgsJson, state, &args, error))
        {
            break;
        }

        bool summaryOnly = false;
        bool verbose = false;
        bool headers = false;
        bool sections = false;
        bool wx = false;
        bool mismatch = false;
        bool disk = false;
        bool iat = false;
        bool prologue = false;
        if (!ExtractAiCapabilityBooleanArg(step.ArgsJson, L"summary", &summaryOnly, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"verbose", &verbose, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"headers", &headers, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"sections", &sections, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"wx", &wx, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"mismatch", &mismatch, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"disk", &disk, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"iat", &iat, error) ||
            !ExtractAiCapabilityBooleanArg(step.ArgsJson, L"prologue", &prologue, error))
        {
            break;
        }
        if (summaryOnly)
        {
            args.push_back(L"/summary");
        }
        if (verbose)
        {
            args.push_back(L"/verbose");
        }
        if (headers)
        {
            args.push_back(L"/headers");
        }
        if (sections)
        {
            args.push_back(L"/sections");
        }
        if (wx)
        {
            args.push_back(L"/wx");
        }
        if (mismatch)
        {
            args.push_back(L"/mismatch");
        }
        if (disk)
        {
            args.push_back(L"/disk");
        }
        if (iat)
        {
            args.push_back(L"/iat");
        }
        if (prologue)
        {
            args.push_back(L"/prologue");
        }

        PrintColoredText(L"ai tool", KNDBG_COLOR_TITLE);
        std::wcout << L": module.integrity\n";
        std::wcout << L"tool> " << JoinArgs(args, 0) << L"\n";
        HandleModuleIntegrityCommand(args, state, device, symbols, structuredJsonOut);
        ok = true;
    } while (false);

    return ok;
}

