static std::wstring BuildMcpLoadEnvPowerShell(const std::wstring& endpointPath)
{
    std::wstring ps;
    ps += L"# Load KnLiveDbg MCP endpoint into the current PowerShell session.\n";
    ps += L"# Dot-source this file before starting a native MCP client.\n";
    ps += L"$ErrorActionPreference = 'Stop'\n";
    ps += L"$p = " + PowerShellSingleQuoted(endpointPath) + L"\n";
    ps += L"if (-not (Test-Path -LiteralPath $p -PathType Leaf)) { throw \"missing $p -- run 'mcp on' first\" }\n";
    ps += L"$e = Get-Content -LiteralPath $p -Raw -Encoding UTF8 | ConvertFrom-Json\n";
    ps += L"$token = [string]$e.token\n";
    ps += L"if ([string]::IsNullOrWhiteSpace($token)) { $token = [string]$e.password }\n";
    ps += L"$url = [string]$e.url\n";
    ps += L"if ([string]::IsNullOrWhiteSpace($token) -or $token.Length -lt 4) { throw \"invalid password in $p\" }\n";
    ps += L"$parsedUrl = $null\n";
    ps += L"if (-not [Uri]::TryCreate($url, [UriKind]::Absolute, [ref]$parsedUrl) -or $parsedUrl.Scheme -ne 'http' -or -not $parsedUrl.IsLoopback) { throw \"invalid loopback URL in $p\" }\n";
    ps += L"$env:KNLIVEDBG_TOKEN = $token\n";
    ps += L"$env:KNLIVEDBG_MCP_URL = $parsedUrl.AbsoluteUri.TrimEnd('/')\n";
    ps += L"$env:KNLIVEDBG_MCP_ENDPOINT = $p\n";
    ps += L"Write-Host (\"KNLIVEDBG_MCP_URL={0}\" -f $env:KNLIVEDBG_MCP_URL)\n";
    ps += L"Write-Host 'KNLIVEDBG_TOKEN set (value hidden)'\n";
    return ps;
}

static bool WriteMcpLoadEnvScript(
    const std::wstring& path,
    const std::wstring& endpointPath)
{
    return WriteUtf8TextFile(path, BuildMcpLoadEnvPowerShell(endpointPath));
}

static std::wstring ResolveMcpClientSetupUrl()
{
    const std::wstring fallback = L"http://127.0.0.1:51766/mcp";
    const std::wstring endpointPath = GetMcpEndpointPath();
    HANDLE file = CreateFileW(
        endpointPath.c_str(),
        GENERIC_READ,
        FILE_SHARE_READ,
        nullptr,
        OPEN_EXISTING,
        FILE_ATTRIBUTE_NORMAL,
        nullptr);
    if (file == INVALID_HANDLE_VALUE)
    {
        return fallback;
    }

    std::string bytes(8192, '\0');
    DWORD read = 0;
    const BOOL ok = ReadFile(
        file,
        bytes.data(),
        static_cast<DWORD>(bytes.size() - 1),
        &read,
        nullptr);
    CloseHandle(file);
    if (ok == 0 || read == 0)
    {
        return fallback;
    }

    bytes.resize(read);
    const std::wstring json = mcpjson::Utf8ToWide(bytes);
    std::wstring url;
    if (ExtractJsonStringValue(json, L"client_url", &url) && !url.empty())
    {
        return url;
    }
    if (ExtractJsonStringValue(json, L"url", &url) && !url.empty())
    {
        return url;
    }
    return fallback;
}

static bool WriteMcpClientSnippetFiles(
    const std::wstring& bridge,
    const std::wstring& clientUrl,
    std::wstring* error)
{
    const std::wstring stateDir = GetKnLiveDbgUserStateDirectory();
    const std::wstring dir = stateDir + L"\\clients";
    const std::wstring endpointPath = GetMcpEndpointPath();
    bool success = true;

    if (error != nullptr)
    {
        error->clear();
    }

    if (!CreateDirectoryW(dir.c_str(), nullptr) && GetLastError() != ERROR_ALREADY_EXISTS)
    {
        success = false;
        if (error != nullptr)
        {
            *error = L"could not create client snippet directory: " + dir;
        }
    }

    auto writeText = [&success, error](
        const std::wstring& path,
        const std::wstring& text)
    {
        if (!WriteUtf8TextFile(path, text))
        {
            success = false;
            if (error != nullptr)
            {
                if (!error->empty())
                {
                    *error += L"; ";
                }
                *error += L"could not write " + path;
            }
        }
    };

    writeText(dir + L"\\claude-code-http.json", BuildMcpClaudeCodeHttpJson(clientUrl));
    writeText(dir + L"\\claude-desktop-mcp.json", BuildMcpBridgeStdioJson(bridge));
    writeText(dir + L"\\cursor-mcp.json", BuildMcpCursorHttpJson(clientUrl));
    writeText(dir + L"\\codex-config.toml.snippet", BuildMcpCodexHttpToml(clientUrl));
    writeText(dir + L"\\grok-config.toml.snippet", BuildMcpGrokHttpToml(clientUrl));
    writeText(dir + L"\\grok-http.toml.snippet", BuildMcpGrokHttpToml(clientUrl));
    writeText(dir + L"\\legacy-stdio-mcp.json", BuildMcpBridgeStdioJson(bridge));
    if (!WriteMcpLoadEnvScript(stateDir + L"\\mcp-load-env.ps1", endpointPath))
    {
        success = false;
        if (error != nullptr)
        {
            if (!error->empty())
            {
                *error += L"; ";
            }
            *error += L"could not write " + stateDir + L"\\mcp-load-env.ps1";
        }
    }

    std::wstring claudeCmd =
        L"claude mcp add-json --scope user knlivedbg " +
        PowerShellSingleQuoted(BuildMcpClaudeCodeHttpServerJson(clientUrl)) + L"\n";
    writeText(dir + L"\\claude-code-http.powershell.txt", claudeCmd);

    writeText(
        dir + L"\\codex-http.powershell.txt",
        BuildMcpCodexHttpPowerShellCommand(clientUrl) + L"\n");
    writeText(
        dir + L"\\grok-http.powershell.txt",
        BuildMcpGrokHttpPowerShellCommand(clientUrl) + L"\n");

    std::wstring claudeDesktopNote =
        L"REM Claude Desktop local MCP uses claude-desktop-mcp.json.\n"
        L"REM This bridge command is also a legacy fallback for older Claude Code builds.\n"
        L"claude mcp add --transport stdio knlivedbg -- powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
        bridge + L"\"\n";
    writeText(dir + L"\\claude-stdio.cmd.txt", claudeDesktopNote);

    std::wstring codexCmd =
        L"REM Legacy fallback only. Prefer codex-http.powershell.txt (native HTTP).\n"
        L"codex mcp add knlivedbg -- powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
        bridge + L"\"\n";
    writeText(dir + L"\\codex-stdio.cmd.txt", codexCmd);

    std::wstring grokCmd =
        L"REM Legacy fallback only. Prefer grok-http.powershell.txt (native HTTP).\n"
        L"grok mcp add knlivedbg -- powershell.exe -NoProfile -ExecutionPolicy Bypass -File \"" +
        bridge + L"\"\n";
    writeText(dir + L"\\grok-stdio.cmd.txt", grokCmd);
    return success;
}

static void PrintMcpClientSetupHelp(const std::wstring& filter)
{
    const std::wstring bridge = ResolveMcpBridgeScriptPath();
    const std::wstring endpoint = GetMcpEndpointPath();
    const std::wstring stateDir = GetKnLiveDbgUserStateDirectory();
    const std::wstring clientsDir = stateDir + L"\\clients";
    const std::wstring loadEnvPath = stateDir + L"\\mcp-load-env.ps1";
    const std::wstring clientUrl = ResolveMcpClientSetupUrl();
    const std::wstring f = ToLower(filter);
    const bool showAll = f.empty() || f == L"all" || f == L"help";
    const bool showClaudeCode = showAll || f == L"claude" || f == L"claude-code";
    const bool showClaudeDesktop = showAll || f == L"claude-desktop" ||
                                   f == L"desktop";
    const bool showCursor = showAll || f == L"cursor";
    const bool showCodex = showAll || f == L"codex";
    const bool showGrok = showAll || f == L"grok" || f == L"grok-build" || f == L"grokbuild";
    const bool showLegacy = f == L"legacy" || f == L"bridge";
    const bool recognizedFilter = showAll || showClaudeCode || showClaudeDesktop ||
                                  showCursor || showCodex || showGrok || showLegacy;

    if (!recognizedFilter)
    {
        std::wcerr << L"unknown MCP client setup filter: " << filter << L"\n";
        std::wcerr << L"valid filters: claude, claude-desktop, cursor, codex, grok, legacy, all\n";
        return;
    }

    std::wstring snippetError;
    const bool snippetsWritten = WriteMcpClientSnippetFiles(
        bridge,
        clientUrl,
        &snippetError);

    std::wcout << L"MCP client setup (native Streamable HTTP preferred)\n";
    std::wcout << L"\n";
    std::wcout << L"How it works:\n";
    std::wcout << L"  1. knkd> mcp on   prompts for a session password and listens on 0.0.0.0\n";
    std::wcout << L"  2. Client needs only IP, port, and that password\n";
    std::wcout << L"  3. Header: Authorization: Bearer <password>\n";
    std::wcout << L"  Claude Desktop local MCP uses the stdio bridge because its remote\n";
    std::wcout << L"  connectors originate in Anthropic's cloud and cannot reach loopback.\n";
    std::wcout << L"\n";
    std::wcout << L"Paths:\n";
    std::wcout << L"  endpoint : " << endpoint << L"\n";
    std::wcout << L"  url      : " << clientUrl << L"\n";
    std::wcout << L"  bridge   : " << bridge << L"\n";
    std::wcout << L"  snippets : " << clientsDir << L"\n";
    std::wcout << L"  load env : . " << PowerShellSingleQuoted(loadEnvPath) << L"\n";
    if (!snippetsWritten)
    {
        std::wcerr << L"WARNING: client setup files are incomplete: " << snippetError << L"\n";
    }
    std::wcout << L"\n";

    if (showClaudeCode)
    {
        std::wcout << L"=== Claude Code (native HTTP; preferred) ===\n";
        std::wcout << L"  PowerShell (single quotes preserve the env placeholder):\n";
        std::wcout << L"    claude mcp add-json --scope user knlivedbg "
                   << PowerShellSingleQuoted(BuildMcpClaudeCodeHttpServerJson(clientUrl)) << L"\n";
        std::wcout << L"  Verify: claude mcp list   /   use /mcp in Claude Code\n";
        std::wcout << L"  snippet: " << clientsDir << L"\\claude-code-http.json\n";
        std::wcout << L"\n";
    }

    if (showClaudeDesktop)
    {
        std::wcout << L"=== Claude Desktop local MCP (stdio bridge) ===\n";
        std::wcout << L"  Merge this into %APPDATA%\\Claude\\claude_desktop_config.json:\n";
        std::wcout << BuildMcpBridgeStdioJson(bridge);
        std::wcout << L"  Fully restart Claude Desktop after editing.\n";
        std::wcout << L"  snippet: " << clientsDir << L"\\claude-desktop-mcp.json\n";
        std::wcout << L"\n";
    }

    if (showCursor)
    {
        std::wcout << L"=== Cursor (native HTTP; preferred) ===\n";
        std::wcout << L"  Merge into user-scope ~/.cursor/mcp.json:\n";
        std::wcout << BuildMcpCursorHttpJson(clientUrl);
        std::wcout << L"  snippet: " << clientsDir << L"\\cursor-mcp.json\n";
        std::wcout << L"\n";
    }

    if (showCodex)
    {
        std::wcout << L"=== OpenAI Codex CLI / IDE (native HTTP; preferred) ===\n";
        std::wcout << L"  PowerShell:\n";
        std::wcout << L"    " << BuildMcpCodexHttpPowerShellCommand(clientUrl) << L"\n";
        std::wcout << L"  Or append TOML to %USERPROFILE%\\.codex\\config.toml:\n";
        std::wcout << BuildMcpCodexHttpToml(clientUrl);
        std::wcout << L"  Then: codex  (or restart IDE) and run /mcp to verify.\n";
        std::wcout << L"  command: " << clientsDir << L"\\codex-http.powershell.txt\n";
        std::wcout << L"  snippet: " << clientsDir << L"\\codex-config.toml.snippet\n";
        std::wcout << L"\n";
    }

    if (showGrok)
    {
        std::wcout << L"=== Grok Build (native HTTP; preferred) ===\n";
        std::wcout << L"  PowerShell (grok mcp add updates an existing entry):\n";
        std::wcout << L"    " << BuildMcpGrokHttpPowerShellCommand(clientUrl) << L"\n";
        std::wcout << L"  Or append TOML to %USERPROFILE%\\.grok\\config.toml:\n";
        std::wcout << BuildMcpGrokHttpToml(clientUrl);
        std::wcout << L"  Verify: grok mcp list   /   grok mcp doctor knlivedbg\n";
        std::wcout << L"  command: " << clientsDir << L"\\grok-http.powershell.txt\n";
        std::wcout << L"  snippet: " << clientsDir << L"\\grok-config.toml.snippet\n";
        std::wcout << L"\n";
    }

    if (showLegacy)
    {
        std::wcout << L"=== Legacy stdio-only client fallback ===\n";
        std::wcout << BuildMcpBridgeStdioJson(bridge);
        std::wcout << L"  Requires Node.js/npx and pinned mcp-remote@0.1.38.\n";
        std::wcout << L"  snippet: " << clientsDir << L"\\legacy-stdio-mcp.json\n";
        std::wcout << L"\n";
    }

    if (!FileExists(endpoint))
    {
        std::wcout << L"NOTE: endpoint file missing -- run 'mcp on' before connecting agents.\n";
    }
    std::wcout << L"Remote clients: replace 127.0.0.1 with a listen IP printed by mcp on.\n";
    std::wcout << L"Password is session-only; set it again the next time you run mcp on.\n";
    std::wcout << L"Filter: mcp client-setup [claude|claude-code|claude-desktop|cursor|codex|grok|legacy|all]\n";
}

static void HandleMcpCommand(const std::vector<std::wstring>& args)
{
    std::wstring sub = args.size() >= 2 ? ToLower(args[1]) : L"status";

    if (sub == L"help" || sub == L"?")
    {
        std::wcout << L"mcp commands:\n";
        std::wcout << L"  mcp on [port] [--allow-write] [--loopback] [--bind <addr>]\n";
        std::wcout << L"  mcp off | mcp status\n";
        std::wcout << L"  mcp client-setup [claude|claude-code|claude-desktop|cursor|codex|grok|legacy|all]\n";
        std::wcout << L"                     native HTTP setup; Desktop/legacy use the stdio bridge\n";
        std::wcout << L"  mcp endpoint         show the live endpoint file path / contents summary\n";
        std::wcout << L"\n";
        std::wcout << L"mcp on prompts for a session password (type it twice) and listens on 0.0.0.0.\n";
        std::wcout << L"Clients need IP + port + that password (Authorization: Bearer <password>).\n";
        std::wcout << L"--loopback keeps 127.0.0.1 only. --bind <ipv4> pins one address (avoid on multi-NIC).\n";
        return;
    }

    if (sub == L"client-setup" || sub == L"setup" || sub == L"connect")
    {
        const std::wstring filter = args.size() >= 3 ? args[2] : L"all";
        PrintMcpClientSetupHelp(filter);
        return;
    }

    if (sub == L"endpoint")
    {
        const std::wstring path = GetMcpEndpointPath();
        std::wcout << L"endpoint file: " << path << L"\n";
        if (!FileExists(path))
        {
            std::wcout << L"  (missing - run 'mcp on' first)\n";
            return;
        }
        // Print a short summary without dumping the full token unless running.
        HANDLE file = CreateFileW(path.c_str(), GENERIC_READ, FILE_SHARE_READ, nullptr,
                                  OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
        if (file == INVALID_HANDLE_VALUE)
        {
            std::wcout << L"  (unreadable)\n";
            return;
        }
        std::string bytes;
        bytes.resize(4096);
        DWORD read = 0;
        if (ReadFile(file, bytes.data(), static_cast<DWORD>(bytes.size() - 1), &read, nullptr) && read > 0)
        {
            bytes.resize(read);
            const std::wstring wide = mcpjson::Utf8ToWide(bytes);
            std::wstring url;
            std::wstring remoteUrl;
            std::wstring clientUrl;
            std::wstring tokenSource;
            std::wstring port;
            std::wstring write;
            if (!ExtractJsonStringValue(wide, L"url", &url) ||
                !ExtractJsonStringValue(wide, L"token_source", &tokenSource) ||
                !ExtractJsonScalarValue(wide, L"port", &port) ||
                !ExtractJsonScalarValue(wide, L"write", &write))
            {
                std::wcout << L"  (invalid endpoint descriptor)\n";
            }
            else
            {
                ExtractJsonStringValue(wide, L"remote_url", &remoteUrl);
                ExtractJsonStringValue(wide, L"client_url", &clientUrl);
                std::wcout << L"  url         : " << url << L"\n";
                if (!remoteUrl.empty())
                {
                    std::wcout << L"  remote_url  : " << remoteUrl << L"\n";
                }
                std::wcout << L"  client_url  : " << clientUrl << L"\n";
                std::wcout << L"  password    : <redacted, session-only>\n";
                std::wcout << L"  auth        : " << tokenSource << L"\n";
                std::wcout << L"  port        : " << port << L"\n";
                std::wcout << L"  write       : " << write << L"\n";
            }
        }
        CloseHandle(file);
        std::wcout << L"bridge: " << ResolveMcpBridgeScriptPath() << L"\n";
        return;
    }

    if (sub == L"on" || sub == L"start")
    {
        if (g_McpServer.IsRunning())
        {
            std::wcout << L"MCP server is already running on port " << g_McpServer.Port() << L"\n";
            return;
        }

        McpServerConfig config;
        for (size_t i = 2; i < args.size(); ++i)
        {
            if (args[i] == L"--allow-write" || args[i] == L"allow-write")
            {
                config.AllowWrite = true;
            }
            else if (args[i] == L"--loopback")
            {
                config.BindAddress = L"loopback";
            }
            else if (args[i] == L"--bind")
            {
                if (i + 1 < args.size())
                {
                    config.BindAddress = args[i + 1];
                    ++i;
                }
            }
            else if (args[i].rfind(L"--bind=", 0) == 0)
            {
                config.BindAddress = args[i].substr(7);
            }
            else if (args[i] == L"--token" || args[i] == L"--new-token" ||
                     args[i].rfind(L"--token=", 0) == 0)
            {
                std::wcerr << L"mcp on no longer uses persisted tokens. "
                           << L"Set a session password at the prompt.\n";
                return;
            }
            else
            {
                unsigned long parsed = wcstoul(args[i].c_str(), nullptr, 10);
                if (parsed > 0 && parsed < 65536)
                {
                    config.Port = static_cast<uint16_t>(parsed);
                }
            }
        }

        config.BindAddress = NormalizeMcpBindAddress(config.BindAddress);
        if (!IsMcpWildcardBind(config.BindAddress) &&
            !IsMcpLoopbackBind(config.BindAddress) &&
            !IsMcpConcreteIpv4Bind(config.BindAddress))
        {
            std::wcerr << L"mcp start failed: --bind must be 0.0.0.0, loopback, or an IPv4 address\n";
            return;
        }
        config.AuditPath = GetExecutableDirectory() + L"\\.kn-live-dbg\\mcp-audit-" +
                           std::to_wstring(config.Port) + L".jsonl";

        std::wstring passwordError;
        if (!PromptMcpSessionPassword(&config.Password, &passwordError))
        {
            std::wcerr << L"mcp start failed: " << passwordError << L"\n";
            return;
        }

        std::wstring startError;
        if (!g_McpServer.Start(config, &startError))
        {
            ClearMcpEndpointSecrets();
            SecureClearWString(&config.Password);
            std::wcerr << L"mcp start failed: " << startError << L"\n";
            return;
        }

        const bool wildcardBound = g_McpServer.WildcardBound();
        const bool networkExposed = g_McpServer.IsNetworkExposed();
        const std::wstring loopUrl =
            L"http://127.0.0.1:" + std::to_wstring(g_McpServer.Port()) + L"/mcp";

        std::vector<McpListenAddress> listenAddresses;
        CollectMcpListenAddresses(&listenAddresses);
        std::vector<std::wstring> listenIps;
        std::wstring firstLanIp;
        for (const McpListenAddress& address : listenAddresses)
        {
            listenIps.push_back(address.Ip);
            if (firstLanIp.empty() && !address.Loopback && !address.LinkLocal)
            {
                firstLanIp = address.Ip;
            }
        }

        std::wstring remoteUrl;
        if (networkExposed)
        {
            const std::wstring remoteHost = !firstLanIp.empty()
                ? firstLanIp
                : (wildcardBound ? L"<this-host-ip>" : g_McpServer.BindAddress());
            remoteUrl = L"http://" + remoteHost + L":" +
                std::to_wstring(g_McpServer.Port()) + L"/mcp";
        }

        std::wstring endpointPath;
        std::wstring endpointError;
        if (!WriteMcpEndpointFile(
                loopUrl,
                remoteUrl,
                g_McpServer.Password(),
                g_McpServer.TokenSource(),
                g_McpServer.Port(),
                config.AllowWrite,
                networkExposed,
                g_McpServer.BindAddress(),
                listenIps,
                &endpointPath,
                &endpointError))
        {
            StopMcpServer();
            SecureClearWString(&config.Password);
            std::wcerr << L"mcp start failed: endpoint persistence failed: "
                       << endpointError << L"\n";
            return;
        }

        const std::wstring clientStateDir = GetKnLiveDbgUserStateDirectory();
        const std::wstring clientsDir = clientStateDir + L"\\clients";
        const std::wstring loadEnvPath = clientStateDir + L"\\mcp-load-env.ps1";
        std::wstring snippetError;
        const bool snippetsWritten = WriteMcpClientSnippetFiles(
            ResolveMcpBridgeScriptPath(),
            loopUrl,
            &snippetError);

        const wchar_t* modeText = L"loopback";
        if (wildcardBound)
        {
            modeText = L"all interfaces";
        }
        else if (networkExposed)
        {
            modeText = L"selected addresses";
        }
        std::wcout << L"MCP server started (" << modeText << L" Streamable HTTP).\n";
        std::wcout << L"  listen   : " << g_McpServer.BindAddress() << L":"
                   << g_McpServer.Port() << L"\n";
        std::wcout << L"  port     : " << g_McpServer.Port() << L"\n";
        std::wcout << L"  write    : "
                   << (config.AllowWrite ? L"ENABLED (lab mode)" : L"disabled (read-only)")
                   << L"\n";
        std::wcout << L"  audit    : " << g_McpServer.AuditPath() << L"\n";
        std::wcout << L"\n";
        PrintConsoleOnly(
            L"  password : " + g_McpServer.Password() +
            L"  (session only, not written to the log)\n");
        std::wcout << L"  Client connection (IP + port + password):\n";
        std::wcout << L"    URL    : http://<ip>:" << g_McpServer.Port() << L"/mcp\n";
        PrintConsoleOnly(
            L"    Header : Authorization: Bearer " + g_McpServer.Password() + L"\n");
        std::wcout << L"\n";
        std::wcout << L"  Listening prefixes:\n";
        const std::vector<std::wstring> registeredHosts = g_McpServer.RegisteredHosts();
        if (registeredHosts.empty())
        {
            std::wcout << L"    (none)\n";
        }
        for (const std::wstring& host : registeredHosts)
        {
            if (host == L"+" || host == L"*")
            {
                std::wcout << L"    +  (all interfaces)\n";
            }
            else
            {
                std::wcout << L"    " << host << L"\n";
            }
        }
        if (wildcardBound || networkExposed)
        {
            std::wcout << L"\n";
            std::wcout << L"  Addresses on this host (pick one the client can reach):\n";
            for (const McpListenAddress& address : listenAddresses)
            {
                std::wcout << L"    " << address.Ip;
                const size_t ipLen = address.Ip.size();
                for (size_t pad = ipLen; pad < 16; ++pad)
                {
                    std::wcout << L" ";
                }
                if (address.Loopback)
                {
                    std::wcout << L"loopback\n";
                }
                else if (address.LinkLocal)
                {
                    std::wcout << L"link-local  " << address.AdapterName << L"\n";
                }
                else
                {
                    std::wcout << address.AdapterName << L"\n";
                }
            }
        }
        else
        {
            std::wcout << L"  loopback only: use http://127.0.0.1:"
                       << g_McpServer.Port() << L"/mcp\n";
        }
        if (IsMcpWildcardBind(g_McpServer.BindAddress()) && !wildcardBound)
        {
            std::wcout << L"  WARNING: all-interface prefix (+) was not reserved; "
                       << L"listening only on the prefixes above.\n";
        }
        std::wcout << L"\n";
        if (!snippetsWritten)
        {
            std::wcerr << L"  WARNING: client setup files are incomplete: "
                       << snippetError << L"\n";
        }
        std::wcout << L"  Local same-box snippets: " << clientsDir << L"\n";
        std::wcout << L"  Desktop/legacy bridge : " << endpointPath << L"\n";
        std::wcout << L"  load env (same box)   : . "
                   << PowerShellSingleQuoted(loadEnvPath) << L"\n";
        if (networkExposed)
        {
            std::wcout << L"  WARNING: this elevated kernel endpoint is reachable on the bound addresses.\n";
            std::wcout << L"           Restrict inbound TCP "
                       << g_McpServer.Port()
                       << L" with a firewall rule on a trusted lab segment.\n";
        }
        if (config.AllowWrite)
        {
            std::wcout << L"  WARNING: write tools are open. Take a VM snapshot before LLM-driven write sessions.\n";
        }
        std::wcout << L"  the engine loop starts now; type 'off' + Enter here to stop.\n";
        SecureClearWString(&config.Password);
        return;
    }

    if (sub == L"off" || sub == L"stop")
    {
        if (!g_McpServer.IsRunning())
        {
            std::wcout << L"MCP server is not running\n";
            return;
        }
        StopMcpServer();
        std::wcout << L"MCP server stopped\n";
        return;
    }

    // status
    if (g_McpServer.IsRunning())
    {
        std::wcout << L"MCP server: running port=" << g_McpServer.Port()
                   << L" bind=" << g_McpServer.BindAddress()
                   << L" wildcard=" << (g_McpServer.WildcardBound() ? L"on" : L"off")
                   << L" write=" << (g_McpServer.AllowWrite() ? L"on" : L"off")
                   << L" auth=password\n";
        std::wcout << L"  endpoint: " << GetMcpEndpointPath() << L"\n";
        std::wcout << L"  bridge  : " << ResolveMcpBridgeScriptPath() << L"\n";
        std::wcout << L"  clients : IP + port + session password\n";
    }
    else
    {
        std::wcout << L"MCP server: stopped.\n";
        std::wcout << L"  usage: mcp on [port] [--allow-write] [--loopback] [--bind <addr>]\n";
        std::wcout << L"         mcp off | mcp status | mcp client-setup | mcp endpoint | mcp help\n";
        std::wcout << L"  tip  : mcp on prompts for a session password and listens on 0.0.0.0\n";
    }
}

static bool PromptRemoteSessionPassword(std::wstring* password, std::wstring* error)
{
    bool ok = false;
    std::wstring first;
    std::wstring second;
    do
    {
        if (password == nullptr)
        {
            if (error != nullptr)
            {
                *error = L"invalid remote password output";
            }
            break;
        }
        std::wcout << L"Set a temporary remote password for this session.\n";
        std::wcout << L"Clients connect with IP, port, and this password.\n";
        std::wcout.flush();
        if (!ReadHiddenConsoleLine(L"Remote password: ", &first) ||
            !ReadHiddenConsoleLine(L"Confirm password: ", &second))
        {
            if (error != nullptr)
            {
                *error = L"remote password prompt requires an interactive console";
            }
            break;
        }
        if (first != second)
        {
            if (error != nullptr)
            {
                *error = L"remote passwords did not match";
            }
            break;
        }
        if (!knremote::SanitizeRemotePassword(first, password, error))
        {
            break;
        }
        ok = true;
    } while (false);
    SecureClearWString(&first);
    SecureClearWString(&second);
    return ok;
}

static void RunRemoteEngineLoop(
    DebuggerState& state,
    DbgEngBackend& dbgeng,
    DeviceClient& device,
    DriverService& service,
    SymbolEngine& symbols,
    AiProviderRuntime& ai,
    AiPlanState& aiState)
{
    std::wcout << L"[remote] engine active: " << g_RemoteServer.BindAddress()
               << L":" << g_RemoteServer.Port()
               << L"  -- type 'off' then Enter to stop\n";

    std::atomic<bool> controlStop{ false };
    std::atomic<bool> statusRequested{ false };
    std::atomic<bool> writeOffRequested{ false };
    std::thread reader([&controlStop, &statusRequested, &writeOffRequested]()
    {
        while (!controlStop.load())
        {
            std::wstring line;
            if (!McpReadConsoleLine(&line))
            {
                break;
            }
            std::wstring lowered = ToLower(line);
            if (lowered == L"off" || lowered == L"remote off" ||
                lowered == L"q" || lowered == L"quit" || lowered == L"exit" ||
                lowered == L"unload")
            {
                if (lowered == L"q" || lowered == L"quit" || lowered == L"exit" ||
                    lowered == L"unload")
                {
                    g_StopRequested = true;
                }
                g_RemoteServer.RequestStop();
                break;
            }
            else if (lowered == L"disconnect" || lowered == L"remote disconnect")
            {
                g_RemoteServer.DisconnectSession();
            }
            else if (lowered == L"status" || lowered == L"remote status")
            {
                statusRequested.store(true);
            }
            else if (lowered == L"write off")
            {
                writeOffRequested.store(true);
                SetEvent(g_RemoteServer.WriteOffEvent());
            }
        }
    });

    while (g_RemoteServer.IsRunning() && !g_StopRequested)
    {
        WaitForSingleObject(g_RemoteServer.JobReadyEvent(), 200);

        if (writeOffRequested.exchange(false))
        {
            std::wstring writeError;
            device.SetWriteMode(false, &writeError);
            g_RemoteServer.SetHelloWriteMode(false);
            ResetEvent(g_RemoteServer.WriteOffEvent());
            std::wcout << L"[remote] write off\n";
        }

        if (statusRequested.exchange(false))
        {
            std::wcout << L"[remote] running bind=" << g_RemoteServer.BindAddress()
                       << L":" << g_RemoteServer.Port()
                       << L" peer=" << g_RemoteServer.PeerIp()
                       << L"\n";
        }

        std::shared_ptr<RemoteJob> job;
        while ((job = g_RemoteServer.TryPopJob()) != nullptr)
        {
            if (g_EngineTid != 0 && GetCurrentThreadId() != g_EngineTid)
            {
                RemoteEngineResult bad;
                bad.IsError = true;
                bad.Code = L"denied";
                bad.Stderr = L"engine thread mismatch";
                try
                {
                    job->ResultPromise.set_value(bad);
                }
                catch (...)
                {
                }
                continue;
            }
            RemoteEngineResult dispatchResult;
            if (job->Cancelled && job->Cancelled->load())
            {
                dispatchResult.IsError = true;
                dispatchResult.Code = L"denied";
                dispatchResult.Stderr = L"cancelled";
            }
            else
            {
                std::wstring denyReason;
                if (IsRemoteDeniedCommandLine(job->Line, &denyReason))
                {
                    dispatchResult.IsError = true;
                    dispatchResult.Code = L"denied";
                    dispatchResult.Stderr = L"denied: " + denyReason;
                }
                else if (IsRemoteAddressOnlyEnter(job->Line))
                {
                    dispatchResult.IsError = true;
                    dispatchResult.Code = L"denied";
                    dispatchResult.Stderr = L"supply values on the command line";
                }
                else
                {
                    std::vector<std::wstring> args = Split(job->Line);
                    struct RemoteOriginScope
                    {
                        RemoteOriginScope()
                        {
                            g_RemoteOriginActive.store(true);
                        }
                        ~RemoteOriginScope()
                        {
                            g_RemoteOriginActive.store(false);
                        }
                    } originScope;
                    CommandExecutionResult executed = ExecuteCommandWithTranscript(
                        args,
                        job->Line,
                        L"remote",
                        state,
                        dbgeng,
                        device,
                        service,
                        symbols,
                        ai,
                        aiState,
                        false);
                    dispatchResult.Stdout = executed.Output;
                    dispatchResult.Stderr = executed.Error;
                    dispatchResult.KeepRunning = executed.KeepRunning;
                    dispatchResult.IsError = false;
                }
            }

            try
            {
                job->ResultPromise.set_value(dispatchResult);
            }
            catch (...)
            {
            }

            std::wstring audit = L"{";
            audit += L"\"ts\":" + std::to_wstring(knremote::UnixTimeMs());
            audit += L",\"peerIp\":" + knremote::Quote(g_RemoteServer.PeerIp());
            audit += L",\"origin\":\"remote\"";
            audit += L",\"command\":" + knremote::Quote(job->Line.substr(0, 512));
            audit += L",\"decision\":" + knremote::Quote(dispatchResult.IsError ? L"deny" : L"allow");
            if (dispatchResult.IsError)
            {
                audit += L",\"deniedReason\":" + knremote::Quote(dispatchResult.Code);
            }
            audit += L"}";
            g_RemoteServer.AppendAuditLine(audit);
        }
    }

    controlStop.store(true);
    CancelSynchronousIo(reader.native_handle());
    if (reader.joinable())
    {
        reader.join();
    }
    g_RemoteServer.Stop();
    std::wcout << L"[remote] engine stopped\n";
}

static void HandleRemoteCommand(
    const std::vector<std::wstring>& args,
    DebuggerState& state,
    DeviceClient& device)
{
    std::wstring sub = args.size() >= 2 ? ToLower(args[1]) : L"status";

    if (sub == L"help" || sub == L"?")
    {
        PrintSessionHelp(L"remote");
        return;
    }

    if (sub == L"off" || sub == L"stop")
    {
        if (!g_RemoteServer.IsRunning())
        {
            std::wcout << L"remote server is not running\n";
            return;
        }
        g_RemoteServer.RequestStop();
        return;
    }

    if (sub == L"disconnect")
    {
        g_RemoteServer.DisconnectSession();
        std::wcout << L"remote session disconnected\n";
        return;
    }

    if (sub == L"on" || sub == L"start")
    {
        if (g_RemoteServer.IsRunning())
        {
            std::wcout << L"remote server is already running on port "
                       << g_RemoteServer.Port() << L"\n";
            return;
        }
        if (g_McpServer.IsRunning())
        {
            std::wcerr << L"remote on failed: MCP server is running (listen XOR)\n";
            return;
        }

        RemoteServerConfig config;
        config.Port = knremote::kDefaultPort;
        config.BindAddress = L"0.0.0.0";
        for (size_t i = 2; i < args.size(); ++i)
        {
            if (args[i] == L"--loopback")
            {
                config.BindAddress = L"127.0.0.1";
            }
            else if (args[i] == L"--bind" && i + 1 < args.size())
            {
                config.BindAddress = args[++i];
            }
            else if (args[i] == L"--peer" && i + 1 < args.size())
            {
                config.Peer = args[++i];
            }
            else
            {
                unsigned long parsed = wcstoul(args[i].c_str(), nullptr, 10);
                if (parsed > 0 && parsed < 65536)
                {
                    config.Port = static_cast<uint16_t>(parsed);
                }
            }
        }

        if (config.Port == knremote::kMcpPort)
        {
            std::wcerr << L"remote on failed: MCP port; use 51767\n";
            return;
        }

        config.BindAddress = knremote::NormalizeBindAddress(config.BindAddress);
        config.AuditPath = GetExecutableDirectory() + L"\\.kn-live-dbg\\remote-audit-" +
                           std::to_wstring(config.Port) + L".jsonl";
        config.AddFirewall = !knremote::IsLoopbackBind(config.BindAddress);

        std::wstring passwordError;
        if (!PromptRemoteSessionPassword(&config.Password, &passwordError))
        {
            std::wcerr << L"remote on failed: " << passwordError << L"\n";
            return;
        }

        DriverSessionStatus session = {};
        std::wstring sessionError;
        if (device.IsOpen())
        {
            device.QuerySessionStatus(&session, &sessionError);
        }
        config.Hello.Hostname.clear();
        config.Hello.Os = L"Windows";
        config.Hello.Abi = KNDBG_ABI_VERSION;
        config.Hello.WriteMode = (session.Flags & KNDBG_SESSION_FLAG_WRITE_ENABLED) != 0;
        config.Hello.Cloak = state.CloakActive;

        std::wstring startError;
        if (!g_RemoteServer.Start(config, &startError))
        {
            SecureClearWString(&config.Password);
            std::wcerr << L"remote on failed: " << startError << L"\n";
            return;
        }
        SecureClearWString(&config.Password);

        std::wcout << L"[remote] listen " << g_RemoteServer.BindAddress()
                   << L":" << g_RemoteServer.Port()
                   << L" cleartext=true\n";
        if (!g_RemoteServer.FirewallWarning().empty())
        {
            std::wcout << L"[remote] warning: " << g_RemoteServer.FirewallWarning()
                       << L"\n";
        }
        if (!g_RemoteServer.IsLoopbackOnly())
        {
            std::wcout << L"[remote] warning: cleartext kernel-command traffic on the LAN\n";
            std::vector<McpListenAddress> addresses;
            CollectMcpListenAddresses(&addresses);
            for (const McpListenAddress& addr : addresses)
            {
                std::wcout << L"  " << addr.Ip;
                if (!addr.AdapterName.empty())
                {
                    std::wcout << L"  " << addr.AdapterName;
                }
                std::wcout << L"\n";
            }
            std::wcout << L"  client: KnLiveDbg.exe --connect <ipv4>:"
                       << g_RemoteServer.Port() << L"\n";
        }
        else
        {
            std::wcout << L"  client: KnLiveDbg.exe --connect 127.0.0.1:"
                       << g_RemoteServer.Port() << L"\n";
        }
        return;
    }

    if (g_RemoteServer.IsRunning())
    {
        std::wcout << L"remote server: running bind=" << g_RemoteServer.BindAddress()
                   << L":" << g_RemoteServer.Port()
                   << L" peer=" << g_RemoteServer.PeerIp() << L"\n";
        std::wcout << L"  audit: " << g_RemoteServer.AuditPath() << L"\n";
    }
    else
    {
        std::wcout << L"remote server: stopped.\n";
        std::wcout << L"  usage: remote on [port] [--loopback] [--bind <ipv4>] [--peer <ipv4>]\n";
        std::wcout << L"  client: KnLiveDbg.exe --connect <ipv4>:51767\n";
    }
}

int wmain(int argc, wchar_t** argv)
{
    // Permanently install the tee buffer in front of std::wcout. Must
    // happen before any ScopedWideStreamCapture (i.e. before any
    // command is dispatched) so that "log enable" only needs to
    // attach a file sink at runtime, not swap rdbufs from inside a
    // capture's chain (which would silently drop the tee on the next
    // capture's destructor).
    InstallOutputTee();
    knremote::EnableVirtualTerminalConsoles();
    CommandRegistry::SetColorPrinter(PrintCommandRegistryColoredText);

    if (argc >= 2 && ToLower(argv[1]) == L"--self-test")
    {
        if (argc >= 3 && ToLower(argv[2]) == L"timeline")
        {
            return RunTimelineSelfTest();
        }
        if (argc >= 3 && ToLower(argv[2]) == L"mcp-tools")
        {
            return RunMcpToolCatalogSelfTest();
        }
        if (argc >= 3 && ToLower(argv[2]) == L"remote-protocol")
        {
            return RunRemoteProtocolSelfTest();
        }
        if (argc >= 3 && ToLower(argv[2]) == L"connect-argv")
        {
            return RunRemoteConnectArgvSelfTest();
        }
        if (argc >= 3 && ToLower(argv[2]) == L"console")
        {
            return RunConsoleSurfaceSelfTest();
        }
        if (argc >= 4 &&
            ToLower(argv[2]) ==
                L"cloudfiles-query")
        {
            return RunCloudFileQuerySelfTest(
                argv[3]);
        }
        if (argc >= 3 &&
            ToLower(argv[2]) ==
                L"minifilter-attachments-query")
        {
            return
                RunMinifilterAttachmentQuerySelfTest();
        }
        if (argc >= 3 && ToLower(argv[2]) == L"all")
        {
            int timelineExit = RunTimelineSelfTest();
            int mcpExit = RunMcpToolCatalogSelfTest();
            int consoleExit = RunConsoleSurfaceSelfTest();
            return (timelineExit == 0 && mcpExit == 0 && consoleExit == 0) ? 0 : 1;
        }

        std::wcerr << L"usage: KnLiveDbg.exe --self-test timeline|mcp-tools|console|cloudfiles-query <path>|minifilter-attachments-query|remote-protocol|connect-argv|all\n";
        return 2;
    }

    if (argc >= 2 && ToLower(argv[1]) == L"--connect")
    {
        return RemoteClientMain(argc, argv);
    }

    if (HasUnknownControllerArgv(argc, argv))
    {
        std::wcerr << L"unknown argument. controller accepts --cloak* only.\n";
        return 2;
    }

    CloakArgs cloakArgs = {};
    if (!ParseCloakArgs(argc, argv, &cloakArgs))
    {
        std::wcerr << L"usage: KnLiveDbg.exe [--cloak | --cloak-resume <session> | --cloak-cleanup <session>]\n";
        return 2;
    }

    if (cloakArgs.Mode == CloakMode::Cleanup)
    {
        return RunCloakCleanup(cloakArgs.SessionPath);
    }

    if (cloakArgs.Mode == CloakMode::Launch)
    {
        if (!IsElevated())
        {
            std::wcerr << L"KnLiveDbg --cloak must run elevated.\n";
            return 1;
        }

        CloakSession session = {};
        std::wstring cloakError;
        if (!BuildCloakSession(&session, &cloakError) ||
            !SaveCloakSession(session, &cloakError) ||
            !LaunchCloakChild(session, argc, argv, &cloakError))
        {
            std::wcerr << L"cloak launch failed: " << cloakError << L"\n";
            CleanupCloakArtifacts(session, false, nullptr);
            return 1;
        }

        std::wcout << L"cloak: launched " << session.ServiceName
                   << L" in a new console\n";
        return 0;
    }

    int exitCode = 1;
    DebuggerState state = {};
    state.NumberBase = 16;
    state.Quiet = false;
    state.MainDriverCleanupRequested = false;
    state.MainDriverUnloaded = false;
    state.ProbeDriverCleanupRequested = false;
    state.ProbeDriverUnloaded = false;
    state.ByovdFixtureCleanupRequested = false;
    state.ByovdFixtureUnloaded = false;
    state.CloakActive = false;
    state.HasSnapshotBaseline = false;
    state.SnapshotBaseline = SnapshotDocument{};
    state.SnapshotBaselineJsonPath.clear();
    state.SnapshotBaselineReportPath.clear();
    state.Backend = DebuggerState::BackendMode::Auto;

    if (cloakArgs.Mode == CloakMode::Resume)
    {
        std::wstring cloakError;
        if (!LoadCloakSession(cloakArgs.SessionPath, &state.Cloak, &cloakError))
        {
            std::wcerr << L"cloak resume failed: " << cloakError << L"\n";
            return 1;
        }
        state.CloakActive = true;
    }

    DriverService service(
        state.CloakActive ? state.Cloak.ServiceName.c_str() : KNDBG_SERVICE_NAME,
        state.CloakActive ? state.Cloak.DisplayName.c_str() : KNDBG_DISPLAY_NAME);
    DeviceClient device;
    SymbolEngine symbols;
    DbgEngBackend dbgeng;
    AiProviderRuntime ai;
    AiPlanState aiState = {};
    std::wstring error;

    do
    {
        DuplicateHandle(
            GetCurrentProcess(),
            GetCurrentThread(),
            GetCurrentProcess(),
            &g_MainThreadHandle,
            0,
            FALSE,
            DUPLICATE_SAME_ACCESS);
        g_EngineTid = GetCurrentThreadId();
        SetConsoleCtrlHandler(ConsoleHandler, TRUE);

        PrintLifecycleHeader(L"KnLiveDbg launch", L"preflight checks");
        PrintLifecycleStep(L"elevation", L"administrator token");
        if (!IsElevated())
        {
            PrintLifecycleFail(L"elevation", L"administrator privileges are required");
            std::wcerr << L"KnLiveDbg must run elevated to install and load the driver.\n";
            break;
        }
        PrintLifecycleOk(L"elevation", L"administrator");

        if (state.CloakActive)
        {
            const std::wstring cloakMutex = L"Global\\" + state.Cloak.ServiceName + L".s";
            PrintLifecycleStep(L"single instance", cloakMutex);
            if (!AcquireNamedMutex(cloakMutex.c_str(), &g_CloakMutexHandle, &error))
            {
                PrintLifecycleFail(L"single instance", error);
                std::wcerr << error << L"\n";
                break;
            }
            if (!AcquireSingleInstanceLock(&error))
            {
                PrintLifecycleFail(L"single instance", error);
                std::wcerr << error << L"\n";
                break;
            }
            PrintLifecycleOk(L"single instance", L"cloak+session");
            SetConsoleTitleW(state.Cloak.ServiceName.c_str());
        }
        else
        {
            PrintLifecycleStep(L"single instance", L"Global\\KnLiveDbg.Exe.SingleInstance");
            if (!AcquireSingleInstanceLock(&error))
            {
                PrintLifecycleFail(L"single instance", error);
                std::wcerr << error << L"\n";
                break;
            }
            PrintLifecycleOk(L"single instance", L"acquired");
        }

        state.MainDriverCleanupRequested = true;

        std::wstring exeDir = GetExecutableDirectory();
        PrintLifecycleStep(L"symbol runtime consent", L"symsrv.yes");
        std::wstring symsrvConsentStatus;
        if (!EnsureSymsrvConsentFile(exeDir, &symsrvConsentStatus, &error))
        {
            PrintLifecycleWarn(L"symbol runtime consent", error);
            std::wcerr << L"symsrv consent warning: " << error << L"\n";
        }
        else
        {
            PrintLifecycleOk(L"symbol runtime consent", symsrvConsentStatus);
        }

        PrintLifecycleStep(L"register DIA", L"msdia COM");
        std::wstring diaStatus;
        if (!EnsureDiaRegistration(exeDir, &diaStatus, &error))
        {
            PrintLifecycleWarn(L"register DIA", error);
            std::wcerr << L"DIA registration warning: " << error << L"\n";
        }
        else
        {
            PrintLifecycleOk(L"register DIA", diaStatus);
        }

        STARTUP_SYMBOL_PATH_INFO startupSymbolPath = BuildStartupSymbolPath(symbols.SymbolPath(), exeDir);
        if (!startupSymbolPath.Path.empty())
        {
            symbols.SetSymbolPath(startupSymbolPath.Path);
        }

        std::wstring driverPath = state.CloakActive
            ? state.Cloak.CopiedSysPath
            : (exeDir + L"\\KnLiveDbg.sys");
        const std::wstring userDeviceName = state.CloakActive
            ? state.Cloak.UserDeviceName
            : KNDBG_USER_DEVICE_NAME;

        if (!LoadDriverServiceWithUx(
                service,
                L"Main driver startup",
                driverPath,
                &error,
                state.CloakActive ? &state.Cloak : nullptr))
        {
            std::wcerr << L"driver load failed\n";
            break;
        }

        PrintLifecycleStep(L"open device", userDeviceName);
        for (int attempt = 0; attempt < 50; ++attempt)
        {
            if (device.Open(userDeviceName, &error))
            {
                break;
            }

            Sleep(100);
        }

        if (!device.IsOpen())
        {
            PrintLifecycleFail(L"open device", error);
            std::wcerr << L"device open failed: " << error << L"\n";
            break;
        }
        PrintLifecycleOk(L"open device", L"ready");

        PrintLifecycleStep(L"verify driver ABI", L"IOCTL_KNDBG_GET_VERSION");
        if (!device.QueryVersion(&error))
        {
            PrintLifecycleFail(L"verify driver ABI", error);
            std::wcerr << L"driver ABI check failed: " << error << L"\n";
            break;
        }
        PrintLifecycleOk(L"verify driver ABI", L"compatible");

        PrintLifecycleStep(L"symbol search path", L"EXE directory tree");
        if (startupSymbolPath.Truncated)
        {
            PrintLifecycleWarn(L"symbol search path", L"local dirs=" + std::to_wstring(startupSymbolPath.LocalDirectoryCount) + L" truncated");
        }
        else
        {
            PrintLifecycleOk(L"symbol search path", L"local dirs=" + std::to_wstring(startupSymbolPath.LocalDirectoryCount));
        }

        PrintLifecycleStep(L"symbol cache", L"EXE symbols directory");
        if (!startupSymbolPath.SymbolCacheReady)
        {
            std::wstring cacheWarning = startupSymbolPath.SymbolCacheError.empty() ?
                L"not configured" : startupSymbolPath.SymbolCacheError;
            PrintLifecycleWarn(L"symbol cache", cacheWarning);
            std::wcerr << L"symbol cache warning: " << cacheWarning << L"\n";
        }
        else
        {
            PrintLifecycleOk(L"symbol cache", startupSymbolPath.SymbolCachePath);
        }

        PrintLifecycleStep(L"initialize symbols", L"DbgHelp/DIA");
        if (!symbols.Initialize(symbols.SymbolPath(), &error))
        {
            PrintLifecycleWarn(L"initialize symbols", error);
            std::wcerr << L"symbol init warning: " << error << L"\n";
        }
        else if (!symbols.LoadKernelModules(&error))
        {
            PrintLifecycleWarn(L"load kernel modules", error);
            std::wcerr << L"symbol reload warning: " << error << L"\n";
        }
        else
        {
            PrintLifecycleOk(L"initialize symbols", L"modules=" + std::to_wstring(symbols.Modules().size()));

            PrintLifecycleStep(L"download kernel symbols", L"nt PDB");
            size_t kernelSymbolCount = 0;
            std::wstring preloadError;
            if (symbols.PreloadKernelSymbols(&kernelSymbolCount, &preloadError))
            {
                PrintLifecycleOk(L"download kernel symbols", L"loaded=" + std::to_wstring(kernelSymbolCount));
            }
            else
            {
                PrintLifecycleWarn(L"download kernel symbols", preloadError);
                std::wcerr << L"kernel symbol preload warning: " << preloadError << L"\n";
            }
        }

        std::wstring dotEnvError;
        ai.LoadDotEnvFiles(BuildDotEnvSearchPaths(exeDir), nullptr, &dotEnvError);

        PrintStartupTui(state, service, device, symbols, ai);

        while (!g_StopRequested)
        {
            if (g_RemoteServer.IsRunning())
            {
                RunRemoteEngineLoop(state, dbgeng, device, service, symbols, ai, aiState);
                continue;
            }
            if (g_McpServer.IsRunning())
            {
                RunMcpEngineLoop(state, dbgeng, device, service, symbols, ai, aiState);
                continue;
            }

            std::wstring line;
            if (!ReadInteractiveCommandLine(L"knkd> ", state.CommandHistory, &line))
            {
                break;
            }

            std::vector<std::wstring> args = Split(line);
            if (args.empty())
            {
                continue;
            }

            AddCommandHistory(&state, line);

            CommandExecutionResult commandResult = ExecuteCommandWithTranscript(
                args,
                line,
                L"operator",
                state,
                dbgeng,
                device,
                service,
                symbols,
                ai,
                aiState);
            if (!commandResult.KeepRunning)
            {
                break;
            }
        }

        exitCode = 0;
    } while (false);

    StopMcpServer();
    g_RemoteServer.Stop();
    StopTimelineAutoDrainWorker();
    dbgeng.Shutdown();
    bool cleanupOk = true;
    if (!CleanupByovdFixtureDriverOnExit(state))
    {
        cleanupOk = false;
    }
    if (!CleanupProbeDriverOnExit(state))
    {
        cleanupOk = false;
    }
    if (!CleanupMainDriverOnExit(state, device, service))
    {
        cleanupOk = false;
    }
    if (!cleanupOk)
    {
        exitCode = 1;
    }

    if (g_MainThreadHandle != nullptr)
    {
        CloseHandle(g_MainThreadHandle);
        g_MainThreadHandle = nullptr;
    }
    ReleaseSingleInstanceLock();

    DisableOutputLog(nullptr);
    UninstallOutputTee();

    return exitCode;
}
